(function() {
    function getSelection($row) {
        let values = $row.find(".applicableUsers").select2("val");

        if (!values || values.length === 0) {
            values = [];
        }

        return values;
    }

    function getSelectedApplicable($row) {
        const users = [];
        const groups = [];
        const multiselect = getSelection($row);

        $.each(multiselect, function(index, value) {
            const pos = value.indexOf ? value.indexOf("(group)") : -1;

            if (pos !== -1) {
                groups.push(value.substr(0, pos));
            } else {
                users.push(value);
            }
        });

        $row.find(".applicable").data("applicable-groups", groups).data("applicable-users", users);

        return {
            users,
            groups
        };
    }

    function highlightBorder($element, highlight) {
        $element.toggleClass("warning-input", highlight);
        return highlight;
    }

    function isInputValid($input) {
        const optional = $input.hasClass("optional");

        switch ($input.attr("type")) {
        case "text":
        case "password":
            if ($input.val() === "" && !optional) {
                return false;
            }

            break;
        }

        return true;
    }

    function highlightInput($input) {
        switch ($input.attr("type")) {
        case "text":
        case "password":
            return highlightBorder($input, !isInputValid($input));
        }
    }

    function initApplicableUsersMultiselect($elements, userListLimit) {
        const escapeHTML = function(text) {
            return text.toString().split("&").join("&amp;").split("<").join("&lt;").split(">").join("&gt;").split("\"").join("&quot;").split("'").join("&#039;");
        };

        if (!$elements.length) {
            return;
        }

        return $elements.select2({
            placeholder: t("files_external", "Type to select account or group."),
            allowClear: true,
            multiple: true,
            toggleSelect: true,
            dropdownCssClass: "files-external-select2",

            ajax: {
                url: OC.generateUrl("apps/files_external/applicable"),
                dataType: "json",
                quietMillis: 100,

                data: function(term, page) {
                    return {
                        pattern: term,
                        limit: userListLimit,
                        offset: userListLimit * (page - 1)
                    };
                },

                results: function(data) {
                    if (data.status === "success") {
                        const results = [];
                        let userCount = 0;

                        $.each(data.groups, function(gid, group) {
                            results.push({
                                name: gid + "(group)",
                                displayname: group,
                                type: "group"
                            });
                        });

                        $.each(data.users, function(id, user) {
                            userCount++;

                            results.push({
                                name: id,
                                displayname: user,
                                type: "user"
                            });
                        });

                        const more = userCount >= userListLimit || data.groups.length >= userListLimit;

                        return {
                            results: results,
                            more: more
                        };
                    } else
                        {}
                }
            },

            initSelection: function(element, callback) {
                const users = {};
                users["users"] = [];
                const toSplit = element.val().split(",");

                for (let i = 0; i < toSplit.length; i++) {
                    users["users"].push(toSplit[i]);
                }

                $.ajax(OC.generateUrl("displaynames"), {
                    type: "POST",
                    contentType: "application/json",
                    data: JSON.stringify(users),
                    dataType: "json"
                }).done(function(data) {
                    const results = [];

                    if (data.status === "success") {
                        $.each(data.users, function(user, displayname) {
                            if (displayname !== false) {
                                results.push({
                                    name: user,
                                    displayname: displayname,
                                    type: "user"
                                });
                            }
                        });

                        callback(results);
                    } else
                        {}
                });
            },

            id: function(element) {
                return element.name;
            },

            formatResult: function(element) {
                const $result = $(
                    "<span><div class=\"avatardiv\"></div><span>" + escapeHTML(element.displayname) + "</span></span>"
                );

                const $div = $result.find(".avatardiv").attr("data-type", element.type).attr("data-name", element.name).attr("data-displayname", element.displayname);

                if (element.type === "group") {
                    const url = OC.imagePath("core", "actions/group");
                    $div.html("<img width=\"32\" height=\"32\" src=\"" + url + "\">");
                }

                return $result.get(0).outerHTML;
            },

            formatSelection: function(element) {
                if (element.type === "group") {
                    return ("<span title=\"" + escapeHTML(element.name) + "\" class=\"group\">" + escapeHTML(element.displayname + " " + t("files_external", "(Group)")) + "</span>");
                } else {
                    return ("<span title=\"" + escapeHTML(element.name) + "\" class=\"user\">" + escapeHTML(element.displayname) + "</span>");
                }
            },

            escapeMarkup: function(m) {
                return m;
            }
        }).on("select2-loaded", function() {
            $.each($(".avatardiv"), function(i, div) {
                const $div = $(div);

                if ($div.data("type") === "user") {
                    $div.avatar($div.data("name"), 32);
                }
            });
        }).on("change", function(event) {
            highlightBorder(
                $(event.target).closest(".applicableUsersContainer").find(".select2-choices"),
                !event.val.length
            );
        });
    }

    const StorageConfig = function(id) {
        this.id = id;
        this.backendOptions = {};
    };

    StorageConfig.Status = {
        IN_PROGRESS: -1,
        SUCCESS: 0,
        ERROR: 1,
        INDETERMINATE: 2
    };

    StorageConfig.Visibility = {
        NONE: 0,
        PERSONAL: 1,
        ADMIN: 2,
        DEFAULT: 3
    };

    StorageConfig.prototype = {
        _url: null,
        id: null,
        mountPoint: "",
        backend: null,
        authMechanism: null,
        backendOptions: null,
        mountOptions: null,

        save: function(options) {
            let url = OC.generateUrl(this._url);
            let method = "POST";

            if (_.isNumber(this.id)) {
                method = "PUT";

                url = OC.generateUrl(this._url + "/{id}", {
                    id: this.id
                });
            }

            window.OC.PasswordConfirmation.requirePasswordConfirmation(() => this._save(method, url, options), options.error);
        },

        _save: function(method, url, options) {
            self = this;

            $.ajax({
                type: method,
                url: url,
                contentType: "application/json",
                data: JSON.stringify(this.getData()),

                success: function(result) {
                    self.id = result.id;

                    if (_.isFunction(options.success)) {
                        options.success(result);
                    }
                },

                error: options.error
            });
        },

        getData: function() {
            const data = {
                mountPoint: this.mountPoint,
                backend: this.backend,
                authMechanism: this.authMechanism,
                backendOptions: this.backendOptions,
                testOnly: true
            };

            if (this.id) {
                data.id = this.id;
            }

            if (this.mountOptions) {
                data.mountOptions = this.mountOptions;
            }

            return data;
        },

        recheck: function(options) {
            if (!_.isNumber(this.id)) {
                if (_.isFunction(options.error)) {
                    options.error();
                }

                return;
            }

            $.ajax({
                type: "GET",

                url: OC.generateUrl(this._url + "/{id}", {
                    id: this.id
                }),

                data: {
                    testOnly: true
                },

                success: options.success,
                error: options.error
            });
        },

        destroy: function(options) {
            if (!_.isNumber(this.id)) {
                if (_.isFunction(options.success)) {
                    options.success();
                }

                return;
            }

            window.OC.PasswordConfirmation.requirePasswordConfirmation(() => this._destroy(options), options.error);
        },

        _destroy: function(options) {
            $.ajax({
                type: "DELETE",

                url: OC.generateUrl(this._url + "/{id}", {
                    id: this.id
                }),

                success: options.success,
                error: options.error
            });
        },

        validate: function() {
            if (this.mountPoint === "") {
                return false;
            }

            if (!this.backend) {
                return false;
            }

            if (this.errors) {
                return false;
            }

            return true;
        }
    };

    const GlobalStorageConfig = function(id) {
        this.id = id;
        this.applicableUsers = [];
        this.applicableGroups = [];
    };

    GlobalStorageConfig.prototype = _.extend({}, StorageConfig.prototype, {
        _url: "apps/files_external/globalstorages",
        applicableUsers: null,
