function(type, data) {
    const item = pimcore.bundle.EcommerceFramework.pricing.conditions[type](this, data);
    const tab = this;

    item.on("afterrender", function(el) {
        el.getEl().applyStyles({
            position: "relative",
            "min-height": "40px",
            "border-bottom": "1px solid #d0d0d0"
        });

        const leftBracket = el.getEl().insertHtml(
            "beforeEnd",
            "<div class=\"pimcore_targeting_bracket pimcore_targeting_bracket_left\">(</div>",
            true
        );

        const rightBracket = el.getEl().insertHtml(
            "beforeEnd",
            "<div class=\"pimcore_targeting_bracket pimcore_targeting_bracket_right\">)</div>",
            true
        );

        if (data["bracketLeft"]) {
            leftBracket.addCls("pimcore_targeting_bracket_active");
        }

        if (data["bracketRight"]) {
            rightBracket.addCls("pimcore_targeting_bracket_active");
        }

        leftBracket.on("click", function(ev, el) {
            const bracket = Ext.get(el);
            bracket.toggleCls("pimcore_targeting_bracket_active");
            tab.recalculateBracketIdent(tab.conditionsContainer.items);
        });

        rightBracket.on("click", function(ev, el) {
            const bracket = Ext.get(el);
            bracket.toggleCls("pimcore_targeting_bracket_active");
            tab.recalculateBracketIdent(tab.conditionsContainer.items);
        });

        tab.recalculateBracketIdent(tab.conditionsContainer.items);
    });

    this.conditionsContainer.add(item);
    item.updateLayout();
    this.conditionsContainer.updateLayout();
    this.currentIndex++;
    this.recalculateButtonStatus();
}

