function() {
    const saveData = {};
    saveData["settings"] = this.settingsForm.getForm().getFieldValues();
    const conditionsData = [];
    let operator;
    const conditions = this.conditionsContainer.items.getRange();

    for (let i = 0; i < conditions.length; i++) {
        const condition = {};

        for (let c = 0; c < conditions[i].items.length; c++) {
            const item = conditions[i].items.getAt(c);

            try {
                if (item.reference) {
                    condition[item.reference.getName()] = item.reference.getValue();
                } else if (item.form) {
                    condition[item.name] = item.getForm().getFieldValues();
                } else if (item.xtype === "datefield") {
                    condition[item.name] = item.getSubmitValue();
                } else {
                    condition[item.getName()] = item.getValue();
                }
            } catch (e) {}
        }

        condition["type"] = conditions[i].type;
        const tb = conditions[i].getDockedItems()[0];

        if (tb.getComponent("toggle_or").pressed) {
            operator = "or";
        } else if (tb.getComponent("toggle_and_not").pressed) {
            operator = "and_not";
        } else {
            operator = "and";
        }

        condition["operator"] = operator;
        condition["bracketLeft"] = Ext.get(conditions[i].getEl().query(".pimcore_targeting_bracket_left")[0]).hasCls("pimcore_targeting_bracket_active");
        condition["bracketRight"] = Ext.get(conditions[i].getEl().query(".pimcore_targeting_bracket_right")[0]).hasCls("pimcore_targeting_bracket_active");
        conditionsData.push(condition);
    }

    saveData["conditions"] = conditionsData;
    const actionData = [];
    const actions = this.actionsContainer.items.getRange();

    for (let i = 0; i < actions.length; i++) {
        let action = {};
        action = actions[i].getForm().getFieldValues();
        action["type"] = actions[i].type;

        if (!actions[i].getForm().isValid()) {
            console.error("Price action invalid");
            return;
        }

        actionData.push(action);
    }

    saveData["actions"] = actionData;

    Ext.Ajax.request({
        url: Routing.generate("pimcore_ecommerceframework_pricing_save"),

        params: {
            id: this.data.id,
            data: Ext.encode(saveData)
        },

        method: "PUT",
        success: this.saveOnComplete.bind(this)
    });
}

