    const conditions = this.conditionsContainer.items.getRange();

    for (let i = 0; i < conditions.length; i++) {
        const tb = conditions[i].getDockedItems()[0];

        if (i == 0) {
            tb.getComponent("toggle_and").hide();
            tb.getComponent("toggle_or").hide();
            tb.getComponent("toggle_and_not").hide();
        } else {
            tb.getComponent("toggle_and").show();
            tb.getComponent("toggle_or").show();
            tb.getComponent("toggle_and_not").show();
        }
    }
}

function(list) {
    let ident = 0;
    let lastIdent = 0;
    const margin = 20;
    const colors = ["transparent", "#007bff", "#00ff99", "#e1a6ff", "#ff3c00", "#000000"];

    list.each(function(condition) {
        if (condition.rendered == false) {
            return;
        }

        const item = condition.getEl();

        item.applyStyles({
            "margin-left": margin * ident + "px",
            "margin-right": margin * ident + "px"
        });

        if (ident > 0) {
            item.applyStyles({
                "border-left": "1px solid " + colors[ident],
                "border-right": "1px solid " + colors[ident]
            });
        } else {
            item.applyStyles({
                "border-left": "0px",
                "border-right": "0px"
            });
        }

        if (ident == 0) {
            item.applyStyles({
                "margin-top": "10px"
            });
        } else if (ident == lastIdent) {
            item.applyStyles({
                "margin-top": "0px",
                "margin-bottom": "0px"
            });
        } else {
            item.applyStyles({
                "margin-top": "5px"
            });
        }

        lastIdent = ident;

        if (item.select(".pimcore_targeting_bracket_left.pimcore_targeting_bracket_active").getCount() == 1) {
            ident++;
        } else if (item.select(".pimcore_targeting_bracket_right.pimcore_targeting_bracket_active").getCount() == 1) {
            if (ident > 0) {
                ident--;
            }
        }
    });

    this.conditionsContainer.updateLayout();
}

function(blockElement, container) {
    let index;

    for (let s = 0; s < container.items.items.length; s++) {
        if (container.items.items[s].getId() == blockElement.getId()) {
            index = s;
            break;
        }
    }

    return index;
}

function(name, index, parent, data, iconCls) {
    const toggleGroup = "g_" + index + parent.data.id;

    if (!data["operator"]) {
        data.operator = "and";
    }

    return [{
        iconCls: iconCls,
        disabled: true
    }, {
        xtype: "tbtext",
        text: "<b>" + name + "</b>"
    }, "-", {
        iconCls: "pimcore_icon_up",

        handler: function(blockId, parent) {
            const container = parent.conditionsContainer;
            const blockElement = Ext.getCmp(blockId);
            const index = pimcore.bundle.EcommerceFramework.pricing.conditions.detectBlockIndex(blockElement, container);
            const tmpContainer = pimcore.viewport;
            let newIndex = index - 1;

            if (newIndex < 0) {
                newIndex = 0;
            }

            container.remove(blockElement, false);
            tmpContainer.add(blockElement);
            container.updateLayout();
            tmpContainer.updateLayout();
            tmpContainer.remove(blockElement, false);
            container.insert(newIndex, blockElement);
            container.updateLayout();
            tmpContainer.updateLayout();
            parent.recalculateButtonStatus();
            pimcore.layout.refresh();
            parent.recalculateBracketIdent(parent.conditionsContainer.items);
        }.bind(window, index, parent)
    }, {
        iconCls: "pimcore_icon_down",

        handler: function(blockId, parent) {
            const container = parent.conditionsContainer;
            const blockElement = Ext.getCmp(blockId);
            const index = pimcore.bundle.EcommerceFramework.pricing.conditions.detectBlockIndex(blockElement, container);
            const tmpContainer = pimcore.viewport;
            container.remove(blockElement, false);
            tmpContainer.add(blockElement);
            container.updateLayout();
            tmpContainer.updateLayout();
            tmpContainer.remove(blockElement, false);
            container.insert(index + 1, blockElement);
            container.updateLayout();
            tmpContainer.updateLayout();
            parent.recalculateButtonStatus();
            pimcore.layout.refresh();
            parent.recalculateBracketIdent(parent.conditionsContainer.items);
        }.bind(window, index, parent)
    }, "-", {
        text: t("AND"),
        toggleGroup: toggleGroup,
        enableToggle: true,
        itemId: "toggle_and",
        pressed: data.operator == "and" ? true : false
    }, {
        text: t("OR"),
        toggleGroup: toggleGroup,
        enableToggle: true,
        itemId: "toggle_or",
        pressed: data.operator == "or" ? true : false
    }, {
        text: t("AND_NOT"),
        toggleGroup: toggleGroup,
        enableToggle: true,
        itemId: "toggle_and_not",
        pressed: data.operator == "and_not" ? true : false
    }, "->", {
        iconCls: "pimcore_icon_delete",

        handler: function(index, parent) {
            parent.conditionsContainer.remove(Ext.getCmp(index));
            parent.recalculateButtonStatus();
            parent.recalculateBracketIdent(parent.conditionsContainer.items);
        }.bind(window, index, parent)
    }];
}

