function get_config_aliases(config) {
    const alias = [{
        find: "$lib",
        replacement: config.files.lib
    }];

    for (let [key, value] of Object.entries(config.alias)) {
        value = posixify(value);

        if (value.endsWith("/*")) {
            value = value.slice(0, -2);
        }

        if (key.endsWith("/*")) {
            alias.push({
                find: new RegExp(`^${escape_for_regexp(key.slice(0, -2))}\\/(.+)$`),
                replacement: `${path.resolve(value)}/$1`
            });
        } else if (key + "/*" in config.alias) {
            alias.push({
                find: new RegExp(`^${escape_for_regexp(key)}$`),
                replacement: path.resolve(value)
            });
        } else {
            alias.push({
                find: key,
                replacement: path.resolve(value)
            });
        }
    }

    return alias;
}

