    const htmlMsg = "<div class=\"alert alert-" + alertType + " alert-dismissible\" role=\"alert\"><button type=\"button\" class=\"close\" data-dismiss=\"alert\" aria-label=\"Close\"><span aria-hidden=\"true\">&times;</span></button>" + msg + "</div>";
    return htmlMsg;
}

function createNetmaskAddr(bitCount) {
    const mask = [];

    for (i = 0; i < 4; i++) {
        const n = Math.min(bitCount, 8);
        mask.push(256 - Math.pow(2, 8 - n));
        bitCount -= n;
    }

    return mask.join(".");
}

