function find_boundary_tr($initial_tr, iterate_row) {
    let j;
    let skip_same_td_check = false;
    let $tr = $initial_tr;

    if ($tr.length === 0) {
        return undefined;
    }

    for (j = 0; !$tr.is(".message_row") && j < 10; j += 1) {
        $tr = iterate_row($tr);
    }

    if (j === 10) {
        return undefined;
    } else if (j !== 0) {
        skip_same_td_check = true;
    }

    return [rows.id($tr), skip_same_td_check];
}

