                }
            }
        } catch (e) {
            util.noop();
        }
    }

    if (_darwin) {
        try {
            const cmd = "/sbin/ifconfig";
            const res = execSync(cmd);
            const lines = res.toString().split("\n");

            for (let i = 0; i < lines.length; i++) {
                if (lines[i] && lines[i][0] !== "\t" && lines[i].indexOf(":") > 0) {
                    iface = lines[i].split(":")[0];
