function markdown(md): void {
    const {
        html_inline,
        html_block
    } = md.renderer.rules;

    const sanitizedRenderer = (original: (...args: any[]) => string) => (...args) => {
        const ret = original(...args);
        const splitted: string[] = [];
        let pos = 0;

        while (pos < ret.length) {
            const startIdx = ret.indexOf("<!--", pos);
            let endIdx = startIdx !== -1 ? ret.indexOf("-->", startIdx + 4) : -1;

            if (endIdx === -1) {
                splitted.push(ret.slice(pos));
                break;
            }

            endIdx += 3;
            splitted.push(ret.slice(pos, startIdx), ret.slice(startIdx, endIdx));
            pos = endIdx;
        }

        const allowList = {};
        const html: MarpOptions["html"] = md.options.html;

        if (typeof html === "object") {
            for (const tag of Object.keys(html)) {
                const attrs = html[tag];

                if (Array.isArray(attrs)) {
                    allowList[tag] = attrs;
                } else if (typeof attrs === "object") {
                    allowList[tag] = Object.keys(attrs).filter(attr => attrs[attr] !== false);
                }
            }
        }

        const filter = new FilterXSS({
            whiteList: allowList,
            onIgnoreTag: (_, rawHtml) => (html === true ? rawHtml : undefined),

            safeAttrValue: (tag, attr, value) => {
                let ret = friendlyAttrValue(value);

                if (typeof html === "object" && html[tag] && !Array.isArray(html[tag]) && typeof html[tag][attr] === "function") {
                    ret = html[tag][attr](ret);
                }

                return escapeAttrValue(ret);
            }
        });

        return splitted.map((part, idx) => {
            if (idx % 2 === 1)
                return part;

            const sanitized = filter.process(part);
            return md.options.xhtmlOut ? xhtmlOutFilter.process(sanitized) : sanitized;
        }).join("");
    };

    md.renderer.rules.html_inline = sanitizedRenderer(html_inline);
    md.renderer.rules.html_block = sanitizedRenderer(html_block);
}

async ctx => {
    if (ctx.request?.method !== "POST" || !ctx.request) {
        return;
    }

    const {
        body,
        query,
        context
    } = ctx;

    const originHeader = ctx.headers?.get("origin") || ctx.headers?.get("referer") || "";
    const callbackURL = body?.callbackURL || query?.callbackURL;
    const redirectURL = body?.redirectTo;
    const errorCallbackURL = body?.errorCallbackURL;
    const newUserCallbackURL = body?.newUserCallbackURL;

    const trustedOrigins: string[] = Array.isArray(context.options.trustedOrigins) ? context.trustedOrigins : [
        ...context.trustedOrigins,
        ...(context.options.trustedOrigins?.(ctx.request) || [])
    ];

    const usesCookies = ctx.headers?.has("cookie");

    const matchesPattern = (url: string, pattern: string): boolean => {
        if (url.startsWith("/")) {
            return false;
        }

        if (pattern.includes("*")) {
            return wildcardMatch(pattern)(getHost(url));
        }

        const protocol = getProtocol(url);
        return protocol === "http:" || protocol === "https:" || !protocol ? pattern === getOrigin(url) : url.startsWith(pattern);
    };

    const validateURL = (url: string | undefined, label: string) => {
        if (!url) {
            return;
        }

        const isTrustedOrigin = trustedOrigins.some(
            origin => matchesPattern(url, origin) || (url?.startsWith("/") && label !== "origin" && !url.includes(":"))
        );

        if (!isTrustedOrigin) {
            ctx.context.logger.error(`Invalid ${label}: ${url}`);

            ctx.context.logger.info(
                `If it's a valid URL, please add ${url} to trustedOrigins in your auth config\n`,
                `Current list of trustedOrigins: ${trustedOrigins}`
            );

            throw new APIError("FORBIDDEN", {
                message: `Invalid ${label}`
            });
        }
    };

    if (usesCookies && !ctx.context.options.advanced?.disableCSRFCheck) {
        validateURL(originHeader, "origin");
    }

    callbackURL && validateURL(callbackURL, "callbackURL");
    redirectURL && validateURL(redirectURL, "redirectURL");
    errorCallbackURL && validateURL(errorCallbackURL, "errorCallbackURL");
    newUserCallbackURL && validateURL(newUserCallbackURL, "newUserCallbackURL");
}

