(
    {
        onClose
    }
) => {
    const [syncedFiles, setSyncedFiles] = useState<string[]>([]);
    const [selectedFiles, setSelectedFiles] = useState<string[]>([]);
    const [searchQuery, setSearchQuery] = useState("");
    const [isDragAndDropping, setIsDragAndDropping] = useState(false);
    const [warning, setWarning] = useState<string | null>(null);
    const [error, setError] = useState<string | null>(null);
    const [uploading, setUploading] = useState(false);
    const [progressValue, setProgressValue] = useState(0);
    const [uploadedFiles, setUploadedFiles] = useState<string[]>([]);
    const fileInputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        if (!uploading) {
            setProgressValue(0);
        }

        if (uploading) {
            const interval = setInterval(() => {
                setProgressValue(prev => {
                    const increment = Math.floor(Math.random() * 5) + 1;
                    const nextValue = prev + increment;
                    return nextValue < 100 ? nextValue : 100;
                });
            }, 800);

            return () => clearInterval(interval);
        }
    }, [uploading]);

    useEffect(() => {
        const fetchFiles = async () => {
            try {
                const response = await fetch("/api/content/computer");

                if (!response.ok)
                    throw new Error("Failed to fetch files");

                const syncedFiles = await response.json();

                if (Array.isArray(syncedFiles)) {
                    setSyncedFiles(syncedFiles.toSorted());
                } else {
                    console.error("Unexpected data format from API");
                }
            } catch (error) {
                console.error("Error fetching files:", error);
            }
        };

        fetchFiles();
    }, [uploadedFiles]);

    const filteredFiles = syncedFiles.filter(file => file.toLowerCase().includes(searchQuery.toLowerCase()));

    const deleteSelected = async () => {
        const filesToDelete = selectedFiles.length > 0 ? selectedFiles : filteredFiles;

        if (filesToDelete.length === 0) {
            return;
        }

        try {
            const response = await fetch("/api/content/files", {
                method: "DELETE",

                headers: {
                    "Content-Type": "application/json"
                },

                body: JSON.stringify({
                    files: filesToDelete
                })
            });

            if (!response.ok)
                throw new Error("Failed to delete files");

            setSyncedFiles(prevFiles => prevFiles.filter(file => !filesToDelete.includes(file)));
            setSelectedFiles([]);
        } catch (error) {
            console.error("Error deleting files:", error);
        }
    };

    const deleteFile = async (filename: string) => {
        try {
            const response = await fetch(`/api/content/file?filename=${encodeURIComponent(filename)}`, {
                method: "DELETE",

                headers: {
                    "Content-Type": "application/json"
                }
            });

            if (!response.ok)
                throw new Error("Failed to delete file");

            setSyncedFiles(prevFiles => prevFiles.filter(file => file !== filename));
            setSelectedFiles(prevSelected => prevSelected.filter(file => file !== filename));
        } catch (error) {
            console.error("Error deleting file:", error);
        }
    };

    function handleDragOver(event: React.DragEvent<HTMLDivElement>) {
        event.preventDefault();
        setIsDragAndDropping(true);
    }

    function handleDragLeave(event: React.DragEvent<HTMLDivElement>) {
        event.preventDefault();
        setIsDragAndDropping(false);
    }

    function handleDragAndDropFiles(event: React.DragEvent<HTMLDivElement>) {
        event.preventDefault();
        setIsDragAndDropping(false);

        if (!event.dataTransfer.files)
            return;

        uploadFiles(event.dataTransfer.files);
    }

    function openFileInput() {
        if (fileInputRef && fileInputRef.current) {
            fileInputRef.current.click();
        }
    }

    function handleFileChange(event: React.ChangeEvent<HTMLInputElement>) {
        if (!event.target.files)
            return;

        uploadFiles(event.target.files);
    }

    function uploadFiles(files: FileList) {
        uploadDataForIndexing(files, setWarning, setUploading, setError, setUploadedFiles);
    }

    return (
        (<CommandDialog open={true} onOpenChange={onClose}>
            <AlertDialog open={warning !== null || error != null}>
                <AlertDialogContent>
                    <AlertDialogHeader>
                        <AlertDialogTitle>Alert</AlertDialogTitle>
                    </AlertDialogHeader>
                    <AlertDialogDescription>{warning || error}</AlertDialogDescription>
                    <AlertDialogAction
                        className="bg-slate-400 hover:bg-slate-500"
                        onClick={() => {
                            setWarning(null);
                            setError(null);
                            setUploading(false);
                        }}>Close</AlertDialogAction>
                </AlertDialogContent>
            </AlertDialog>
            <div
                className={`flex flex-col h-full`}
                onDragOver={handleDragOver}
                onDragLeave={handleDragLeave}
                onDrop={handleDragAndDropFiles}
                onClick={openFileInput}>
                <input
                    type="file"
                    multiple
                    ref={fileInputRef}
                    style={{
                        display: "none"
                    }}
                    onChange={handleFileChange} />
                <div className="flex-none p-4">Upload files{uploading && (<Progress
                        indicatorColor="bg-slate-500"
                        className="w-full h-2 rounded-full"
                        value={progressValue} />)}
                </div>
                <div
                    className={`flex-none p-4 bg-secondary border-b ${isDragAndDropping ? "animate-pulse" : ""} rounded-lg`}>
                    <div
                        className="flex items-center justify-center w-full h-32 border-2 border-dashed border-gray-300 rounded-lg">
                        {isDragAndDropping ? (<div className="flex items-center justify-center w-full h-full">
                            <Waveform className="h-6 w-6 mr-2" />
                            <span>Drop files to upload</span>
                        </div>) : (<div className="flex items-center justify-center w-full h-full">
                            <Plus className="h-6 w-6 mr-2" />
                            <span>Drag and drop files here</span>
                        </div>)}
                    </div>
                </div>
            </div>
            <div className="flex flex-col h-full">
                <div className="flex-none p-4 bg-background border-b">
                    <CommandInput
                        placeholder="Find synced files"
                        value={searchQuery}
                        onValueChange={setSearchQuery} />
                </div>
                <div className="flex-grow overflow-auto">
                    <CommandList>
                        <CommandEmpty>
                            {syncedFiles.length === 0 ? (<div className="flex items-center justify-center">
                                <ExclamationMark className="h-4 w-4 mr-2" weight="bold" />No files synced</div>) : (<div>Could not find a good match.<Link href="/search" className="block">Need advanced search? Click here.</Link>
                            </div>)}
                        </CommandEmpty>
                        <CommandGroup heading="Synced files">
                            {filteredFiles.map((filename: string) => (<CommandItem
                                key={filename}
                                value={filename}
                                onSelect={value => {
                                    setSelectedFiles(
                                        prev => prev.includes(value) ? prev.filter(f => f !== value) : [...prev, value]
                                    );
                                }}>
                                <div className="flex items-center justify-between w-full">
                                    <div
                                        className={`flex items-center ${selectedFiles.includes(filename) ? "font-semibold" : ""}`}>
                                        {selectedFiles.includes(filename) && <Check className="h-4 w-4 mr-2" />}
                                        <span className="break-all">{filename}</span>
                                    </div>
                                    <Button
                                        variant="outline"
                                        size="sm"
                                        onClick={() => deleteFile(filename)}
                                        className="ml-auto">
                                        <Trash className="h-4 w-4" />
                                    </Button>
                                </div>
                            </CommandItem>))}
                        </CommandGroup>
                    </CommandList>
                </div>
                <div className="flex-none p-4 bg-background border-t">
                    <div className="flex justify-between">
                        <Button variant="outline" size="sm" onClick={deleteSelected} className="mr-2">
                            <Trash className="h-4 w-4 mr-2" />
                            {selectedFiles.length > 0 ? `Delete Selected (${selectedFiles.length})` : "Delete All"}
                        </Button>
                    </div>
                </div>
            </div>
        </CommandDialog>)
    );
}

(
    {
        items,
        selected,
        callbackFunc
    }
) => {
    const [position, setPosition] = useState(selected?.toString() ?? "0");

    return (!!selected && (<div className="overflow-hidden shadow-md rounded-lg">
        <DropdownMenu>
            <DropdownMenuTrigger asChild className="w-full rounded-lg">
                <Button variant="outline" className="justify-start py-6 rounded-lg">
                    {items.find(item => item.id.toString() === position)?.name}{" "}
                    <CaretDown className="h-4 w-4 ml-auto text-muted-foreground" />
                </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent>
                <DropdownMenuRadioGroup
                    value={position}
                    onValueChange={async value => {
                        setPosition(value);
                        await callbackFunc(value);
                    }}>
                    {items.map(
                        item => (<DropdownMenuRadioItem key={item.id.toString()} value={item.id.toString()}>
                            {item.name}
                        </DropdownMenuRadioItem>)
                    )}
                </DropdownMenuRadioGroup>
            </DropdownMenuContent>
        </DropdownMenu>
    </div>));
}

() => {
    const [apiKeys, setApiKeys] = useState<TokenObject[]>([]);

    const {
        toast
    } = useToast();

    const generateAPIKey = async () => {
        try {
            const response = await fetch(`/auth/token`, {
                method: "POST",

                headers: {
                    "Content-Type": "application/json"
                }
            });

            const tokenObj = await response.json();
            setApiKeys(prevKeys => [...prevKeys, tokenObj]);
        } catch (error) {
            console.error("Error generating API key:", error);
        }
    };

    const copyAPIKey = async (token: string) => {
        try {
            await navigator.clipboard.writeText(token);

            toast({
                title: "🔑 API Key",
                description: "Copied to clipboard"
            });
        } catch (error) {
            console.error("Error copying API key:", error);
        }
    };

    const deleteAPIKey = async (token: string) => {
        try {
            const response = await fetch(`/auth/token?token=${token}`, {
                method: "DELETE"
            });

            if (response.ok) {
                setApiKeys(prevKeys => prevKeys.filter(key => key.token !== token));
            }
        } catch (error) {
            console.error("Error deleting API key:", error);
        }
    };

    const listApiKeys = async () => {
        try {
            const response = await fetch(`/auth/token`);
            const tokens = await response.json();

            if (tokens?.length > 0) {
                setApiKeys(tokens);
            }
        } catch (error) {
            console.error("Error listing API keys:", error);
        }
    };

    useEffect(() => {
        listApiKeys();
    }, []);

    return {
        apiKeys,
        generateAPIKey,
        copyAPIKey,
        deleteAPIKey
    };
}

function SettingsView() {
    const [title, setTitle] = useState("Settings");

    const {
        apiKeys,
        generateAPIKey,
        copyAPIKey,
        deleteAPIKey
    } = useApiKeys();

    const {
        userConfig: initialUserConfig
    } = useUserConfig(true);

    const [userConfig, setUserConfig] = useState<UserConfig | null>(null);
    const [name, setName] = useState<string | undefined>(undefined);
    const [notionToken, setNotionToken] = useState<string | null>(null);
    const [phoneNumber, setPhoneNumber] = useState<string | undefined>(undefined);
    const [otp, setOTP] = useState("");
    const [numberValidationState, setNumberValidationState] = useState<PhoneNumberValidationState>(PhoneNumberValidationState.Verified);
    const [isManageFilesModalOpen, setIsManageFilesModalOpen] = useState(false);

    const {
        toast
    } = useToast();

    const isMobileWidth = useIsMobileWidth();
    const cardClassName = "w-full lg:w-1/3 grid grid-flow-column border border-gray-300 shadow-md rounded-lg bg-gradient-to-b from-background to-gray-50 dark:to-gray-950 border border-opacity-50";

    useEffect(() => {
        setUserConfig(initialUserConfig);
        setPhoneNumber(initialUserConfig?.phone_number);

        setNumberValidationState(
            initialUserConfig?.is_phone_number_verified ? PhoneNumberValidationState.Verified : initialUserConfig?.phone_number ? PhoneNumberValidationState.SendOTP : PhoneNumberValidationState.Setup
        );

        setName(initialUserConfig?.given_name);
        setNotionToken(initialUserConfig?.notion_token ?? null);
    }, [initialUserConfig]);

    const sendOTP = async () => {
        try {
            const response = await fetch(`/api/phone?phone_number=${phoneNumber}`, {
                method: "POST",

                headers: {
                    "Content-Type": "application/json"
                }
            });

            if (!response.ok)
                throw new Error("Failed to send OTP");

            setNumberValidationState(PhoneNumberValidationState.VerifyOTP);
        } catch (error) {
            console.error("Error sending OTP:", error);

            toast({
                title: "📱 Phone",
                description: "Failed to send OTP. Try again or contact us at team@khoj.dev"
            });
        }
    };

    const verifyOTP = async () => {
        try {
            const response = await fetch(`/api/phone/verify?code=${otp}`, {
                method: "POST",

                headers: {
                    "Content-Type": "application/json"
                }
            });

            if (!response.ok)
                throw new Error("Failed to verify OTP");

            setNumberValidationState(PhoneNumberValidationState.Verified);

            toast({
                title: "📱 Phone",
                description: "Phone number verified"
            });
        } catch (error) {
            console.error("Error verifying OTP:", error);

            toast({
                title: "📱 Phone",
                description: "Failed to verify OTP. Try again or contact us at team@khoj.dev"
            });
        }
    };

    const disconnectNumber = async () => {
        try {
            const response = await fetch(`/api/phone`, {
                method: "DELETE",

                headers: {
                    "Content-Type": "application/json"
                }
            });

            if (!response.ok)
                throw new Error("Failed to disconnect phone number");

            setPhoneNumber(undefined);
            setNumberValidationState(PhoneNumberValidationState.Setup);

            toast({
                title: "📱 Phone",
                description: "Phone number disconnected"
            });
        } catch (error) {
            console.error("Error disconnecting phone number:", error);

            toast({
                title: "📱 Phone",
                description: "Failed to disconnect phone number. Try again or contact us at team@khoj.dev"
            });
        }
    };

    const setSubscription = async (state: string) => {
        try {
            const url = `/api/subscription?operation=${state}`;

            const response = await fetch(url, {
                method: "PATCH",

                headers: {
                    "Content-Type": "application/json"
                }
            });

            if (!response.ok)
                throw new Error("Failed to change subscription");

            if (userConfig) {
                const newUserConfig = userConfig;
                newUserConfig.subscription_state = state === "cancel" ? SubscriptionStates.UNSUBSCRIBED : SubscriptionStates.SUBSCRIBED;
                setUserConfig(newUserConfig);
            }

            toast({
                title: "💳 Subscription",
                description: userConfig?.subscription_state === "unsubscribed" ? "Your subscription was cancelled" : "Your Futurist subscription has been renewed"
            });
        } catch (error) {
            console.error("Error changing subscription:", error);

            toast({
                title: "💳 Subscription",
                description: state === "cancel" ? "Failed to cancel subscription. Try again or contact us at team@khoj.dev" : "Failed to renew subscription. Try again or contact us at team@khoj.dev"
            });
        }
    };

    const enableFreeTrial = async () => {
        const formatDate = (dateString: Date) => {
            const date = new Date(dateString);

            return new Intl.DateTimeFormat("en-US", {
                day: "2-digit",
                month: "short",
                year: "numeric"
            }).format(date);
        };

        try {
            const response = await fetch(`/api/subscription/trial`, {
                method: "POST"
            });

            if (!response.ok)
                throw new Error("Failed to enable free trial");

            const responseBody = await response.json();

            if (responseBody.trial_enabled && userConfig) {
                const newUserConfig = userConfig;
                newUserConfig.subscription_state = SubscriptionStates.TRIAL;
                const renewalDate = new Date(Date.now() + userConfig.length_of_free_trial * 24 * 60 * 60 * 1000);
                newUserConfig.subscription_renewal_date = formatDate(renewalDate);
                newUserConfig.subscription_enabled_trial_at = new Date().toISOString();
                setUserConfig(newUserConfig);

                toast({
                    title: "🎉 Trial Enabled",
                    description: `Your free trial will end on ${newUserConfig.subscription_renewal_date}`
                });
            }
        } catch (error) {
            console.error("Error enabling free trial:", error);

            toast({
                title: "⚠️ Failed to Enable Free Trial",
                description: "Failed to enable free trial. Try again or contact us at team@khoj.dev"
            });
        }
    };

    const saveName = async () => {
        if (!name)
            return;

        try {
            const response = await fetch(`/api/user/name?name=${name}`, {
                method: "PATCH",

                headers: {
                    "Content-Type": "application/json"
                }
            });

            if (!response.ok)
                throw new Error("Failed to update name");

            if (userConfig) {
                const newUserConfig = userConfig;
                newUserConfig.given_name = name;
                setUserConfig(newUserConfig);
            }

            toast({
                title: `✅ Updated Profile`,
                description: `You name has been updated to ${name}`
            });
        } catch (error) {
            console.error("Error updating name:", error);

            toast({
                title: "⚠️ Failed to Update Profile",
                description: "Failed to update name. Try again or contact team@khoj.dev"
            });
        }
    };

    const updateModel = (name: string) => async (id: string) => {
        if (!userConfig?.is_active) {
            toast({
                title: `Model Update`,
                description: `You need to be subscribed to update ${name} models`,
                variant: "destructive"
            });

            return;
        }

        try {
            const response = await fetch(`/api/model/${name}?id=` + id, {
                method: "POST",

                headers: {
                    "Content-Type": "application/json"
                }
            });

            if (!response.ok)
                throw new Error("Failed to update model");

            toast({
                title: `✅ Updated ${toTitleCase(name)} Model`
            });
        } catch (error) {
            console.error(`Failed to update ${name} model:`, error);

            toast({
                description: `❌ Failed to update ${toTitleCase(name)} model. Try again.`,
                variant: "destructive"
            });
        }
    };

    const saveNotionToken = async () => {
        if (!notionToken)
            return;

        try {
            const response = await fetch(`/api/content/notion`, {
                method: "POST",

                headers: {
                    "Content-Type": "application/json"
                },

                body: JSON.stringify({
                    token: notionToken
                })
            });

            if (!response.ok)
                throw new Error("Failed to save Notion API key");

            if (userConfig) {
                const newUserConfig = userConfig;
                newUserConfig.notion_token = notionToken;
                setUserConfig(newUserConfig);
            }

            toast({
                title: `✅ Saved Notion Settings`,
                description: `You Notion API key has been saved.`
            });
        } catch (error) {
            console.error("Error updating name:", error);

            toast({
                title: "⚠️ Failed to Save Notion Settings",
                description: "Failed to save Notion API key. Try again or contact team@khoj.dev"
            });
        }
    };

    const syncContent = async (type: string) => {
        try {
            const response = await fetch(`/api/content?t=${type}`, {
                method: "PATCH",

                headers: {
                    "Content-Type": "application/json"
                }
            });

            if (!response.ok)
                throw new Error(`Failed to sync content from ${type}`);

            toast({
                title: `🔄 Syncing ${type}`,
                description: `Your ${type} content is being synced.`
            });
        } catch (error) {
            console.error("Error syncing content:", error);

            toast({
                title: `⚠️ Failed to Sync ${type}`,
                description: `Failed to sync ${type} content. Try again or contact team@khoj.dev`
            });
        }
    };

    const disconnectContent = async (type: string) => {
        try {
            const response = await fetch(`/api/content/${type}`, {
                method: "DELETE",

                headers: {
                    "Content-Type": "application/json"
                }
            });

            if (!response.ok)
                throw new Error(`Failed to disconnect ${type}`);

            if (userConfig) {
                const newUserConfig = userConfig;

                if (type === "computer") {
                    newUserConfig.enabled_content_source.computer = false;
                } else if (type === "notion") {
                    newUserConfig.enabled_content_source.notion = false;
                    newUserConfig.notion_token = null;
                    setNotionToken(newUserConfig.notion_token);
                } else if (type === "github") {
                    newUserConfig.enabled_content_source.github = false;
                }

                setUserConfig(newUserConfig);
            }

            if (type === "computer") {
                toast({
                    title: `✅ Deleted Synced Files`,
                    description: "Your synced documents have been deleted."
                });
            } else {
                toast({
                    title: `✅ Disconnected ${type}`,
                    description: `Your ${type} integration to Khoj has been disconnected.`
                });
            }
        } catch (error) {
            console.error(`Error disconnecting ${type}:`, error);

            toast({
                title: `⚠️ Failed to Disconnect ${type}`,
                description: `Failed to disconnect from ${type}. Try again or contact team@khoj.dev`
            });
        }
    };

    if (!userConfig)
        return <Loading />;

    return (
        (<div className={styles.page}>
            <title>{title}</title>
            <div className={styles.sidePanel}>
                <SidePanel conversationId={null} uploadedFiles={[]} isMobileWidth={isMobileWidth} />
            </div>
            <div className={styles.content}>
                <div className={`${styles.contentBody} mx-10 my-2`}>
                    <Suspense fallback={<Loading />}>
                        <div
                            id="content"
                            className="grid grid-flow-column sm:grid-flow-row gap-16 m-8">
                            <div className="section grid gap-8">
                                <div className="text-2xl">Profile</div>
                                <div className="cards flex flex-wrap gap-16">
                                    <Card className={cardClassName}>
                                        <CardHeader className="text-xl flex flex-row">
                                            <UserCircle className="h-7 w-7 mr-2" />Name</CardHeader>
                                        <CardContent className="overflow-hidden">
                                            <p className="pb-4 text-gray-400">What should Khoj refer to you as?</p>
                                            <Input
                                                type="text"
                                                onChange={e => setName(e.target.value)}
                                                value={name}
                                                className="w-full border border-gray-300 rounded-lg p-4 py-6" />
                                        </CardContent>
                                        <CardFooter className="flex flex-wrap gap-4">
                                            <Button
                                                variant="outline"
                                                size="sm"
                                                onClick={saveName}
                                                disabled={name === userConfig.given_name}>
                                                <FloppyDisk className="h-5 w-5 inline mr-2" />Save</Button>
                                        </CardFooter>
                                    </Card>
                                    <Card id="subscription" className={cardClassName}>
                                        <CardHeader className="text-xl flex flex-row">
                                            <CreditCard className="h-7 w-7 mr-2" />Subscription</CardHeader>
                                        <CardContent className="grid gap-2 overflow-hidden">
                                            <p className="text-gray-400">Current Plan</p>
                                            {(userConfig.subscription_state === "trial" && (<>
                                                <p className="text-xl text-primary/80">Futurist (Trial)</p>
                                                <p className="text-gray-400">You are on a{userConfig.length_of_free_trial}day trial of the Khoj Futurist plan. Your
                                                                                trial ends on{userConfig.subscription_renewal_date}. Check{" "}
                                                    <a href="https://khoj.dev/#pricing" target="_blank">pricing page</a>{" "}to compare plans.</p>
                                            </>)) || (userConfig.subscription_state === "subscribed" && (<>
                                                <p className="text-xl text-primary/80">Futurist</p>
                                                <p className="text-gray-400">Subscription<b>renews</b>on<b>{userConfig.subscription_renewal_date}</b>
                                                </p>
                                            </>)) || (userConfig.subscription_state === "unsubscribed" && (<>
                                                <p className="text-xl">Futurist</p>
                                                <p className="text-gray-400">Subscription<b>ends</b>on<b>{userConfig.subscription_renewal_date}</b>
                                                </p>
                                            </>)) || (userConfig.subscription_state === "expired" && (<>
                                                <p className="text-xl">Humanist</p>
                                                {(userConfig.subscription_renewal_date && (<p className="text-gray-400">Subscription<b>expired</b>on<b>{userConfig.subscription_renewal_date}</b>
                                                </p>)) || (<p className="text-gray-400">Check{" "}
                                                    <a href="https://khoj.dev/#pricing" target="_blank">pricing page</a>{" "}to compare plans.</p>)}
                                            </>))}
                                        </CardContent>
                                        <CardFooter className="flex flex-wrap gap-4">
                                            {(userConfig.subscription_state == "subscribed" && (<Button
                                                variant="outline"
                                                className="hover:text-red-400"
                                                onClick={() => setSubscription("cancel")}>
                                                <ArrowCircleDown className="h-5 w-5 mr-2" />Unsubscribe</Button>)) || (userConfig.subscription_state == "unsubscribed" && (<Button
                                                variant="outline"
                                                className="text-primary/80 hover:text-primary"
                                                onClick={() => setSubscription("resubscribe")}>
                                                <ArrowCircleUp weight="bold" className="h-5 w-5 mr-2" />Resubscribe</Button>)) || (userConfig.subscription_enabled_trial_at && (<Button
                                                variant="outline"
                                                className="text-primary/80 hover:text-primary"
                                                onClick={() => window.open(
                                                    `${userConfig.khoj_cloud_subscription_url}?prefilled_email=${userConfig.username}`,
                                                    "_blank",
                                                    "noopener,noreferrer"
                                                )}>
                                                <ArrowCircleUp weight="bold" className="h-5 w-5 mr-2" />Subscribe</Button>)) || (<Button
                                                variant="outline"
                                                className="text-primary/80 hover:text-primary"
                                                onClick={enableFreeTrial}>
                                                <ArrowCircleUp weight="bold" className="h-5 w-5 mr-2" />Enable Trial</Button>)}
                                        </CardFooter>
                                    </Card>
                                </div>
                            </div>
                            {isManageFilesModalOpen && <ManageFilesModal onClose={() => setIsManageFilesModalOpen(false)} />}
                            <div className="section grid gap-8">
                                <div className="text-2xl">Content</div>
                                <div className="cards flex flex-wrap gap-16">
                                    <Card id="computer" className={cardClassName}>
                                        <CardHeader className="flex flex-row text-2xl">
