                                        </CardHeader>
                                        <CardContent className="overflow-hidden pb-12 text-gray-400">Manage your synced files</CardContent>
                                        <CardFooter className="flex flex-wrap gap-4">
                                            <Button
                                                variant="outline"
                                                size="sm"
                                                onClick={() => setIsManageFilesModalOpen(true)}>
