                                        <CardFooter className="flex flex-wrap gap-4">
                                            <Button variant="outline" size="sm">
                                                {(userConfig.enabled_content_source.github && (<>
                                                    <Files className="h-5 w-5 inline mr-1" />Manage</>)) || (<>
                                                    <Plugs className="h-5 w-5 inline mr-1" />Connect</>)}
                                            </Button>
                                            <Button
                                                variant="outline"
                                                size="sm"
                                                className={`${userConfig.enabled_content_source.github || "hidden"}`}>
                                                <CloudSlash className="h-5 w-5 inline mr-1" />Disable</Button>
                                        </CardFooter>
                                    </Card>
                                    <Card id="notion" className={cardClassName}>
                                        <CardHeader className="text-xl flex flex-row">
                                            <NotionLogo className="h-7 w-7 mr-2" />Notion{userConfig.enabled_content_source.notion && (<CheckCircle className="h-6 w-6 ml-auto text-green-500" weight="fill" />)}
                                        </CardHeader>
                                        <CardContent className="grid gap-4">
                                            <p className="text-gray-400">Sync your Notion workspace.</p>
                                            {!userConfig.notion_oauth_url && (<Input
                                                onChange={e => setNotionToken(e.target.value)}
                                                value={notionToken || ""}
                                                placeholder="Enter API Key of your Khoj integration on Notion"
                                                className="w-full border border-gray-300 rounded-lg px-4 py-6" />)}
                                        </CardContent>
                                        <CardFooter className="flex flex-wrap gap-4">
                                            {userConfig.notion_oauth_url && !userConfig.enabled_content_source.notion ? (<Button
                                                variant="outline"
                                                size="sm"
                                                onClick={() => {
                                                    window.open(userConfig.notion_oauth_url);
                                                }}>
                                                <Plugs className="h-5 w-5 inline mr-1" />Connect</Button>) : userConfig.enabled_content_source.notion && notionToken === userConfig.notion_token ? (<Button variant="outline" size="sm" onClick={() => syncContent("notion")}>
                                                <ArrowsClockwise className="h-5 w-5 inline mr-1" />Sync</Button>) : !userConfig.notion_oauth_url ? (<Button
                                                variant="outline"
                                                size="sm"
                                                onClick={saveNotionToken}
                                                disabled={notionToken === userConfig.notion_token}>
                                                <FloppyDisk className="h-5 w-5 inline mr-1" />
                                                {(userConfig.enabled_content_source.notion && "Update API Key") || "Set API Key"}
                                            </Button>) : (<></>)}
                                            <Button
                                                variant="outline"
                                                size="sm"
                                                className={`${userConfig.notion_token || "hidden"}`}
                                                onClick={() => disconnectContent("notion")}>
                                                <CloudSlash className="h-5 w-5 inline mr-1" />Disconnect</Button>
                                        </CardFooter>
                                    </Card>
                                </div>
                            </div>
                            <div className="section grid gap-8">
                                <div className="text-2xl">Models</div>
                                <div className="cards flex flex-wrap gap-16">
                                    {userConfig.chat_model_options.length > 0 && (<Card className={cardClassName}>
                                        <CardHeader className="text-xl flex flex-row">
                                            <ChatCircleText className="h-7 w-7 mr-2" />Chat</CardHeader>
                                        <CardContent className="overflow-hidden pb-12 grid gap-8 h-fit">
                                            <p className="text-gray-400">Pick the chat model to generate text responses</p>
                                            <DropdownComponent
                                                items={userConfig.chat_model_options}
                                                selected={userConfig.selected_chat_model_config}
                                                callbackFunc={updateModel("chat")} />
                                        </CardContent>
                                        <CardFooter className="flex flex-wrap gap-4">
                                            {!userConfig.is_active && <p className="text-gray-400">Subscribe to switch model</p>}
                                        </CardFooter>
                                    </Card>)}
                                    {userConfig.paint_model_options.length > 0 && (<Card className={cardClassName}>
                                        <CardHeader className="text-xl flex flex-row">
                                            <Palette className="h-7 w-7 mr-2" />Paint</CardHeader>
                                        <CardContent className="overflow-hidden pb-12 grid gap-8 h-fit">
                                            <p className="text-gray-400">Pick the paint model to generate image responses</p>
                                            <DropdownComponent
                                                items={userConfig.paint_model_options}
                                                selected={userConfig.selected_paint_model_config}
                                                callbackFunc={updateModel("paint")} />
                                        </CardContent>
                                        <CardFooter className="flex flex-wrap gap-4">
                                            {!userConfig.is_active && <p className="text-gray-400">Subscribe to switch model</p>}
                                        </CardFooter>
                                    </Card>)}
                                    {userConfig.voice_model_options.length > 0 && (<Card className={cardClassName}>
                                        <CardHeader className="text-xl flex flex-row">
                                            <Waveform className="h-7 w-7 mr-2" />Voice</CardHeader>
                                        <CardContent className="overflow-hidden pb-12 grid gap-8 h-fit">
                                            <p className="text-gray-400">Pick the voice model to generate speech responses</p>
                                            <DropdownComponent
                                                items={userConfig.voice_model_options}
                                                selected={userConfig.selected_voice_model_config}
                                                callbackFunc={updateModel("voice")} />
                                        </CardContent>
                                        <CardFooter className="flex flex-wrap gap-4">
                                            {!userConfig.is_active && <p className="text-gray-400">Subscribe to switch model</p>}
                                        </CardFooter>
                                    </Card>)}
                                </div>
                            </div>
                            <div className="section grid gap-8">
                                <div id="clients" className="text-2xl">Clients</div>
                                <div className="cards flex flex-wrap gap-8">
                                    {!userConfig.anonymous_mode && (<Card
                                        className="grid grid-flow-column border border-gray-300 shadow-md rounded-lg bg-gradient-to-b from-background to-gray-50 dark:to-gray-950">
                                        <CardHeader className="text-xl grid grid-flow-col grid-cols-[1fr_auto] pb-0">
                                            <span className="flex flex-wrap">
                                                <Key className="h-7 w-7 mr-2" />API Keys</span>
                                            <Button variant="secondary" className="!mt-0" onClick={generateAPIKey}>
                                                <Plus weight="bold" className="h-5 w-5 mr-2" />Generate Key</Button>
                                        </CardHeader>
