                if (typeof linha["Telefone"] == "undefined") {
                    var telefone = "";
                } else
                    var telefone = linha["Telefone"];

                if (typeof linha["Descrição"] == "undefined") {
                    var descricao = "";
                } else
                    var descricao = linha["Descrição"];

                if (typeof linha["Emissão"] == "undefined") {
                    var data_emissao = "";
                } else
                    var data_emissao = linha["Emissão"];

                if (typeof linha["Vencimento"] == "undefined") {
                    var data_vencimento = "";
                } else
                    var data_vencimento = linha["Vencimento"];

                if (typeof linha["Valor"] == "undefined") {
                    var valor = "";
                } else
                    var valor = linha["Valor"];

                if (typeof linha["Valor Pago"] == "undefined") {
                    var valor_pago = "";
                } else
                    var valor_pago = linha["Valor Pago"];

                if (typeof linha["Data Pgto."] == "undefined") {
                    var data_pagamento = "";
                } else
