                } else
                    var link_cobranca = linha["Link da Cobrança"];

                if (typeof linha["Link do Boleto"] == "undefined") {
                    var link_boleto = "";
                } else
                    var link_boleto = linha["Link do Boleto"];

                if (typeof linha["Linha Digitável"] == "undefined") {
                    var linha_digitavel = "";
                } else
                    var linha_digitavel = linha["Linha Digitável"];

                if (typeof linha["Código"] == "undefined") {
                    var codigo = "";
                } else
                    var codigo = linha["Código"];

                if (typeof linha["Status"] == "undefined") {
                    var status = "";
                } else
                    var status = linha["Status"];

                const dados = {
                    socio_nome: linha["Nome Cliente"],
