        log.html_log = "Total cadastrados = " + log.cadastrados + "/" + tabela.length + log.html_log;
        return log;
    }

    function cadastro_socios_xlsx(tabela) {
        log = {
            cadastrados: tabela.length,
            html_log: ""
        };

        for (linha of tabela) {
            if (valida_cpf_cnpj(linha["CPF/CNPJ"])) {
