                const data_nasc = "imp";

                if (typeof linha["TELEFONE"] == "undefined") {
                    var telefone = "";
                } else
                    var telefone = linha["TELEFONE"].replace(" ", "");

                const dados = {
                    socio_nome: linha["NOME/RAZÃO SOCIAL"],
                    pessoa: pessoa,
                    email: email,
                    telefone: telefone,
                    cpf_cnpj: linha["CPF/CNPJ"],
                    rua: linha["ENDEREÇO"],
                    numero: linha["NÚMERO"],
                    complemento: complemento,
                    bairro: linha["BAIRRO"],
                    estado: linha["UF"],
                    cidade: linha["CIDADE"],
                    status: 4,
                    contribuinte: null,
                    data_nasc: data_nasc,
                    cep: linha["CEP"],
                    valor_periodo: null,
                    data_referencia: null
                };

                $.ajax({
                    async: false,
                    url: "cadastro_socio.php",
                    data: dados,
                    type: "POST",

                    success: function(resp) {
                        const r = JSON.parse(resp);

                        if (r) {
                            log.html_log += "<p style='margin: 0.2em' class='text-green'> <b>[CADASTRADO]</b> - " + linha["NOME/RAZÃO SOCIAL"] + "</p> ";
