async create(
    data: string,
    chunk: {
        index: number;
        total: number;
    },
    file: {
        id?: string;
        name: string;
    },
    shareId: string
) {
    if (!file.id)
        file.id = crypto.randomUUID();

    const share = await this.prisma.share.findUnique({
        where: {
            id: shareId
        },

        include: {
            files: true,
            reverseShare: true
        }
    });

    if (share.uploadLocked)
        throw new BadRequestException("Share is already completed");

    let diskFileSize: number;

    try {
        diskFileSize = fs.statSync(`${SHARE_DIRECTORY}/${shareId}/${file.id}.tmp-chunk`).size;
    } catch {
        diskFileSize = 0;
    }

    const chunkSize = this.config.get("share.chunkSize");
    const expectedChunkIndex = Math.ceil(diskFileSize / chunkSize);

    if (expectedChunkIndex != chunk.index) throw new BadRequestException({
        message: "Unexpected chunk received",
        error: "unexpected_chunk_index",
        expectedChunkIndex
    });

    const buffer = Buffer.from(data, "base64");
    const space = await fs.promises.statfs(SHARE_DIRECTORY);
    const availableSpace = space.bavail * space.bsize;

    if (availableSpace < buffer.byteLength) {
        throw new InternalServerErrorException("Not enough space on the server");
    }

    const fileSizeSum = share.files.reduce((
        n,
        {
            size
        }
    ) => n + parseInt(size), 0);

    const shareSizeSum = fileSizeSum + diskFileSize + buffer.byteLength;

    if (shareSizeSum > this.config.get("share.maxSize") || (share.reverseShare?.maxShareSize && shareSizeSum > parseInt(share.reverseShare.maxShareSize))) {
        throw new HttpException("Max share size exceeded", HttpStatus.PAYLOAD_TOO_LARGE);
    }

    fs.appendFileSync(`${SHARE_DIRECTORY}/${shareId}/${file.id}.tmp-chunk`, buffer);
    const isLastChunk = chunk.index == chunk.total - 1;

    if (isLastChunk) {
        fs.renameSync(
            `${SHARE_DIRECTORY}/${shareId}/${file.id}.tmp-chunk`,
            `${SHARE_DIRECTORY}/${shareId}/${file.id}`
        );

        const fileSize = fs.statSync(`${SHARE_DIRECTORY}/${shareId}/${file.id}`).size;

        await this.prisma.file.create({
            data: {
                id: file.id,
                name: file.name,
                size: fileSize.toString(),

                share: {
                    connect: {
                        id: shareId
                    }
                }
            }
        });
    }

    return file;
}

