async function lookupWebFinger(resource: URL | string): Promise<ResourceDescriptor | null> {
    if (typeof resource === "string")
        resource = new URL(resource);

    let protocol = "https:";
    let server: string;

    if (resource.protocol === "acct:") {
        const atPos = resource.pathname.lastIndexOf("@");

        if (atPos < 0)
            return null;

        server = resource.pathname.substring(atPos + 1);

        if (server === "")
            return null;
    } else {
        protocol = resource.protocol;
        server = resource.host;
    }

    let url = new URL(`${protocol}//${server}/.well-known/webfinger`);
    url.searchParams.set("resource", resource.href);
    let redirected = 0;

    while (true) {
        logger.debug("Fetching WebFinger resource descriptor from {url}...", {
            url: url.href
        });

        let response: Response;

        try {
            response = await fetch(url, {
                headers: {
                    Accept: "application/jrd+json"
                },

                redirect: "manual"
            });
        } catch (error) {
            logger.debug("Failed to fetch WebFinger resource descriptor: {error}", {
                url: url.href,
                error
            });

            return null;
        }

        if (response.status >= 300 && response.status < 400 && response.headers.has("Location")) {
            redirected++;

            if (redirected >= MAX_REDIRECTION) {
                logger.error(
                    "Too many redirections ({redirections}) while fetching WebFinger " + "resource descriptor.",
                    {
                        redirections: redirected
                    }
                );

                return null;
            }

            const redirectedUrl = new URL(
                response.headers.get("Location")!,
                response.url == null || response.url === "" ? url : response.url
            );

            if (redirectedUrl.protocol !== url.protocol) {
                logger.error(
                    "Redirected to a different protocol ({protocol} to " + "{redirectedProtocol}) while fetching WebFinger resource " + "descriptor.",
                    {
                        protocol: url.protocol,
                        redirectedProtocol: redirectedUrl.protocol
                    }
                );

                return null;
            }

            url = redirectedUrl;
            continue;
        }

        if (!response.ok) {
            logger.debug("Failed to fetch WebFinger resource descriptor: {status} {statusText}.", {
                url: url.href,
                status: response.status,
                statusText: response.statusText
            });

            return null;
        }

        try {
            return (await response.json()) as ResourceDescriptor;
        } catch (e) {
            if (e instanceof SyntaxError) {
                logger.debug("Failed to parse WebFinger resource descriptor as JSON: {error}", {
                    error: e
                });

                return null;
            }

            throw e;
        }
    }
}

