function extractBody(object, keepalive = false) {
    if (!ReadableStream) {
        ReadableStream = require("stream/web").ReadableStream;
    }

    let stream = null;

    if (object instanceof ReadableStream) {
        stream = object;
    } else if (isBlobLike(object)) {
        stream = object.stream();
    } else {
        stream = new ReadableStream({
            async pull(controller) {
                controller.enqueue(typeof source === "string" ? textEncoder.encode(source) : source);
                queueMicrotask(() => readableStreamClose(controller));
            },

            start() {},
            type: undefined
        });
    }

    assert(isReadableStreamLike(stream));
    let action = null;
    let source = null;
    let length = null;
    let type = null;

    if (typeof object === "string") {
        source = object;
        type = "text/plain;charset=UTF-8";
    } else if (object instanceof URLSearchParams) {
        source = object.toString();
        type = "application/x-www-form-urlencoded;charset=UTF-8";
    } else if (isArrayBuffer(object)) {
        source = new Uint8Array(object.slice());
    } else if (ArrayBuffer.isView(object)) {
        source = new Uint8Array(
            object.buffer.slice(object.byteOffset, object.byteOffset + object.byteLength)
        );
    } else if (util.isFormDataLike(object)) {
        const boundary = `----formdata-undici-0${`${Math.floor(Math.random() * 1e11)}`.padStart(11, "0")}`;
        const prefix = `--${boundary}\r\nContent-Disposition: form-data`;
        const escape = str => str.replace(/\n/g, "%0A").replace(/\r/g, "%0D").replace(/"/g, "%22");
        const normalizeLinefeeds = value => value.replace(/\r?\n|\r/g, "\r\n");
        const blobParts = [];
        const rn = new Uint8Array([13, 10]);
        length = 0;
        let hasUnknownSizeValue = false;

        for (const [name, value] of object) {
            if (typeof value === "string") {
                const chunk = textEncoder.encode(
                    prefix + `; name="${escape(normalizeLinefeeds(name))}"` + `\r\n\r\n${normalizeLinefeeds(value)}\r\n`
                );

                blobParts.push(chunk);
                length += chunk.byteLength;
            } else {
                const chunk = textEncoder.encode(
                    `${prefix}; name="${escape(normalizeLinefeeds(name))}"` + (value.name ? `; filename="${escape(value.name)}"` : "") + "\r\n" + `Content-Type: ${value.type || "application/octet-stream"}\r\n\r\n`
                );

                blobParts.push(chunk, value, rn);

                if (typeof value.size === "number") {
                    length += chunk.byteLength + value.size + rn.byteLength;
                } else {
                    hasUnknownSizeValue = true;
                }
            }
        }

        const chunk = textEncoder.encode(`--${boundary}--`);
        blobParts.push(chunk);
        length += chunk.byteLength;

        if (hasUnknownSizeValue) {
            length = null;
        }

        source = object;

        action = async function*() {
            for (const part of blobParts) {
                if (part.stream) {
                    yield* part.stream();
                } else {
                    yield part;
                }
            }
        };

        type = "multipart/form-data; boundary=" + boundary;
    } else if (isBlobLike(object)) {
        source = object;
        length = object.size;

        if (object.type) {
            type = object.type;
        }
    } else if (typeof object[Symbol.asyncIterator] === "function") {
        if (keepalive) {
            throw new TypeError("keepalive");
        }

        if (util.isDisturbed(object) || object.locked) {
            throw new TypeError("Response body object should not be disturbed or locked");
        }

        stream = object instanceof ReadableStream ? object : ReadableStreamFrom(object);
    }

    if (typeof source === "string" || util.isBuffer(source)) {
        length = Buffer.byteLength(source);
    }

    if (action != null) {
        let iterator;

        stream = new ReadableStream({
            async start() {
                iterator = action(object)[Symbol.asyncIterator]();
            },

            async pull(controller) {
                const {
                    value,
                    done
                } = await iterator.next();

                if (done) {
                    queueMicrotask(() => {
                        controller.close();
                    });
                } else {
                    if (!isErrored(stream)) {
                        controller.enqueue(new Uint8Array(value));
                    }
                }

                return controller.desiredSize > 0;
            },

            async cancel(reason) {
                await iterator.return();
            },

            type: undefined
        });
    }

    const body = {
        stream,
        source,
        length
    };

    return [body, type];
}

