}

async function ensureDirectoryExists(filePath) {
    const dir = path.dirname(filePath);

    try {
        await fs.promises.mkdir(dir, {
            recursive: true
        });
    } catch (err) {
        log.error(`Failed to create directory ${dir}: ${err.message}`);
        throw err;
    }
}

function safeCompare(a, b) {
    if (typeof a !== "string" || typeof b !== "string") {
        return false;
    }

    return crypto.timingSafeEqual(Buffer.from(a.padEnd(32)), Buffer.from(b.padEnd(32)));
}

(req, res) => {
    const {
        pin
    } = req.body;

    const ip = req.ip;

    if (!PIN) {
        return res.json({
            success: true
        });
    }

    if (isLockedOut(ip)) {
        const attempts = loginAttempts.get(ip);
        const timeLeft = Math.ceil((LOCKOUT_TIME - (Date.now() - attempts.lastAttempt)) / 1000 / 60);

        return res.status(429).json({
            error: `Too many attempts. Please try again in ${timeLeft} minutes.`
        });
    }

    if (safeCompare(pin, PIN)) {
        resetAttempts(ip);

        res.cookie("DUMBDROP_PIN", pin, {
            httpOnly: true,
            secure: process.env.NODE_ENV === "production",
            sameSite: "strict",
            path: "/"
        });

        res.json({
            success: true
        });
    } else {
        const attempts = recordAttempt(ip);
        const attemptsLeft = MAX_ATTEMPTS - attempts.count;

        res.status(401).json({
            success: false,
            error: attemptsLeft > 0 ? `Invalid PIN. ${attemptsLeft} attempts remaining.` : "Too many attempts. Account locked for 15 minutes."
        });
    }
}

