        const sanitizedFilename = JSON.stringify(filename).slice(1, -1);
        const message = APPRISE_MESSAGE.replace("{filename}", sanitizedFilename).replace("{size}", formattedSize).replace("{storage}", totalStorage);

        await execAsync(["apprise", APPRISE_URL, "-b", message], {
            shell: false
        });

        log.info(
            `Notification sent for: ${sanitizedFilename} (${formattedSize}, Total storage: ${totalStorage})`
        );
    } catch (err) {
        log.error(`Failed to send notification: ${err.message}`);
    }
}

