public sanitizeHtml(html: string, options: SanitizeHtmlOptions = null) {
    options = {
        addNoMdConvClass: false,
        ...options
    };

    options.allowedFilePrefixes ??= [];
    const output: string[] = [];
    const tagStack: string[] = [];

    const currentTag = () => {
        if (!tagStack.length)
            return "";

        return tagStack[tagStack.length - 1];
    };

    let disallowedTagDepth = 0;

    const disallowedTags = [
        "script",
        "iframe",
        "frameset",
        "frame",
        "object",
        "base",
        "embed",
        "link",
        "meta",
        "noscript",
        "button",
        "input",
        "select",
        "textarea",
        "option",
        "optgroup",
        "svg",
        "map",
        "area"
    ];

    const replaceWithDivTags = ["form"];

    const parser = new htmlparser2.Parser({
        oncomment: (encodedData: string) => {
            output.push(`<!--${encodedData}-->`);
        },

        onopentag: (name: string, attrs: Record<string, string>) => {
            tagStack.push(name);

            if (disallowedTags.includes(currentTag())) {
                disallowedTagDepth++;
                return;
            }

            if (disallowedTagDepth)
                return;

            if (replaceWithDivTags.includes(currentTag())) {
                output.push("<div>");
                return;
            }

            attrs = {
                ...attrs
            };

            if ("name" in attrs) {
                const oldName = attrs["name"];
                delete attrs["name"];

                if (!("id" in attrs)) {
                    attrs["id"] = oldName;
                }
            }

            for (const attrName in attrs) {
                if (!attrs.hasOwnProperty(attrName))
                    continue;

                if (attrName.length <= 2)
                    continue;

                if (attrName.substr(0, 2) !== "on")
                    continue;

                delete attrs[attrName];
            }

            if ("href" in attrs && !this.isAcceptedUrl(attrs["href"], options.allowedFilePrefixes)) {
                attrs["href"] = "#";
            }

            if ("data-from-md" in attrs) {
                delete attrs["data-from-md"];
            }

            if (options.addNoMdConvClass) {
                let classAttr = attrs["class"] || "";

                if (!classAttr.includes("jop-noMdConv")) {
                    classAttr += " jop-noMdConv";
                    attrs["class"] = classAttr.trim();
                }
            }

            if (name === "a" && !attrs["href"]) {
                attrs["href"] = "#";
            }

            let attrHtml = attributesHtml(attrs);

            if (attrHtml)
                attrHtml = ` ${attrHtml}`;

            const closingSign = isSelfClosingTag(name) ? "/>" : ">";
            output.push(`<${name}${attrHtml}${closingSign}`);
        },

        ontext: (decodedText: string) => {
            if (disallowedTagDepth)
                return;

            if (currentTag() === "style") {
                output.push(decodedText.replace(/</g, "&lt;"));
            } else {
                output.push(htmlentities(decodedText));
            }
        },

        onclosetag: (name: string) => {
            const current = currentTag();

            if (current === name.toLowerCase())
                tagStack.pop();

            if (disallowedTags.includes(current) || disallowedTags.includes(name)) {
                if (disallowedTagDepth > 0) {
                    disallowedTagDepth--;
                }

                return;
            }

            if (disallowedTagDepth)
                return;

            if (replaceWithDivTags.includes(currentTag())) {
                output.push("</div>");
                return;
            }

            if (isSelfClosingTag(name))
                return;

            output.push(`</${name}>`);
        }
    }, {
        decodeEntities: true
    });

    parser.write(html);
    parser.end();
    return output.join("");
}

