(html: string) => {
    if (!html.startsWith("<p>"))
        return html;

    const stack: string[] = [];
    const output: string[] = [];
    let inFirstParagraph = true;
    let canSimplify = true;

    const parser = new htmlparser2.Parser({
        onopentag: (name: string, attrs: Record<string, string>) => {
            if (inFirstParagraph && stack.length > 0) {
                output.push(makeHtmlTag(name, attrs));
            } else if (!inFirstParagraph && attrs.style) {
                canSimplify = false;
            }

            stack.push(name);
        },

        ontext: (encodedText: string) => {
            if (encodedText.trim() && !inFirstParagraph) {
                canSimplify = false;
            } else {
                output.push(encodedText);
            }
        },

        onclosetag: (name: string) => {
            stack.pop();

            if (stack.length === 0 && name === "p") {
                inFirstParagraph = false;
            } else if (inFirstParagraph) {
                if (isSelfClosingTag(name))
                    return;

                output.push(`</${name}>`);
            } else if (!["div", "style", "span"].includes(name)) {
                canSimplify = false;
            }
        }
    });

    parser.write(html);
    parser.end();
    return canSimplify ? output.join("") : html;
}

(html: string) => {
    let imageCount = 0;
    let nonImageFound = false;
    let textFound = false;
    const ignoredTags = ["meta", "head", "body", "html"];

    const parser = new htmlparser2.Parser({
        onopentag: (name: string) => {
            if (name === "img") {
                imageCount++;
            } else if (ignoredTags.includes(name))
                {} else {
                nonImageFound = true;
            }
        },

        ontext: (text: string) => {
            if (text.trim())
                textFound = true;
        }
    });

    parser.write(html);
    parser.end();
    return imageCount === 1 && !nonImageFound && !textFound;
}

public renderItem(item: GotoAnythingSearchResult, index: number) {
    const theme = themeStyle(this.props.themeId);
    const style = this.style();
    const resultId = getResultId(item);
    const isSelected = resultId === this.state.selectedItemId;
    const rowStyle = isSelected ? style.rowSelected : style.row;

    const wrapKeywordMatches = (unescapedContent: string) => {
        return surroundKeywords(
            this.state.keywords,
            unescapedContent,
            `<span class="match-highlight" style="font-weight: bold; color: ${theme.searchMarkerColor}; background-color: ${theme.searchMarkerBackgroundColor}">`,
            "</span>",
            {
                escapeHtml: true
            }
        );
    };

    const titleHtml = item.fragments ? `<span style="font-weight: bold; color: ${theme.color};">${item.title}</span>` : wrapKeywordMatches(item.title);
    const fragmentsHtml = !item.fragments ? null : wrapKeywordMatches(item.fragments);

    const folderIcon = (<i
        style={{
            fontSize: theme.fontSize,
            marginRight: 2
        }}
        className="fa fa-book"
        role="img"
        aria-label={_("Notebook")} />);

    const pathComp = !item.path ? null : (<div style={style.rowPath}>
        {folderIcon} {item.path}
    </div>);

    const fragmentComp = !fragmentsHtml ? null : (<div
        style={style.rowFragments}
        dangerouslySetInnerHTML={{
            __html: fragmentsHtml
        }}></div>);

    return (
        (<div
            key={resultId}
            className={isSelected ? "selected" : null}
            style={rowStyle}
            onClick={this.listItem_onClick}
            data-id={item.id}
            data-parent-id={item.parent_id}
            data-type={item.type}
            role="option"
            id={resultId}
            aria-posinset={index + 1}>
            <div
                style={style.rowTitle}
                dangerouslySetInnerHTML={{
                    __html: titleHtml
                }}></div>
            {fragmentComp}
            {pathComp}
        </div>)
    );
}

(
    result: GotoAnythingSearchResult,
    notesById: Record<string, NoteEntity>,
    resources: ResourceEntity[]
) => {
    if (result.item_type === ModelType.Resource) {
        const resource = resources.find(r => r.id === result.item_id);

        if (!resource) {
            logger.warn("Could not find resources associated with result:", result);

            return {
                markupLanguage: MarkupLanguage.Markdown,
                content: ""
            };
        } else {
            return {
                markupLanguage: MarkupLanguage.Markdown,
                content: resource.ocr_text
            };
        }
    } else {
        const note = notesById[result.id];

        return {
            markupLanguage: note.markup_language,
            content: note.body
        };
    }
}

