function fetchAccount(token: string, id?: string, forceShowDialog?: boolean): Promise<Account> {
    document.cookie = "token=; path=/; max-age=0";
    document.cookie = `token=${token}; path=/queue; max-age=86400; SameSite=Strict; Secure`;

    return new Promise((done, fail) => {
        window.fetch(`${apiUrl}/i`, {
            method: "POST",

            body: JSON.stringify({
                i: token
            }),

            headers: {
                "Content-Type": "application/json"
            }
        }).then(res => new Promise<Account | {
            error: Record<string, any>;
        }>((done2, fail2) => {
            if (res.status >= 500 && res.status < 600) {
                return fail2(res);
            }

            res.json().then(done2, fail2);
        })).then(async res => {
            if ("error" in res) {
                if (res.error.id === "a8c724b3-6e9c-4b46-b1a8-bc3ed6258370") {
                    if (forceShowDialog || ($i && (token === $i.token || id === $i.id))) {
                        await showSuspendedDialog();
                    }
                } else if (res.error.id === "e5b3b9f0-2b8f-4b9f-9c1f-8c5c1b2e1b1a") {
                    if (forceShowDialog || ($i && (token === $i.token || id === $i.id))) {
                        await alert({
                            type: "error",
                            title: i18n.ts.accountDeleted,
                            text: i18n.ts.accountDeletedDescription
                        });
                    }
                } else if (res.error.id === "b0a7f5f8-dc2f-4171-b91f-de88ad238e14") {
                    if (forceShowDialog || ($i && (token === $i.token || id === $i.id))) {
                        await alert({
                            type: "error",
                            title: i18n.ts.tokenRevoked,
                            text: i18n.ts.tokenRevokedDescription
                        });
                    }
                } else {
                    await alert({
                        type: "error",
                        title: i18n.ts.failedToFetchAccountInformation,
                        text: JSON.stringify(res.error)
                    });
                }

                fail(true);
            } else {
                (res as Account).token = token;
                done(res as Account);
            }
        }).catch(fail);
    });
}

