function parse(str = "", format = "ms") {
    let result = null;
    let prevUnits;

    (str + "").replace(/(\d)[_ ](\d)/g, "$1$2").replaceAll(parse.unit.group, "").replaceAll(parse.unit.decimal, ".").replace(durationRE, (_, n, units) => {
        if (!units) {
            if (prevUnits) {
                for (const u in parse.unit) if (parse.unit[u] < prevUnits) {
                    units = u;
                    break;
                }
            } else
                units = format;
        } else
            units = units.toLowerCase();

        units = parse.unit[units] || parse.unit[units.replace(/s$/, "")];

        if (units)
            ((result = (result || 0) + Math.abs(parseFloat(n, 10)) * units), (prevUnits = units));
    });

    return result && (result / (parse.unit[format] || 1)) * (str[0] === "-" ? -1 : 1);
}

function parse(str = "", format = "ms") {
    let result = null;
    let prevUnits;

    String(str).replace(
        new RegExp(`(\\d)[${parse.unit.placeholder}${parse.unit.group}](\\d)`, "g"),
        "$1$2"
    ).replace(parse.unit.decimal, ".").replace(durationRE, (_, n, units) => {
        if (!units) {
            if (prevUnits) {
                for (const u in parse.unit) if (parse.unit[u] < prevUnits) {
                    units = u;
                    break;
                }
            } else
                units = format;
        } else
            units = units.toLowerCase();

        prevUnits = units = parse.unit[units] || parse.unit[units.replace(/s$/, "")];

        if (units)
            result = (result || 0) + n * units;
    });

    return result && (result / (parse.unit[format] || 1)) * (str[0] === "-" ? -1 : 1);
}

