            return res.send({
                success: false,
                status: 403,
                message: "Please authenticate first.",
                data: {}
            });
        }

        const {
            archive
        } = req.files;

        const randomName = crypto.randomBytes(16).toString("hex");
        const filepath = path.join("/tmp", `${randomName}`);
        await archive.mv(filepath);

        const result = await new Promise(resolve => {
            execFile(
                `${process.cwd()}/scripts/restore.sh`,
                [config.get("mongo.host"), config.get("mongo.port"), filepath],
                (error, stdout, stderr) => {
                    if (error) {
                        resolve({
                            code: 1,
                            stdout,
                            stderr,
                            error
                        });

                        return;
                    }

                    resolve({
                        code: 0,
                        stdout,
                        stderr
                    });
                }
            );
        });

        if (result.code !== 0) {
            slack.sendMessage(`The restore has failed.`, {
                symbol: "global"
            });

            return res.send({
                success: false,
                status: 500,
                message: "Restore failed",
                data: result
            });
        }

        return res.send({
            success: true,
            status: 200,
            message: "Restore success",
            data: result
        });
    });
}

