    function gotdir(e) {
        ev(e);
        const good_files = [];
        const nil_files = [];
        const bad_files = [];

        for (let a = 0, aa = e.target.files.length; a < aa; a++) {
            const fobj = e.target.files[a];
            const name = fobj.webkitRelativePath;
            let dst = good_files;

            try {
                if (!name)
                    throw 1;

                if (fobj.size < 1)
                    dst = nil_files;
            } catch (ex) {
                dst = bad_files;
            }

            dst.push([fobj, name]);
        }

        if (!good_files.length && bad_files.length)
            return toast.err(30, L.u_notdir);

        return read_dirs(null, [], [], good_files, nil_files, bad_files);
    }

    function gotfile(e) {
        ev(e);
        nenters = 0;
        offdrag.call(this);
        let dz = this && this.getAttribute("id");

        if (!dz && e && e.clientY)
            dz = e.clientY < window.innerHeight / 2 ? "up_dz" : "srch_dz";

        const err = this.getAttribute("err");

        if (err)
            return modal.alert("sorry, " + err);

        toast.inf(0, L.u_scan);

        if ((dz == "up_dz" && uc.fsearch) || (dz == "srch_dz" && !uc.fsearch))
            tgl_fsearch();

        if (!QS("#op_up2k.act"))
            goto("up2k");

        let files;
        let is_itemlist = false;

        if (e.dataTransfer) {
            if (e.dataTransfer.items) {
                files = e.dataTransfer.items;
                is_itemlist = true;
            } else
                files = e.dataTransfer.files;
        } else
            files = e.target.files;

        if (!files || !files.length)
            return toast.err(0, "no files selected??");

        more_one_file();
        const bad_files = [];
        const nil_files = [];
        const good_files = [];
        const dirs = [];

        for (let a = 0; a < files.length; a++) {
            let fobj = files[a];
            let dst = good_files;

            if (is_itemlist) {
                if (fobj.kind !== "file" && fobj.type !== "text/uri-list")
                    continue;

                try {
                    const wi = fobj.getAsEntry ? fobj.getAsEntry() : fobj.webkitGetAsEntry();

                    if (wi.isDirectory) {
                        dirs.push(wi);
                        continue;
                    }
                } catch (ex) {}

                fobj = fobj.getAsFile();

                if (!fobj)
                    continue;
            }

            try {
                if (fobj.size < 1)
                    dst = nil_files;
            } catch (ex) {
                dst = bad_files;
            }

            dst.push([fobj, fobj.name]);
        }

        start_actx();
        return read_dirs(null, [], dirs, good_files, nil_files, bad_files);
    }

    function rd_flatten(pf, dirs) {
        const ret = jcp(pf);

        for (let a = 0; a < dirs.length; a++)
            ret.push(dirs.fullPath || "");

        ret.sort();
        return ret;
    }

    let rd_missing_ref = [];

    function read_dirs(rd, pf, dirs, good, nil, bad, spins) {
        spins = spins || 0;

        if (++spins == 5)
            rd_missing_ref = rd_flatten(pf, dirs);

        if (spins == 200) {
            const missing = rd_flatten(pf, dirs);
            let match = rd_missing_ref.length == missing.length;
            const aa = match ? missing.length : 0;
            missing.sort();

            for (var a = 0; a < aa; a++) if (rd_missing_ref[a] != missing[a])
                match = false;

            if (match) {
                const msg = [L.u_dirstuck.format(missing.length) + "<ul>"];

                for (var a = 0; a < Math.min(20, missing.length); a++)
                    msg.push("<li>" + esc(missing[a]) + "</li>");

                return modal.alert(msg.join("") + "</ul>", function() {
                    read_dirs(rd, [], [], good, nil, bad, spins);
                });
            }

            spins = 0;
        }

        if (!dirs.length) {
            if (!pf.length)
                return r.gotallfiles[0](good, nil, bad, r.gotallfiles.slice(1));

            console.log("retry pf, " + pf.length);

            setTimeout(function() {
                read_dirs(rd, pf, dirs, good, nil, bad, spins);
            }, 50);

            return;
        }

        if (!rd)
            rd = dirs[0].createReader();

        rd.readEntries(function(ents) {
            let ngot = 0;

            ents.forEach(function(dn) {
                if (dn.isDirectory) {
                    dirs.push(dn);
                } else {
                    let name = dn.fullPath;

                    if (name.startsWith("/"))
                        name = name.slice(1);

                    pf.push(name);

                    dn.file(function(fobj) {
                        apop(pf, name);
                        let dst = good;

                        try {
                            if (fobj.size < 1)
                                dst = nil;
                        } catch (ex) {
                            dst = bad;
                        }

                        dst.push([fobj, name]);
                    });
                }

                ngot += 1;
            });

            if (!ngot) {
                dirs.shift();
                rd = null;
            }

            read_dirs(rd, pf, dirs, good, nil, bad, spins);
        }, function() {
            const dn = dirs[0];
            let name = dn.fullPath;

            if (name.startsWith("/"))
                name = name.slice(1);

            bad.push([dn, name + "/"]);
            read_dirs(null, pf, dirs.slice(1), good, nil, bad, spins);
        });
    }

