    function up_them(good_files) {
        start_actx();
        draw_turbo();
        const evpath = get_evpath();
        const draw_each = good_files.length < 50;

        if (WebAssembly && !hws.length) {
            let nw = Math.min(navigator.hardwareConcurrency || 4, 16);

            if (CHROME) {
                nw = Math.max(1, nw > 4 ? 4 : nw - 1);
                nw = subtle && !MOBILE && nw > 2 ? 2 : nw;
