            let fdir = evpath;
            const now = Date.now();
            const lmod = uc.u2ts ? fobj.lastModified || now : 0;
            const ofs = name.lastIndexOf("/") + 1;

            if (ofs) {
                fdir += url_enc(name.slice(0, ofs));
                name = name.slice(ofs);
            }

            const entry = {
                n: st.files.length,
                t0: now,
                fobj: fobj,
                name: name,
                size: fobj.size || 0,
                lmod: lmod / 1000,
                purl: fdir,
                done: false,
                bytes_uploaded: 0,
                hash: []
            };

            const key = name + "\n" + entry.size + "\n" + lmod + "\n" + uc.fsearch;

            if (uc.fsearch)
                entry.srch = 1;
            else if (uc.rand) {
                entry.rand = true;
                entry.name = "a\n" + entry.name;
            } else if (uc.umod)
                entry.umod = true;

            if (biggest_file < entry.size)
                biggest_file = entry.size;

            try {
                if (st.seen[fdir][key])
                    continue;
            } catch (ex) {
                st.seen[fdir] = {};
            }

            st.seen[fdir][key] = 1;

            pvis.addfile([
                uc.fsearch ? esc(entry.name) : linksplit(entry.purl + uricom_enc(entry.name)).join(" / "),
                "📐 " + L.u_hashing,
                ""
            ], entry.size, draw_each);

            st.bytes.total += entry.size;
            st.files.push(entry);

            if (uc.turbo)
                push_t(st.todo.head, entry);
            else
                push_t(st.todo.hash, entry);
        }

        if (!draw_each) {
            pvis.drawcard("q");
            pvis.changecard(pvis.act);
