    function handshakes_permitted() {
        if (!st.todo.handshake.length)
            return true;

        const t = st.todo.handshake[0];
        const cd = t.cooldown;

        if (cd && cd > Date.now())
            return false;

        if (t.keepalive || t.t_uploaded)
            return true;

        if (parallel_uploads < st.busy.handshake.length)
            return false;

        if (t.n - st.car > Math.max(8, parallel_uploads))
            return false;

        if ((uc.multitask ? parallel_uploads : 0) < st.todo.upload.length + st.busy.upload.length)
            return false;

        return true;
    }

    function hashing_permitted() {
        if (!parallel_uploads)
            return false;

        const nhs = st.todo.handshake.length + st.busy.handshake.length;
        const nup = st.todo.upload.length + st.busy.upload.length;

        if (uc.multitask) {
            if (nhs + nup < parallel_uploads)
                return true;

            if (!uc.az)
                return nhs < 2;

            const ahead = st.bytes.hashed - st.bytes.finished;
            const nmax = ahead < biggest_file / 8 ? 32 : 16;
            return ahead < biggest_file && nhs < nmax;
        }

        return handshakes_permitted() && 0 == nhs + nup;
    }

    const tasker = (function() {
        let running = false;
        let was_busy = false;

        const defer = function() {
            running = false;
        };

        const taskerd = function() {
            if (running)
                return;

            if (crashed || !got_deps())
                return defer();

            running = true;

            while (true) {
                const now = Date.now();
                const blocktime = now - r.tact;
                let is_busy = st.car < st.files.length;

                if (blocktime > 2500)
                    console.log("main thread blocked for " + blocktime);

                r.tact = now;

                if (was_busy && !is_busy) {
                    for (var a = 0; a < st.files.length; a++) {
                        var t = st.files[a];

                        if (t.want_recheck) {
                            t.rechecks++;
                            t.want_recheck = false;
                            push_t(st.todo.handshake, t);
                        }
                    }

                    is_busy = st.todo.handshake.length;

                    try {
                        if (!is_busy && !uc.fsearch && !msel.getsel().length && (!mp.au || mp.au.paused))
                            treectl.goto();
                    } catch (ex) {}
                }

                if (was_busy != is_busy) {
                    st.is_busy = was_busy = is_busy;
                    window[(is_busy ? "add" : "remove") + "EventListener"]("beforeunload", warn_uploader_busy);
                    donut.on(is_busy);

                    if (!is_busy) {
                        uptoast();
                    } else {
                        timer.add(donut.do);
                        timer.add(etafun, false);
                        ebi("u2etas").style.textAlign = "left";
                    }

                    etafun();
                }

                if (flag) {
                    if (is_busy) {
                        flag.take(now);
                        ebi("u2flagblock").style.display = flag.ours ? "" : "block";

                        if (!flag.ours)
                            return defer();
                    } else if (flag.ours) {
                        flag.give();
                    }
                }

                if (st.bytes.inflight && (st.bytes.inflight < 0 || !st.busy.upload.length)) {
                    console.log("insane inflight " + st.bytes.inflight);
                    st.bytes.inflight = 0;
                }

                let mou_ikkai = false;
                let nprev = -1;

                for (var a = 0; a < st.todo.upload.length; a++) {
                    const nf = st.todo.upload[a].nfile;

                    if (nprev == nf)
                        continue;

                    nprev = nf;
                    var t = st.files[nf];

                    if (now - t.t_busied > 1000 * 30 && now - t.t_handshake > 1000 * (21600 - 1800)) {
                        apop(st.todo.handshake, t);
                        st.todo.handshake.unshift(t);
                        t.keepalive = true;
                    }
                }

                if (st.todo.head.length && st.busy.head.length < parallel_uploads && (!is_busy || st.todo.head[0].n - st.car < parallel_uploads * 2)) {
                    exec_head();
                    mou_ikkai = true;
                }

                if (handshakes_permitted() && st.todo.handshake.length) {
                    exec_handshake();
                    mou_ikkai = true;
                }

                if (st.todo.upload.length && st.busy.upload.length < parallel_uploads && can_upload_next()) {
                    exec_upload();
                    mou_ikkai = true;
                }

                if (hashing_permitted() && st.todo.hash.length && !st.busy.hash.length) {
                    exec_hash();
                    mou_ikkai = true;
                }

                if (is_busy && st.modn < 100) {
                    const t0 = Date.now() + (ebi("repl").offsetTop ? 0 : 0);

                    if (++st.modn >= 10) {
                        if (st.modn == 10)
                            st.mod0 = Date.now();

                        st.modv += Date.now() - t0;
                    }

                    if (st.modn >= 100) {
                        const n = st.modn - 10;
                        const ipu = st.modv / n;
                        const spu = (Date.now() - st.mod0) / n;
                        const ir = spu / ipu;
                        console.log("tsk:", f2f(ipu, 2), " spu:", f2f(spu, 2), " ir:", f2f(ir, 2));

                        if (ipu >= 0.5 && ir <= 15)
                            pvis.go_potato();
                    }
                }

                if (!mou_ikkai || crashed)
                    return defer();
            }
        };

        timer.add(taskerd, true);
        return taskerd;
    })();

    function uptoast() {
        if (st.busy.handshake.length)
            return;

        for (let a = 0; a < st.files.length; a++) {
            var t = st.files[a];

            if (t.want_recheck && !t.rechecks)
                return;
        }

        const sr = uc.fsearch;
        const ok = pvis.ctr.ok;
        const ng = pvis.ctr.ng;
        const spd = Math.floor(st.bytes.finished / st.time.busy);
        const suf = "\n\n{0} @ {1}/s".format(shumantime(st.time.busy), humansize(spd));
        var t = uc.ask_up ? 0 : 10;
        console.log("toast", ok, ng);

        if (ok && ng)
            toast.warn(t, (uc.nagtxt = (sr ? L.ur_sm : L.ur_um).format(ok, ng) + suf));
        else if (ok > 1)
            toast.ok(t, (uc.nagtxt = (sr ? L.ur_aso : L.ur_auo).format(ok) + suf));
        else if (ok)
            toast.ok(t, (uc.nagtxt = (sr ? L.ur_1so : L.ur_1uo) + suf));
        else if (ng > 1)
            toast.err(t, (uc.nagtxt = (sr ? L.ur_asn : L.ur_aun).format(ng) + suf));
        else if (ng)
            toast.err(t, (uc.nagtxt = (sr ? L.ur_1sn : L.ur_1un) + suf));

        timer.rm(etafun);
        timer.rm(donut.do);
        ebi("u2tabw").style.minHeight = "0px";
        utw_minh = 0;

        if (pvis.act == "bz")
            pvis.changecard("bz");
    }

    function chill(t) {
        const now = Date.now();

        if ((t.coolmul || 0) < 5 || now - t.cooldown < t.coolmul * 700)
            t.coolmul = Math.min((t.coolmul || 0.5) * 2, 32);

        const cd = now + 1000 * (t.coolmul + Math.random() * 4 + 2);
        t.cooldown = Math.floor(Math.max(cd, t.cooldown || 1));
        return t;
    }

    function buf2b64(arrayBuffer) {
        let base64 = "";
        const cset = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
        const src = new Uint8Array(arrayBuffer);
        const nbytes = src.byteLength;
        const byteRem = nbytes % 3;
        const mainLen = nbytes - byteRem;
        let a;
        let b;
        let c;
        let d;
        let chunk;

        for (let i = 0; i < mainLen; i = i + 3) {
            chunk = (src[i] << 16) | (src[i + 1] << 8) | src[i + 2];
            a = (chunk & 16515072) >> 18;
            b = (chunk & 258048) >> 12;
            c = (chunk & 4032) >> 6;
            d = chunk & 63;
            base64 += cset[a] + cset[b] + cset[c] + cset[d];
        }

        if (byteRem == 1) {
            chunk = src[mainLen];
            a = (chunk & 252) >> 2;
            b = (chunk & 3) << 4;
            base64 += cset[a] + cset[b];
        } else if (byteRem == 2) {
            chunk = (src[mainLen] << 8) | src[mainLen + 1];
            a = (chunk & 64512) >> 10;
            b = (chunk & 1008) >> 4;
            c = (chunk & 15) << 2;
            base64 += cset[a] + cset[b] + cset[c];
        }

        return base64;
    }

    function hex2u8(txt) {
        return new Uint8Array(txt.match(/.{2}/g).map(function(b) {
            return parseInt(b, 16);
        }));
    }

    function get_chunksize(filesize) {
        let chunksize = 1024 * 1024;
        let stepsize = 512 * 1024;

        while (true) {
            for (let mul = 1; mul <= 2; mul++) {
                const nchunks = Math.ceil(filesize / chunksize);

                if (nchunks <= 256 || (chunksize >= 32 * 1024 * 1024 && nchunks <= 4096))
                    return chunksize;

                chunksize += stepsize;
                stepsize *= mul;
            }
        }
    }

    function exec_hash() {
        const t = st.todo.hash.shift();

        if (!t.size)
            return st.todo.handshake.push(t);

        st.busy.hash.push(t);
        st.nfile.hash = t.n;
        t.t_hashing = Date.now();
        let bpend = 0;
        let nchunk = 0;
        const chunksize = get_chunksize(t.size);
        const nchunks = Math.ceil(t.size / chunksize);
        const csz_mib = chunksize / 1048576;
        let tread = t.t_hashing;
        let cache_buf = null;
        let cache_car = 0;
        let cache_cdr = 0;
        let hashers = 0;
        const hashtab = {};
        const use_workers = hws.length && !hws_ng && uc.hashw && (nchunks > 1 || document.visibilityState == "hidden");
        const hash_par = !subtle && !use_workers ? 0 : csz_mib < 48 ? 2 : csz_mib < 96 ? 1 : 0;
        pvis.setab(t.n, nchunks);
        pvis.move(t.n, "bz");

        if (use_workers)
            return wexec_hash(t, chunksize, nchunks);

        const segm_next = function() {
            if (nchunk >= nchunks || bpend)
                return false;

            const nch = nchunk++;
            const car = nch * chunksize;
            const cdr = Math.min(chunksize + car, t.size);
            st.bytes.hashed += cdr - car;
            st.etac.h++;

            if (MOBILE && CHROME && st.slow_io === null && nch == 1 && cdr - car >= 1024 * 512) {
                const spd = Math.floor((cdr - car) / (Date.now() + 1 - tread));
                st.slow_io = spd < 40 * 1024;
                console.log("spd {0}, slow: {1}".format(spd, st.slow_io));
            }

            if (cdr <= cache_cdr && car >= cache_car) {
                try {
                    const ofs = car - cache_car;
                    const ofs2 = ofs + (cdr - car);
                    const buf = cache_buf.subarray(ofs, ofs2);
                    hash_calc(nch, buf);
                } catch (ex) {
                    vis_exh(ex + "", "up2k.js", "", "", ex);
                }

                return;
            }

            const reader = new FileReader();
            let fr_cdr = cdr;

            if (st.slow_io) {
                const step = cdr - car;
                const tgt = 48 * 1048576;

                while (step && fr_cdr - car < tgt)
                    fr_cdr += step;

                if (fr_cdr - car > tgt && fr_cdr > cdr)
                    fr_cdr -= step;

                if (fr_cdr > t.size)
                    fr_cdr = t.size;
            }

            const orz = function(e) {
                bpend = 0;
                let buf = e.target.result;

                if (fr_cdr > cdr) {
                    cache_buf = new Uint8Array(buf);
                    cache_car = car;
                    cache_cdr = fr_cdr;
                    buf = cache_buf.subarray(0, cdr - car);
                }

                if (hashers < hash_par)
                    segm_next();

                hash_calc(nch, buf);
            };

            reader.onload = function(e) {
                try {
                    orz(e);
                } catch (ex) {
                    vis_exh(ex + "", "up2k.js", "", "", ex);
                }
            };

            reader.onerror = function() {
                const err = reader.error + "";
                let handled = false;

                if (err.indexOf("NotReadableError") !== -1 || err.indexOf("NotFoundError") !== -1) {
                    pvis.seth(t.n, 1, "OS-error");
                    pvis.seth(t.n, 2, err + " @ " + car);
                    console.log("OS-error", reader.error, "@", car);
                    handled = true;
                    got_oserr();
                }

                if (handled) {
                    pvis.move(t.n, "ng");
                    apop(st.busy.hash, t);
                    st.bytes.finished += t.size;
                    return;
                }

                toast.err(
                    0,
                    "y o u   b r o k e    i t\nfile: " + esc(t.name + "") + "\nerror: " + err
                );
            };

            bpend = 1;
            tread = Date.now();
            reader.readAsArrayBuffer(t.fobj.slice(car, fr_cdr));
            return true;
        };

        var hash_calc = function(nch, buf) {
            hashers++;

            const orz = function(hashbuf) {
                const hslice = new Uint8Array(hashbuf).subarray(0, 33);
                const b64str = buf2b64(hslice);
                hashers--;
                hashtab[nch] = b64str;
                t.hash.push(nch);
                pvis.hashed(t);

                if (t.hash.length < nchunks)
                    return segm_next();

                t.hash = [];

                for (let a = 0; a < nchunks; a++)
                    t.hash.push(hashtab[a]);

                t.t_hashed = Date.now();
                pvis.seth(t.n, 2, L.u_hashdone);
                pvis.seth(t.n, 1, "📦 wait");
                apop(st.busy.hash, t);
                st.todo.handshake.push(t);
                tasker();
            };

            const hash_done = function(hashbuf) {
                try {
                    orz(hashbuf);
                } catch (ex) {
                    vis_exh(ex + "", "up2k.js", "", "", ex);
                }
            };

            if (subtle)
                subtle.digest("SHA-512", buf).then(hash_done);
            else setTimeout(function() {
                const u8buf = new Uint8Array(buf);

                if (sha_js == "hw") {
                    hashwasm.sha512(u8buf).then(function(v) {
                        hash_done(hex2u8(v));
                    });
                } else {
                    const hasher = new asmCrypto.Sha512();
                    hasher.process(u8buf);
                    hasher.finish();
                    hash_done(hasher.result);
                }
            }, 1);
        };

        segm_next();
    }

    function wexec_hash(t, chunksize, nchunks) {
        let nchunk = 0;
        let reading = 0;
        let max_readers = 1;
        let opt_readers = 2;
        const free = [];
        const busy = {};
        let nbusy = 0;
        let init = 0;
        const hashtab = {};
        let mem = (MOBILE ? 128 : 256) * 1024 * 1024;

        if (!hws_ok) init = setTimeout(function() {
            hws_ng = true;

            toast.warn(
                30,
                "webworkers failed to start\n\nwill be a bit slower due to\nhashing on main-thread"
            );

            apop(st.busy.hash, t);
            st.todo.hash.unshift(t);
            exec_hash();
        }, 5000);

        for (let a = 0; a < hws.length; a++) {
            const w = hws[a];
            w.onmessage = onmsg;

            if (init)
                w.postMessage("ping");

            if (mem > 0)
                free.push(w);

            mem -= chunksize;
        }

        function go_next() {
            if (st.slow_io && uc.multitask)
                max_readers = opt_readers = free.length;

            if (reading >= max_readers || !free.length || nchunk >= nchunks)
                return;

            const w = free.pop();
            const car = nchunk * chunksize;
            const cdr = Math.min(chunksize + car, t.size);
            w.postMessage([nchunk, t.fobj, car, cdr]);
            busy[nchunk] = w;
            nbusy++;
            reading++;
            nchunk++;

            if (Date.now() - up2k.tact > 1500)
                tasker();
        }

        function onmsg(d) {
            d = d.data;
            const k = d[0];

            if (k == "pong") if (++hws_ok == hws.length) {
                clearTimeout(init);
                go_next();
            }

            if (k == "panic")
                return vis_exh(d[1], "up2k.js", "", "", d[1]);

            if (k == "fail") {
                pvis.seth(t.n, 1, d[1]);
                pvis.seth(t.n, 2, d[2]);
                console.log(d[1], d[2]);

                if (d[1] == "OS-error")
                    got_oserr();

                pvis.move(t.n, "ng");
                apop(st.busy.hash, t);
                st.bytes.finished += t.size;
                return;
            }

            if (k == "ferr") return toast.err(
                0,
                "y o u   b r o k e    i t\nfile: " + esc(t.name + "") + "\nerror: " + d[1]
            );

            if (k == "read") {
                reading--;

                if (MOBILE && CHROME && st.slow_io === null && d[1] == 1 && d[2] > 1024 * 512) {
                    const spd = Math.floor(d[2] / d[3]);
                    st.slow_io = spd < 40 * 1024;
                    console.log("spd {0}, slow: {1}".format(spd, st.slow_io));
                }

                return go_next();
            }

            if (k == "done") {
                const nchunk = d[1];
                const hslice = d[2];
                const sz = d[3];
                free.push(busy[nchunk]);
                delete busy[nchunk];
                nbusy--;
                hashtab[nchunk] = buf2b64(hslice);
                st.bytes.hashed += sz;
                t.hash.push(nchunk);
                pvis.hashed(t);

                if (t.hash.length < nchunks)
                    return nbusy < opt_readers && go_next();

                t.hash = [];

                for (let a = 0; a < nchunks; a++)
                    t.hash.push(hashtab[a]);

                t.t_hashed = Date.now();
                pvis.seth(t.n, 2, L.u_hashdone);
                pvis.seth(t.n, 1, "📦 wait");
                apop(st.busy.hash, t);
                st.todo.handshake.push(t);
                tasker();
            }
        }

        if (!init)
            go_next();
    }

    function exec_head() {
        const t = st.todo.head.shift();

        if (t.done)
            return console.log("done; skip head1", t.name, t);

        st.busy.head.push(t);
        const xhr = new XMLHttpRequest();

        xhr.onerror = xhr.ontimeout = function() {
            console.log("head onerror, retrying", t.name, t);

            if (!toast.visible)
                toast.warn(9.98, L.u_enethd + "\n\nfile: " + t.name, t);

            apop(st.busy.head, t);
            st.todo.head.unshift(t);
        };

        function orz(e) {
            if (t.done)
                return console.log("done; skip head2", t.name, t);

            let ok = false;

            if (xhr.status == 200) {
                const srv_sz = xhr.getResponseHeader("Content-Length");
                let srv_ts = xhr.getResponseHeader("Last-Modified");
                ok = t.size == srv_sz;

                if (ok && uc.datechk) {
                    srv_ts = new Date(srv_ts) / 1000;
                    ok = Math.abs(srv_ts - t.lmod) < 2;
                }
            }

            apop(st.busy.head, t);

            if (!ok && !t.srch) {
                push_t(st.todo.hash, t);
                tasker();
                return;
            }

            t.done = true;
            t.fobj = null;
            st.bytes.hashed += t.size;
            st.bytes.finished += t.size;
            pvis.move(t.n, "bz");
            pvis.seth(t.n, 1, ok ? "YOLO" : "404");
            pvis.seth(t.n, 2, "turbo'd");
            pvis.move(t.n, ok ? "ok" : "ng");
            tasker();
        }

        xhr.onload = function(e) {
            try {
                orz(e);
            } catch (ex) {
                vis_exh(ex + "", "up2k.js", "", "", ex);
            }
        };

        xhr.timeout = 34000;
        xhr.open("HEAD", t.purl + uricom_enc(t.name), true);
        xhr.send();
    }

    function exec_handshake() {
        const t = st.todo.handshake.shift();
        const keepalive = t.keepalive;
        const me = Date.now();

        if (t.done)
            return console.log("done; skip hs", t.name, t);

        st.busy.handshake.push(t);
        t.keepalive = undefined;
        t.t_busied = me;

        if (keepalive)
            console.log("sending keepalive handshake", t.name, t);

        if (!t.srch && !t.t_handshake)
            pvis.seth(t.n, 2, L.u_hs);

        const xhr = new XMLHttpRequest();

        xhr.onerror = xhr.ontimeout = function() {
            if (t.t_busied != me)
                return console.log("zombie handshake onerror", t.name, t);

            if (!toast.visible)
                toast.warn(9.98, L.u_eneths + "\n\nfile: " + t.name, t);

            console.log("handshake onerror, retrying", t.name, t);
            apop(st.busy.handshake, t);
            st.todo.handshake.unshift(chill(t));
            t.keepalive = keepalive;
        };

        const orz = function(e) {
            if (t.t_busied != me || t.done)
                return console.log("zombie handshake onload", t.name, t);

            if (xhr.status == 200) {
                try {
                    var response = JSON.parse(xhr.responseText);
                } catch (ex) {
                    apop(st.busy.handshake, t);
                    st.todo.handshake.unshift(chill(t));
                    const txt = t.t_uploading ? L.u_ehsfin : t.srch ? L.u_ehssrch : L.u_ehsinit;
                    return toast.err(0, txt + "\n\n" + L.badreply + ":\n\n" + unpre(xhr.responseText));
                }

                t.t_handshake = Date.now();

                if (keepalive) {
                    apop(st.busy.handshake, t);
                    tasker();
                    return;
                }

                if (toast.tag === t)
                    toast.ok(5, L.u_fixed);

                if (!response.name) {
                    var msg = "";
                    let smsg = "";

                    if (!response || !response.hits || !response.hits.length) {
                        smsg = "404";
                        msg = L.u_s404 + " <a href=\"#\" onclick=\"fsearch_explain(" + (has(perms, "write") ? "0" : "1") + ")\" class=\"fsearch_explain\">(" + L.u_expl + ")</a>";
                    } else {
                        smsg = "found";
                        var msg = [];

                        for (var a = 0, aa = Math.min(20, response.hits.length); a < aa; a++) {
                            const hit = response.hits[a];
                            const tr = unix2iso(hit.ts);
                            const tu = unix2iso(t.lmod);
                            const diff = parseInt(t.lmod) - parseInt(hit.ts);
                            const cdiff = Math.abs(diff) <= 2 ? "3c0" : "f0b";
                            const sdiff = "<span style=\"color:#" + cdiff + "\">diff " + diff;

                            msg.push(
                                linksplit(hit.rp).join(" / ") + "<br /><small>" + tr + " (srv), " + tu + " (You), " + sdiff + "</small></span>"
                            );
                        }

                        msg = msg.join("<br />\n");
                    }

                    pvis.seth(t.n, 2, msg);
                    pvis.seth(t.n, 1, smsg);
                    pvis.move(t.n, smsg == "404" ? "ng" : "ok");
                    apop(st.busy.handshake, t);
                    st.bytes.finished += t.size;
                    t.done = true;
                    t.fobj = null;
                    tasker();
                    return;
                }

                t.sprs = response.sprs;
                const fk = response.fk;
                const rsp_purl = url_enc(response.purl);
                const rename = rsp_purl !== t.purl || response.name !== t.name;

                if (rename || fk) {
                    if (rename) console.log(
                        "server-rename [" + t.purl + "] [" + t.name + "] to [" + rsp_purl + "] [" + response.name + "]"
                    );

                    t.purl = rsp_purl;
                    t.name = response.name;
                    let url = t.purl + uricom_enc(t.name);

                    if (fk) {
                        t.fk = fk;
                        url += "?k=" + fk;
                    }

                    pvis.seth(t.n, 0, linksplit(url).join(" / "));
                }

                const chunksize = get_chunksize(t.size);
                const cdr_idx = Math.ceil(t.size / chunksize) - 1;
                const cdr_sz = t.size % chunksize || chunksize;
                const cbd = [];

                for (var a = 0; a <= cdr_idx; a++) {
                    cbd.push(a == cdr_idx ? cdr_sz : chunksize);
                }

                t.postlist = [];
                t.wark = response.wark;
                const missing = response.hash;

                for (var a = 0; a < missing.length; a++) {
                    const idx = t.hash.indexOf(missing[a]);

                    if (idx < 0) return modal.alert(
                        "wtf negative index for hash \"{0}\" in task:\n{1}".format(missing[a], JSON.stringify(t))
                    );

                    t.postlist.push(idx);
                    cbd[idx] = 0;
                }

                pvis.setat(t.n, cbd);
                pvis.prog(t, 0, cbd[0]);
                let done = true;
                var msg = "done";

                if (t.postlist.length) {
                    if (t.rechecks && QS("#opa_del.act"))
                        toast.inf(30, L.u_started, L.u_unpt);

                    const arr = st.todo.upload;
                    const sort = arr.length && arr[arr.length - 1].nfile > t.n;

                    if (!t.stitch_sz) {
                        const bpc = (st.bytes.total - st.bytes.finished) / (parallel_uploads || 1);
                        let ocs = 1024 * 1024;
                        let stp = 1024 * 512;
                        let ccs = ocs;

                        while (ccs < bpc) {
                            ocs = ccs;
                            ccs += stp;

                            if (ccs < bpc)
                                ocs = ccs;

                            ccs += stp;
                            stp *= 2;
                        }

                        ocs = Math.floor(ocs / 1024 / 1024);
                        t.stitch_sz = Math.min(ocs, stitch_tgt);
                    }

                    for (var a = 0; a < t.postlist.length; a++) {
                        const nparts = [];
                        let tbytes = 0;
                        let stitch = t.stitch_sz;

                        if (t.nojoin && t.nojoin - t.postlist.length < 6)
                            stitch = 1;

                        --a;

                        for (let b = 0; b < stitch; b++) {
                            nparts.push(t.postlist[++a]);
                            tbytes += chunksize;

                            if (tbytes + chunksize > stitch * 1024 * 1024 || t.postlist[a + 1] - t.postlist[a] !== 1)
                                break;
                        }

                        arr.push({
                            nfile: t.n,
                            nparts: nparts
                        });
                    }

                    t.nojoin = 0;
                    msg = null;
                    done = false;

                    if (sort) arr.sort(function(a, b) {
                        return a.nfile < b.nfile ? -1 : a.nfile > b.nfile ? 1 : a.nparts[0] < b.nparts[0] ? -1 : 1;
                    });
                }

                if (msg)
                    pvis.seth(t.n, 1, msg);

                apop(st.busy.handshake, t);

                if (done) {
                    t.done = true;
                    t.fobj = null;
                    st.bytes.finished += t.size - t.bytes_uploaded;
                    const spd1 = t.size / ((t.t_hashed - t.t_hashing) / 1000) / (1024 * 1024);
                    const spd2 = t.size / ((t.t_uploaded - t.t_uploading) / 1000) / (1024 * 1024);

                    pvis.seth(
                        t.n,
                        2,
                        "hash {0}, up {1} MB/s".format(f2f(spd1, 2), !isNum(spd2) ? "--" : f2f(spd2, 2))
                    );

                    pvis.move(t.n, "ok");

                    if (!pvis.ctr.bz && !pvis.ctr.q)
                        uptoast();
                } else {
                    if (t.t_uploaded)
                        chill(t);

                    t.t_uploaded = undefined;
                }

                tasker();
            } else {
                pvis.seth(t.n, 1, "ERROR");
                pvis.seth(t.n, 2, L.u_ehstmp, t);
                apop(st.busy.handshake, t);
                let err = "";
                let cls = "ERROR";
                let rsp = unpre(xhr.responseText);
                let ofs = rsp.lastIndexOf("\nURL: ");

                if (ofs !== -1)
                    rsp = rsp.slice(0, ofs);

                if (rsp.indexOf("rate-limit ") !== -1) {
                    const penalty = rsp.replace(/.*rate-limit /, "").split(" ")[0];
                    console.log("rate-limit: " + penalty);
                    t.cooldown = Date.now() + parseFloat(penalty) * 1000;
                    st.todo.handshake.unshift(t);
                    return;
                }

                const err_pend = rsp.indexOf("partial upload exists at a different") + 1;
                const err_srcb = rsp.indexOf("source file busy; please try again") + 1;
                const err_plug = rsp.indexOf("upload blocked by x") + 1;
                const err_dupe = rsp.indexOf("upload rejected, file already exists") + 1;

                if (err_pend || err_srcb || err_plug || err_dupe) {
                    err = rsp;
                    ofs = err.indexOf("\n/");

                    if (ofs !== -1) {
                        err = err.slice(0, ofs + 1) + linksplit(err.slice(ofs + 2).trimEnd()).join(" / ");
                    }

                    if (!t.rechecks && (err_pend || err_srcb)) {
                        t.rechecks = 0;
                        t.want_recheck = true;

                        if (st.busy.upload.length || st.busy.handshake.length || st.bytes.uploaded) {
                            err = L.u_dupdefer;
                            cls = "defer";
                        }
                    }

                    if (err_pend) {
                        err += " <a href=\"#\" onclick=\"toast.inf(60, L.ue_ab);\" class=\"fsearch_explain\">(" + L.u_expl + ")</a>";
                    }
                }

                if (err != "") {
                    if (!t.t_uploading)
                        st.bytes.finished += t.size;

                    pvis.seth(t.n, 1, cls);
                    pvis.seth(t.n, 2, err);
                    pvis.move(t.n, "ng");
                    tasker();
                    return;
                }

                st.todo.handshake.unshift(chill(t));

                if (rsp.indexOf("server HDD is full") + 1)
                    return toast.err(0, L.u_ehsdf + "\n\n" + rsp.replace(/.*; /, ""));

                err = t.t_uploading ? L.u_ehsfin : t.srch ? L.u_ehssrch : L.u_ehsinit;

                xhrchk(
                    xhr,
                    err + "\n\nfile: " + t.name + "\n\nerror ",
                    "404, target folder not found",
                    "warn",
                    t
                );
            }
        };

        xhr.onload = function(e) {
            try {
                orz(e);
            } catch (ex) {
                vis_exh(ex + "", "up2k.js", "", "", ex);
            }
        };

        const req = {
            name: t.name,
            size: t.size,
            lmod: t.lmod,
            life: st.lifetime,
            hash: t.hash
        };

        if (t.srch)
            req.srch = 1;
        else if (t.rand)
            req.rand = true;
        else if (t.umod)
            req.umod = true;

        if (!t.srch) {
            if (uc.ow == 1)
                req.replace = "mt";

            if (uc.ow == 2)
                req.replace = true;
        }

        xhr.open("POST", t.purl, true);
        xhr.responseType = "text";
        xhr.timeout = 42000 + (t.srch || t.t_uploaded ? 0 : t.size / (1048 * 20));
        xhr.send(JSON.stringify(req));
    }

    function can_upload_next() {
        const upt = st.todo.upload[0];
        const upf = st.files[upt.nfile];
        const nhs = st.busy.handshake.length;
        var hs = nhs && st.busy.handshake[0];
        const now = Date.now();

        if (nhs >= 16)
            return false;

        if (hs && hs.t_uploaded && Date.now() - hs.t_busied > 10000)
            return false;

        for (var a = 0, aa = st.busy.handshake.length; a < aa; a++) {
            var hs = st.busy.handshake[a];

            if (hs.n < upt.nfile && hs.t_busied > now - 10 * 1000 && !st.files[hs.n].bytes_uploaded)
                return false;
        }

        if (upf.sprs)
            return true;

        for (var a = 0, aa = st.busy.upload.length; a < aa; a++) if (st.busy.upload[a].nfile == upt.nfile)
            return false;

        return true;
    }

    function exec_upload() {
        const upt = st.todo.upload.shift();
        const t = st.files[upt.nfile];
        const nparts = upt.nparts;
        const pcar = nparts[0];
        const pcdr = nparts[nparts.length - 1];
        const maxsz = (u2sz_max > 1 ? u2sz_max : 2040) * 1024 * 1024;

        if (t.done)
            return console.log("done; skip chunk", t.name, t);

        st.busy.upload.push(upt);
        st.nfile.upload = upt.nfile;

        if (!t.t_uploading)
            t.t_uploading = Date.now();

        pvis.seth(t.n, 1, "🚀 send");
        const chunksize = get_chunksize(t.size);
        let car = pcar * chunksize;
        let cdr = (pcdr + 1) * chunksize;

        if (cdr >= t.size)
            cdr = t.size;

        if (cdr - car <= maxsz)
            return upload_sub(t, upt, pcar, pcdr, car, cdr, chunksize, car, []);

        const car0 = car;
        const subs = [];

        while (car < cdr) {
            subs.push([car, Math.min(cdr, car + maxsz)]);
            car += maxsz;
        }

        upload_sub(t, upt, pcar, pcdr, 0, 0, chunksize, car0, subs);
    }

    function upload_sub(t, upt, pcar, pcdr, car, cdr, chunksize, car0, subs) {
        const nparts = upt.nparts;
        const is_sub = subs.length;

        if (is_sub) {
            const x = subs.shift();
            car = x[0];
            cdr = x[1];
        }

        const snpart = is_sub ? "" + pcar + "(" + (car - car0) + "+" + (cdr - car) : pcar == pcdr ? pcar : "" + pcar + "~" + pcdr;

        const orz = function(xhr) {
            st.bytes.inflight -= xhr.bsent;
            const txt = unpre((xhr.response && xhr.response.err) || xhr.responseText);

            if (txt.indexOf("upload blocked by x") + 1) {
                apop(st.busy.upload, upt);

                for (var a = pcar; a <= pcdr; a++)
                    apop(t.postlist, a);

                pvis.seth(t.n, 1, "ERROR");
                pvis.seth(t.n, 2, txt.split(/\n/)[0]);
                pvis.move(t.n, "ng");
                return;
            }

            if (xhr.status == 200) {
                car = car0;

                if (subs.length)
                    return upload_sub(t, upt, pcar, pcdr, 0, 0, chunksize, car0, subs);

                let bdone = cdr - car;

                for (var a = pcar; a <= pcdr; a++) {
                    pvis.prog(t, a, Math.min(bdone, chunksize));
                    bdone -= chunksize;
                }

                st.bytes.finished += cdr - car;
                st.bytes.uploaded += cdr - car;
                t.bytes_uploaded += cdr - car;
                t.cooldown = t.coolmul = 0;
                st.etac.u++;
                st.etac.t++;
            } else if (txt.indexOf("already got that") + 1 || txt.indexOf("already being written") + 1) {
                t.nojoin = t.nojoin || t.postlist.length;
                console.log("ignoring dupe-segment with backoff", t.nojoin, t.name, t);

                if (!toast.visible && st.todo.upload.length < 4)
                    toast.inf(10, L.u_cbusy);
            } else {
                xhrchk(
                    xhr,
                    L.u_cuerr2.format(snpart, Math.ceil(t.size / chunksize), t.name),
                    "404, target folder not found (???)",
                    "warn",
                    t
                );

                chill(t);
            }

            orz2(xhr);
        };

        var orz2 = function(xhr) {
            apop(st.busy.upload, upt);

            for (let a = pcar; a <= pcdr; a++)
                apop(t.postlist, a);

            if (!t.postlist.length) {
                t.t_uploaded = Date.now();
                pvis.seth(t.n, 1, "verifying");
                st.todo.handshake.unshift(t);
            }

            tasker();
        };

        function do_send() {
            const xhr = new XMLHttpRequest();
            const bfin = Math.floor(st.bytes.finished / 1024 / 1024);
            const btot = Math.floor(st.bytes.total / 1024 / 1024);

            xhr.upload.onprogress = function(xev) {
                const nb = xev.loaded;
                const db = nb - xhr.bsent;

                if (!db)
                    return;

                st.bytes.inflight += db;
                xhr.bsent = nb;
                xhr.timeout = 64000 + Date.now() - xhr.t0;
                pvis.prog(t, pcar, nb);
            };

            xhr.onload = function(xev) {
                try {
                    orz(xhr);
                } catch (ex) {
                    vis_exh(ex + "", "up2k.js", "", "", ex);
                }
            };

            xhr.onerror = xhr.ontimeout = function(xev) {
                if (crashed)
                    return;

                st.bytes.inflight -= xhr.bsent || 0;
                xhr.bsent = 0;

                if (!toast.visible)
                    toast.warn(9.98, L.u_cuerr.format(snpart, Math.ceil(t.size / chunksize), t.name), t);

                t.nojoin = t.nojoin || t.postlist.length;
                console.log("chunkpit onerror,", t.name, t);
                orz2(xhr);
            };

            const chashes = [];
            let ctxt = t.hash[pcar];
            let plen = Math.floor(192 / nparts.length);
            plen = plen > 9 ? 9 : plen < 2 ? 2 : plen;

            for (let a = pcar + 1; a <= pcdr; a++)
                chashes.push(t.hash[a].slice(0, plen));

            if (chashes.length)
                ctxt += "," + plen + "," + chashes.join("");

            xhr.open("POST", t.purl, true);
            xhr.setRequestHeader("X-Up2k-Hash", ctxt);
            xhr.setRequestHeader("X-Up2k-Wark", t.wark);

            if (is_sub)
                xhr.setRequestHeader("X-Up2k-Subc", car - car0);

            xhr.setRequestHeader("X-Up2k-Stat", "{0}/{1}/{2}/{3} {4}/{5} {6}".format(
                pvis.ctr.ok,
                pvis.ctr.ng,
                pvis.ctr.bz,
                pvis.ctr.q,
                btot,
                btot - bfin,
                st.eta.t.indexOf("/s, ") + 1 ? st.eta.t.split(" ").pop() : "x"
            ));

            xhr.setRequestHeader("Content-Type", "application/octet-stream");

            if (xhr.overrideMimeType)
                xhr.overrideMimeType("Content-Type", "application/octet-stream");

            xhr.bsent = 0;
            xhr.t0 = Date.now();
            xhr.timeout = 42000;
            xhr.responseType = "text";
            xhr.send(t.fobj.slice(car, cdr));
        }

        do_send();
    }

