function up2k_flagbus() {
    const flag = {
        id: Math.floor(Math.random() * 1024 * 1024 * 1023 * 2),
        ch: new BroadcastChannel("up2k_flagbus"),
        ours: false,
        owner: null,
        wants: null,
        act: false,
        last_tx: ["x", null]
    };

    const dbg = function(who, msg) {
        console.log("flagbus(" + flag.id + "): [" + who + "] " + msg);
    };

    flag.ch.onmessage = function(e) {
        const who = e.data[0];
        const what = e.data[1];

        if (who == flag.id) {
            dbg(who, "hi me (??)");
            return;
        }

        flag.act = Date.now();

        if (what == "want") {
            if (who < flag.id) {
                dbg(who, "wants (ack)");
                flag.wants = [who, flag.act];
            } else {
                dbg(who, "wants (ign)");
            }
        } else if (what == "have") {
            dbg(who, "have");
            flag.owner = [who, flag.act];
        } else if (what == "give") {
            if (flag.owner && flag.owner[0] == who) {
                flag.owner = null;
                dbg(who, "give (ok)");
            } else {
                dbg(who, "give, INVALID, " + flag.owner);
            }
        } else if (what == "hi") {
            dbg(who, "hi");
            flag.ch.postMessage([flag.id, "hey"]);
        } else {
            dbg("?", e.data);
        }
    };

    const tx = function(now, msg) {
        const td = now - flag.last_tx[1];

        if (td > 500 || flag.last_tx[0] != msg) {
            dbg("*", "tx " + msg);
            flag.ch.postMessage([flag.id, msg]);
            flag.last_tx = [msg, now];
        }
    };

    const do_take = function(now) {
        tx(now, "have");
        flag.owner = [flag.id, now];
        flag.ours = true;
    };

    const do_want = function(now) {
        tx(now, "want");
    };

    flag.take = function(now) {
        if (flag.ours) {
            do_take(now);
            return;
        }

        if (flag.owner && now - flag.owner[1] > 12000) {
            flag.owner = null;
        }

        if (flag.wants && now - flag.wants[1] > 12000) {
            flag.wants = null;
        }

        if (!flag.owner && !flag.wants) {
            do_take(now);
            return;
        }

        do_want(now);
    };

    flag.give = function() {
        dbg("#", "put give");
        flag.ch.postMessage([flag.id, "give"]);
        flag.owner = null;
        flag.ours = false;
    };

    flag.ch.postMessage([flag.id, "hi"]);
