}

function U2pvis(act, btns, uc, st) {
    const r = this;
    r.act = act;

    r.ctr = {
        ok: 0,
        ng: 0,
        bz: 0,
        q: 0
    };

    r.tab = [];
    r.hq = {};
    r.head = 0;
    r.tail = -1;
    r.wsz = 3;
    r.npotato = 99;
    r.modn = 0;
    r.modv = 0;
    r.mod0 = null;

    const markup = {
        404: "<span class=\"err\">" + L.utl_404 + "</span>",
        ERROR: "<span class=\"err\">" + L.utl_err + "</span>",
        "OS-error": "<span class=\"err\">" + L.utl_oserr + "</span>",
        found: "<span class=\"inf\">" + L.utl_found + "</span>",
        defer: "<span class=\"inf\">" + L.utl_defer + "</span>",
        YOLO: "<span class=\"inf\">" + L.utl_yolo + "</span>",
        done: "<span class=\"ok\">" + L.utl_done + "</span>"
    };

    r.addfile = function(entry, sz, draw) {
        r.tab.push({
            hn: entry[0],
            ht: entry[1],
            hp: entry[2],
            in: "q",
            nh: 0,
            nd: 0,
            cb: [],
            bt: sz,
            bd: 0,
            bd0: 0
        });

        r.ctr["q"]++;

        if (!draw)
            return;

        r.drawcard("q");

        if (r.act == "q") {
            r.addrow(r.tab.length - 1);
        }

        if (r.act == "bz") {
            r.bzw();
        }
    };

    r.is_act = function(card) {
        if (uc.potato && !uc.fsearch)
            return false;

        if (r.act == "done")
            return card == "ok" || card == "ng";

        return r.act == card;
    };

    r.seth = function(nfile, field, html) {
        const fo = r.tab[nfile];
        field = ["hn", "ht", "hp"][field];

        if (fo[field] === html)
            return;

        fo[field] = html;

        if (!r.is_act(fo.in))
            return;

        const k = "f" + nfile + "" + field.slice(1);
        const obj = ebi(k);
        obj.innerHTML = field == "ht" ? markup[html] || html : html;

        if (field == "hp") {
            obj.style.color = "";
            obj.style.background = "";
            delete r.hq[nfile];
        }
    };

    r.setab = function(nfile, nblocks) {
        const t = [];

        for (let a = 0; a < nblocks; a++)
            t.push(0);

        r.tab[nfile].cb = t;
    };

    r.setat = function(nfile, blocktab) {
        const fo = r.tab[nfile];
        let bd = 0;

        for (let a = 0; a < blocktab.length; a++)
            bd += blocktab[a];

        fo.bd = bd;
        fo.bd0 = bd;
        fo.cb = blocktab;
    };

    r.perc = function(bd, bd0, sz, t0) {
        const td = Date.now() - t0;
        const p = (bd * 100.0) / sz;
        const nb = bd - bd0;
        const spd = nb / (td / 1000);
        const eta = spd ? (sz - bd) / spd : 3599;
        return [p, s2ms(eta), spd / (1024 * 1024)];
    };

    r.hashed = function(fobj) {
        const fo = r.tab[fobj.n];
