        fo.hp = f2f(p[0], 2) + "%, " + p[1] + ", " + f2f(p[2], 2) + " MB/s";

        if (!r.is_act(fo.in))
            return;

        const o1 = p[0] - 2;
        const o2 = p[0] - 0.1;
        const o3 = p[0];

        r.hq[fobj.n] = [
            fo.hp,
            "#fff",
            "linear-gradient(90deg, #025, #06a " + o1 + "%, #09d " + o2 + "%, #222 " + o3 + "%, #222 99%, #555)"
        ];
    };

    r.prog = function(fobj, nchunk, cbd) {
