        if (!fo.bd)
            return;

        const p = r.perc(fo.bd, fo.bd0, fo.bt, fobj.t_uploading);
        fo.hp = f2f(p[0], 2) + "%, " + p[1] + ", " + f2f(p[2], 2) + " MB/s";

        if (!r.is_act(fo.in))
