                console.log(
                    "dom %d/%d = [%s] in(%s) is_act(%s) %s",
                    a,
                    aa,
                    id,
                    r.tab[id].in,
                    r.is_act(fo.in),
                    ds[a].textContent
                );
            }

            for (var a = 0, aa = r.tab.length; a < aa; a++) if (r.is_act(r.tab[a].in))
                console.log("tab %d/%d = sz %s", a, aa, r.tab[a].bt);

            throw new Error("see console");
        }

        r.hq[fobj.n] = [
            fo.hp,
            "#fff",
            "linear-gradient(90deg, #050, #270 " + o1 + "%, #4b0 " + o2 + "%, #222 " + o3 + "%, #222 99%, #555)"
        ];
    };

    r.move = function(nfile, newcat) {
        const fo = r.tab[nfile];
        const oldcat = fo.in;
        const bz_act = r.act == "bz";

        if (oldcat == newcat)
            return;

        fo.in = newcat;
        r.ctr[oldcat]--;
        r.ctr[newcat]++;

        while (st.car < r.tab.length && has(["ok", "ng"], r.tab[st.car].in))
            st.car++;

        r.drawcard(oldcat);
        r.drawcard(newcat);

        if (r.is_act(newcat)) {
            r.tail = Math.max(r.tail, nfile + 1);

            if (!ebi("f" + nfile))
                r.addrow(nfile);
        } else if (r.is_act(oldcat)) {
            while (r.head < Math.min(r.tab.length, r.tail) && r.precard[r.tab[r.head].in])
                r.head++;

            if (!bz_act) {
                qsr("#f" + nfile);
            }
        } else
            return;

        if (bz_act)
            r.bzw();
    };

    r.bzw = function() {
        let mod = 0;
        const t0 = Date.now();
        let first = QS("#u2tab>tbody>tr:first-child");

        if (!first)
            return;

        let last = QS("#u2tab>tbody>tr:last-child");
        first = parseInt(first.getAttribute("id").slice(1));
        last = parseInt(last.getAttribute("id").slice(1));

        while (r.head - first > r.wsz) {
            qsr("#f" + first++);
            mod++;
        }

        while (last - r.tail < r.wsz && last < r.tab.length - 1) {
            const obj = ebi("f" + ++last);

            if (!obj) {
                r.addrow(last);
                mod++;
            }
        }

        if (mod && r.modn < 200 && ebi("repl").offsetTop) {
            if (++r.modn >= 10) {
                if (r.modn == 10)
                    r.mod0 = Date.now();

                r.modv += Date.now() - t0;
            }

            if (r.modn >= 200) {
                const n = r.modn - 10;
                const ipu = r.modv / n;
                const spu = (Date.now() - r.mod0) / n;
                const ir = spu / ipu;

                console.log(
                    "bzw:",
                    f2f(ipu, 2),
                    " spu:",
                    f2f(spu, 2),
                    " ir:",
                    f2f(ir, 2),
                    " tab:",
                    r.tab.length
                );

                if (ipu >= 1.5 && ir <= 9 && r.tab.length >= 1000 && r.tab[Math.floor(r.tab.length / 3)].bt <= 1024 * 1024 * 4)
                    r.go_potato();
            }
