    function apply_html() {
        const oq = {};
        let n = 0;

        for (var k in r.hq) {
            var o = ebi("f" + k + "p");

            if (!o)
                continue;

            oq[k] = o;
            n++;
        }

        if (!n)
            return;

        for (var k in oq) {
            var o = oq[k];
            const v = r.hq[k];
