        r.hq = {};
    }

    r.drawcard = function(cat) {
        const cards = QSA("#u2cards>a>span");

        if (cat == "q") {
            cards[4].innerHTML = r.ctr[cat];
            return;
        }

        if (cat == "bz") {
            cards[3].innerHTML = r.ctr[cat];
            return;
        }

        cards[2].innerHTML = r.ctr["ok"] + r.ctr["ng"];

        if (cat == "ng") {
            cards[1].innerHTML = r.ctr[cat];
        }

        if (cat == "ok") {
            cards[0].innerHTML = r.ctr[cat];
        }
    };

    r.changecard = function(card) {
        r.act = card;

        r.precard = has(["ok", "ng", "done"], r.act) ? {} : r.act == "bz" ? {
            ok: 1,
            ng: 1
        } : {
            ok: 1,
            ng: 1,
            bz: 1
        };

        r.postcard = has(["ok", "ng", "done"], r.act) ? {
            bz: 1,
            q: 1
        } : r.act == "bz" ? {
            q: 1
        } : {};

        r.head = -1;
        r.tail = -1;
        const html = [];

        for (var a = 0; a < r.tab.length; a++) {
            var rt = r.tab[a].in;

            if (r.is_act(rt)) {
                html.push(r.genrow(a, true));
                r.tail = a;

                if (r.head == -1)
                    r.head = a;
            }
        }

        if (r.head == -1) {
            for (var a = 0; a < r.tab.length; a++) {
                var rt = r.tab[a].in;

                if (r.precard[rt]) {
                    r.head = a + 1;
                    r.tail = a;
                } else if (r.postcard[rt]) {
                    r.head = a;
                    r.tail = a - 1;
                    break;
                }
            }
        }

        if (r.head < 0)
            r.head = 0;

        if (card == "bz") {
            for (var a = r.head - 1; a >= r.head - r.wsz && a >= 0; a--) {
                html.unshift(r.genrow(a, true).replace(/><td>/, "><td>a "));
            }

            for (var a = r.tail + 1; a <= r.tail + r.wsz && a < r.tab.length; a++) {
                html.push(r.genrow(a, true).replace(/><td>/, "><td>b "));
            }
        }

        const el = ebi("u2tab");
        el.tBodies[0].innerHTML = html.join("\n");
        el.className = (uc.fsearch ? "srch " : "up ") + r.act;
    };

    r.genrow = function(nfile, as_html) {
        const row = r.tab[nfile];
        const td1 = "<td id=\"f" + nfile;
        const td = "</td>" + td1;
        const ret = td1 + "n\">" + row.hn + td + "t\">" + (markup[row.ht] || row.ht) + td + "p\" class=\"prog\">" + row.hp + "</td>";

        if (as_html)
            return "<tr id=\"f" + nfile + "\">" + ret + "</tr>";

        const obj = mknod("tr", "f" + nfile);
        obj.innerHTML = ret;
        return obj;
    };

    r.addrow = function(nfile) {
        const tr = r.genrow(nfile);
        ebi("u2tab").tBodies[0].appendChild(tr);
    };

    btns = QSA(btns + ">a[act]");

    for (let a = 0; a < btns.length; a++) {
        btns[a].onclick = function(e) {
            ev(e);
            const newtab = this.getAttribute("act");

            const go = function() {
                for (let b = 0; b < btns.length; b++) {
                    btns[b].className = btns[b].getAttribute("act") == newtab ? "act" : "";
                }

                r.changecard(newtab);
            };

            let nf = r.ctr[newtab];

            if (nf === undefined)
                nf = r.ctr["ok"] + r.ctr["ng"];

            if (nf < 9000)
                return go();

            modal.confirm(L.u_bigtab.format(nf), go, null);
        };
    }

    r.changecard(r.act);
    r.potato();
}

function Donut(uc, st) {
    const r = this;
    let el = null;
    let psvg = null;
    let tenstrobe = null;
    let tstrober = null;
    let strobes = [];
    const o = 20 * 2 * Math.PI;
    const optab = QS("#ops a[data-dest=\"up2k\"]");
    optab.setAttribute("ico", optab.textContent);

    function svg(v) {
        const ico = v !== undefined;
        const bg = ico ? "#333" : "transparent";
        let fg = "#fff";
        let fsz = 52;
        let rc = 32;

        if (r.eta && (r.eta > 99 || (uc.fsearch ? st.time.hashing : st.time.uploading) < 20))
            r.eta = null;

        if (r.eta) {
            if (r.eta < 10) {
                fg = "#fa0";
                fsz = 72;
            }

            rc = 8;
        }

        return ("<svg version=\"1.1\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\">\n" + (ico ? "<rect width=\"100%\" height=\"100%\" rx=\"" + rc + "\" fill=\"#333\" />\n" : "<circle stroke=\"white\" stroke-width=\"6\" r=\"3\" cx=\"32\" cy=\"32\" />\n") + (r.eta ? "<text x=\"55%\" y=\"58%\" dominant-baseline=\"middle\" text-anchor=\"middle\"" + " font-family=\"sans-serif\" font-weight=\"bold\" font-size=\"" + fsz + "px\"" + " fill=\"" + fg + "\">" + r.eta + "</text></svg>" : "<circle class=\"donut\" stroke=\"white\" fill=\"" + bg + "\" stroke-dashoffset=\"" + (ico ? v : o) + "\" stroke-dasharray=\"" + o + " " + o + "\" transform=\"rotate(270 32 32)\" stroke-width=\"12\" r=\"20\" cx=\"32\" cy=\"32\" /></svg>"));
    }

    function pos() {
        return uc.fsearch ? Math.max(st.bytes.hashed, st.bytes.finished) : st.bytes.inflight + st.bytes.finished;
    }

    r.on = function(ya) {
        r.fc = r.tc = r.dc = 99;
        r.eta = null;
        r.base = pos();
        optab.innerHTML = ya ? svg() : optab.getAttribute("ico");
        el = QS("#ops a .donut");
        clearTimeout(tenstrobe);

        if (!ya) {
            favico.upd();
            wintitle();

            if (document.visibilityState == "hidden")
                tenstrobe = setTimeout(r.enstrobe, 500);
        }
    };

    r.do = function() {
        if (!el)
            return;

        const t = st.bytes.total - r.base;
        const v = pos() - r.base;
        const ofs = o - (o * v) / t;

        if (!uc.potato || ++r.dc >= 4) {
            el.style.strokeDashoffset = ofs;
            r.dc = 0;
        }

        if (++r.tc >= 10) {
            var s = r.eta === null ? "paused" : r.eta > 60 ? shumantime(r.eta) : r.eta + "s";

            wintitle(
                "{0}%, {1}, #{2}, ".format(f2f((v * 100) / t, 1), s, st.files.length - st.nfile.upload),
                true
            );

            r.tc = 0;
        }

        if (favico.txt) {
            if (++r.fc < 10 && r.eta && r.eta > 99)
                return;

            var s = svg(ofs);

            if (s == psvg || (r.eta === null && r.fc < 10))
                return;

            favico.upd("", s);
            psvg = s;
            r.fc = 0;
        }
    };

    r.enstrobe = function() {
        strobes = ["████████████████", "________________", "████████████████"];
        tstrober = setInterval(strobe, 300);

        if (uc.upsfx && actx && actx.state != "suspended")
            sfx();

        if (uc.upnag && Notification && Notification.permission == "granted")
            new Notification(uc.nagtxt);
    };

    function strobe() {
        const txt = strobes.pop();
        wintitle(txt, false);

        if (!txt)
            clearInterval(tstrober);
    }

    function sfx() {
        const osc = actx.createOscillator();
        const gain = actx.createGain();
        const gg = gain.gain;
        const ft = [660, 880, 440, 660, 880];
        let ofs = 0;
        osc.connect(gain);
        gain.connect(actx.destination);
        const ct = actx.currentTime + 0.03;
        osc.type = "triangle";

        while (ft.length)
            osc.frequency.setTargetAtTime(ft.shift(), ct + (ofs += 0.05), 0.001);

        gg.value = 0.15;
        gg.setTargetAtTime(0.8, ct, 0.01);
        gg.setTargetAtTime(0.3, ct + 0.13, 0.01);
        gg.setTargetAtTime(0, ct + ofs + 0.05, 0.02);
        osc.start();

        setTimeout(function() {
            osc.stop();
            osc.disconnect();
            gain.disconnect();
        }, 500);
    }
}

