    function up_them(good_files) {
        start_actx();
        draw_turbo();
        const evpath = get_evpath();
        const draw_each = good_files.length < 50;

        if (WebAssembly && !hws.length) {
            let nw = Math.min(navigator.hardwareConcurrency || 4, 16);

            if (CHROME) {
                nw = Math.max(1, nw > 4 ? 4 : nw - 1);
                nw = subtle && !MOBILE && nw > 2 ? 2 : nw;
            }

            for (var a = 0; a < nw; a++)
                hws.push(new Worker(SR + "/.cpr/w.hash.js?_=" + TS));

            if (!subtle) for (var a = 0; a < hws.length; a++)
                hws[a].postMessage("nosubtle");

            console.log(hws.length + " hashers");
        }

        if (!uc.az) good_files.sort(function(a, b) {
            a = a[0].size;
            b = b[0].size;
            return a < b ? -1 : a > b ? 1 : 0;
        });

        for (var a = 0; a < good_files.length; a++) {
            const fobj = good_files[a][0];
            let name = good_files[a][1];
            let fdir = evpath;
            const now = Date.now();
            const lmod = uc.u2ts ? fobj.lastModified || now : 0;
            const ofs = name.lastIndexOf("/") + 1;

            if (ofs) {
                fdir += url_enc(name.slice(0, ofs));
                name = name.slice(ofs);
            }

            const entry = {
                n: st.files.length,
                t0: now,
                fobj: fobj,
                name: name,
                size: fobj.size || 0,
                lmod: lmod / 1000,
                purl: fdir,
                done: false,
                bytes_uploaded: 0,
                hash: []
            };

            const key = name + "\n" + entry.size + "\n" + lmod + "\n" + uc.fsearch;

            if (uc.fsearch)
                entry.srch = 1;
            else if (uc.rand) {
                entry.rand = true;
                entry.name = "a\n" + entry.name;
            } else if (uc.umod)
                entry.umod = true;

            if (biggest_file < entry.size)
                biggest_file = entry.size;

            try {
                if (st.seen[fdir][key])
                    continue;
            } catch (ex) {
                st.seen[fdir] = {};
            }

            st.seen[fdir][key] = 1;

            pvis.addfile([
                uc.fsearch ? esc(entry.name) : linksplit(entry.purl + uricom_enc(entry.name)).join(" / "),
                "📐 " + L.u_hashing,
                ""
            ], entry.size, draw_each);

            st.bytes.total += entry.size;
            st.files.push(entry);

            if (uc.turbo)
                push_t(st.todo.head, entry);
            else
                push_t(st.todo.hash, entry);
        }

        if (!draw_each) {
            pvis.drawcard("q");
            pvis.changecard(pvis.act);
        }

        ebi("u2tabw").className = "ye";

        setTimeout(function() {
            if (!actx || actx.state != "suspended" || toast.visible)
                return;

            toast.warn(
                30,
                "<div onclick=\"start_actx();toast.inf(3,'thanks!')\">" + L.u_actx + "</div>"
            );
        }, 500);
    }

