    let etaref = 0;
    let etaskip = 0;
    let utw_minh = 0;
    let utw_read = 0;
    let utw_card = 0;

    function etafun() {
        let nhash = st.busy.head.length + st.busy.hash.length + st.todo.head.length + st.todo.hash.length;
        const nsend = st.busy.upload.length + st.todo.upload.length;
        const now = Date.now();
        let td = (now - (etaref || now)) / 1000.0;
        etaref = now;

        if (td > 1.2)
            td = 0.05;

        if (utw_card != pvis.act) {
            utw_card = pvis.act;
            utw_read = 9001;
            ebi("u2tabw").style.minHeight = "0px";
        }

        if (++utw_read >= 20) {
            utw_read = 0;
            utw_minh = parseInt(ebi("u2tabw").style.minHeight || "0");
        }

        const minh = QS("#op_up2k.act") && st.is_busy ? Math.max(utw_minh, ebi("u2tab").offsetHeight + 32) : 0;

        if (utw_minh < minh || !utw_minh) {
            utw_minh = minh;
            ebi("u2tabw").style.minHeight = utw_minh + "px";
        }

        if (!nhash) {
            var h = L.u_etadone.format(humansize(st.bytes.hashed), pvis.ctr.ok + pvis.ctr.ng);

            if (st.eta.h !== h) {
                st.eta.h = ebi("u2etah").innerHTML = h;

                console.log(
                    "{0} hash, {1} up, {2} busy".format(f2f(st.time.hashing, 1), f2f(st.time.uploading, 1), f2f(st.time.busy, 1))
                );
            }
        }

        if (!nsend && !nhash) {
            var h = L.u_etadone.format(humansize(st.bytes.uploaded), pvis.ctr.ok + pvis.ctr.ng);

            if (st.eta.u !== h)
                st.eta.u = ebi("u2etau").innerHTML = h;

            if (st.eta.t !== h)
                st.eta.t = ebi("u2etat").innerHTML = h;
        }

        if (!st.busy.hash.length && !hashing_permitted())
            nhash = 0;

        if (!parallel_uploads || !(nhash + nsend) || (flag && flag.owner && !flag.ours))
            return;

        const t = [];

        if (nhash) {
            st.time.hashing += td;
            t.push(["u2etah", st.bytes.hashed, st.bytes.hashed, st.time.hashing]);

            if (uc.fsearch) {
                st.time.busy += td;
                t.push(["u2etat", st.bytes.hashed, st.bytes.hashed, st.time.hashing]);
            }
        }

        const b_up = st.bytes.inflight + st.bytes.uploaded;
        const b_fin = st.bytes.inflight + st.bytes.finished;

        if (nsend) {
            st.time.uploading += td;
            t.push(["u2etau", b_up, b_fin, st.time.uploading]);
        }

        if ((nhash || nsend) && !uc.fsearch) {
            if (!b_fin) {
                ebi("u2etat").innerHTML = L.u_etaprep;
            } else {
                st.time.busy += td;
                t.push(["u2etat", b_fin, b_fin, st.time.busy]);
            }
        }

        for (let a = 0; a < t.length; a++) {
            const hid = t[a][0];
            const eid = hid.slice(-1);
            const etaw = st.etaw[eid];

            if (st.etac[eid] > 100) {
                st.etac[eid] = 0;
                etaw.push(jcp(t[a]));

                if (etaw.length > 5)
                    etaw.shift();
            }

            var h = etaw[0];
            const rem = st.bytes.total - t[a][2];
            const bps = (t[a][1] - h[1]) / Math.max(0.1, t[a][3] - h[3]);
            const eta = Math.floor(rem / bps);

            if (t[a][1] < 1024 || t[a][3] < 0.1) {
                ebi(hid).innerHTML = L.u_etaprep;
                continue;
            }

            donut.eta = eta;
            st.eta[eid] = "{0}, {1}/s, {2}".format(humansize(rem), humansize(bps, 1), humantime(eta));

            if (!etaskip)
                ebi(hid).innerHTML = st.eta[eid];
        }

        if (++etaskip > 2)
            etaskip = 0;
    }

    function got_oserr() {
        if (!hws.length || !uc.hashw || st.oserr)
            return;

        st.oserr = true;
        const msg = HTTPS ? L.u_emtleak3 : L.u_emtleak2.format((location + "").replace(":", "s:"));
        modal.alert(L.u_emtleak1 + msg + (CHROME ? L.u_emtleakc : FIREFOX ? L.u_emtleakf : ""));
    }

    function handshakes_permitted() {
        if (!st.todo.handshake.length)
            return true;

        const t = st.todo.handshake[0];
        const cd = t.cooldown;

        if (cd && cd > Date.now())
            return false;

        if (t.keepalive || t.t_uploaded)
            return true;

        if (parallel_uploads < st.busy.handshake.length)
            return false;

        if (t.n - st.car > Math.max(8, parallel_uploads))
            return false;

        if ((uc.multitask ? parallel_uploads : 0) < st.todo.upload.length + st.busy.upload.length)
            return false;

        return true;
    }

    function hashing_permitted() {
        if (!parallel_uploads)
            return false;

        const nhs = st.todo.handshake.length + st.busy.handshake.length;
        const nup = st.todo.upload.length + st.busy.upload.length;

        if (uc.multitask) {
            if (nhs + nup < parallel_uploads)
                return true;

            if (!uc.az)
                return nhs < 2;

            const ahead = st.bytes.hashed - st.bytes.finished;
            const nmax = ahead < biggest_file / 8 ? 32 : 16;
            return ahead < biggest_file && nhs < nmax;
        }

        return handshakes_permitted() && 0 == nhs + nup;
    }

    const tasker = (function() {
        let running = false;
        let was_busy = false;

        const defer = function() {
            running = false;
        };

        const taskerd = function() {
            if (running)
                return;

            if (crashed || !got_deps())
                return defer();

            running = true;

            while (true) {
                const now = Date.now();
                const blocktime = now - r.tact;
                let is_busy = st.car < st.files.length;

                if (blocktime > 2500)
                    console.log("main thread blocked for " + blocktime);

                r.tact = now;

                if (was_busy && !is_busy) {
                    for (var a = 0; a < st.files.length; a++) {
                        var t = st.files[a];

                        if (t.want_recheck) {
                            t.rechecks++;
                            t.want_recheck = false;
                            push_t(st.todo.handshake, t);
                        }
                    }

                    is_busy = st.todo.handshake.length;

                    try {
                        if (!is_busy && !uc.fsearch && !msel.getsel().length && (!mp.au || mp.au.paused))
                            treectl.goto();
                    } catch (ex) {}
                }

                if (was_busy != is_busy) {
                    st.is_busy = was_busy = is_busy;
                    window[(is_busy ? "add" : "remove") + "EventListener"]("beforeunload", warn_uploader_busy);
                    donut.on(is_busy);

                    if (!is_busy) {
                        uptoast();
                    } else {
                        timer.add(donut.do);
                        timer.add(etafun, false);
                        ebi("u2etas").style.textAlign = "left";
                    }

                    etafun();
                }

                if (flag) {
                    if (is_busy) {
                        flag.take(now);
                        ebi("u2flagblock").style.display = flag.ours ? "" : "block";

                        if (!flag.ours)
                            return defer();
                    } else if (flag.ours) {
                        flag.give();
                    }
                }

                if (st.bytes.inflight && (st.bytes.inflight < 0 || !st.busy.upload.length)) {
                    console.log("insane inflight " + st.bytes.inflight);
                    st.bytes.inflight = 0;
                }

                let mou_ikkai = false;
                let nprev = -1;

                for (var a = 0; a < st.todo.upload.length; a++) {
                    const nf = st.todo.upload[a].nfile;

                    if (nprev == nf)
                        continue;

                    nprev = nf;
                    var t = st.files[nf];

                    if (now - t.t_busied > 1000 * 30 && now - t.t_handshake > 1000 * (21600 - 1800)) {
                        apop(st.todo.handshake, t);
                        st.todo.handshake.unshift(t);
                        t.keepalive = true;
                    }
                }

                if (st.todo.head.length && st.busy.head.length < parallel_uploads && (!is_busy || st.todo.head[0].n - st.car < parallel_uploads * 2)) {
                    exec_head();
                    mou_ikkai = true;
                }

                if (handshakes_permitted() && st.todo.handshake.length) {
                    exec_handshake();
                    mou_ikkai = true;
                }

                if (st.todo.upload.length && st.busy.upload.length < parallel_uploads && can_upload_next()) {
                    exec_upload();
                    mou_ikkai = true;
                }

                if (hashing_permitted() && st.todo.hash.length && !st.busy.hash.length) {
                    exec_hash();
                    mou_ikkai = true;
                }

                if (is_busy && st.modn < 100) {
                    const t0 = Date.now() + (ebi("repl").offsetTop ? 0 : 0);

                    if (++st.modn >= 10) {
                        if (st.modn == 10)
                            st.mod0 = Date.now();

                        st.modv += Date.now() - t0;
                    }

                    if (st.modn >= 100) {
                        const n = st.modn - 10;
                        const ipu = st.modv / n;
                        const spu = (Date.now() - st.mod0) / n;
                        const ir = spu / ipu;
                        console.log("tsk:", f2f(ipu, 2), " spu:", f2f(spu, 2), " ir:", f2f(ir, 2));

                        if (ipu >= 0.5 && ir <= 15)
                            pvis.go_potato();
                    }
                }

                if (!mou_ikkai || crashed)
                    return defer();
            }
        };

        timer.add(taskerd, true);
        return taskerd;
    })();

    function uptoast() {
