    function bumpthread(dir) {
        try {
            dir.stopPropagation();
            dir.preventDefault();
        } catch (ex) {}

        const obj = ebi("nthread");

        if (dir.target) {
            clmod(obj, "err", 1);
            let v = Math.floor(parseInt(obj.value));

            if (v < 0 || v !== v)
                return;

            if (v > 64) {
                const p = obj.selectionStart;
                v = obj.value = 64;
                obj.selectionStart = obj.selectionEnd = p;
            }

            parallel_uploads = v;

            if (v == u2j)
                sdrop("nthread");
            else
                swrite("nthread", v);

            clmod(obj, "err");
            return;
        }

        parallel_uploads += dir;

        if (parallel_uploads < 0)
            parallel_uploads = 0;

        if (parallel_uploads > 16)
            parallel_uploads = 16;

        if (parallel_uploads > 6)
            toast.warn(10, L.u_maxconn);
        else if (toast.txt == L.u_maxconn)
            toast.hide();

        obj.value = parallel_uploads;

        bumpthread({
            target: 1
        });
    }

