    function set_fsearch(new_state) {
        let fixed = false;
        const persist = new_state !== undefined;
        const preferred = bcfg_get("fsearch", undefined);
        let can_write = false;

        if (!ebi("fsearch")) {
            new_state = false;
        } else if (perms.length) {
            if (!(can_write = has(perms, "write"))) {
                new_state = true;
                fixed = true;
            }

            if (!has(perms, "read") || !have_up2k_idx) {
                new_state = false;
                fixed = true;
            }

            if (new_state === undefined && preferred === undefined)
