typeFormattterErrorFormatter(context: HtmlFormatterContext, err: unknown) {
    const message = typeof err === "object" && err !== null && "message" in err && typeof err.message === "string" ? err.message : String(err);
    context.out(`<pre class="jsondiffpatch-error">${htmlEscape(message)}</pre>`);
}

formatValue(context: HtmlFormatterContext, value: unknown) {
    context.out(`<pre>${htmlEscape(JSON.stringify(value, null, 2))}</pre>`);
}

formatTextDiffString(context: HtmlFormatterContext, value: string) {
    const lines = this.parseTextDiff(value);
    context.out("<ul class=\"jsondiffpatch-textdiff\">");

    for (let i = 0, l = lines.length; i < l; i++) {
        const line = lines[i];

        context.out(
            "<li><div class=\"jsondiffpatch-textdiff-location\">" + `<span class="jsondiffpatch-textdiff-line-number">${line.location.line}</span><span class="jsondiffpatch-textdiff-char">${line.location.chr}</span></div><div class="jsondiffpatch-textdiff-line">`
        );

        const pieces = line.pieces;

        for (let pieceIndex = 0, piecesLength = pieces.length; pieceIndex < piecesLength; pieceIndex++) {
            const piece = pieces[pieceIndex];

            context.out(
                `<span class="jsondiffpatch-textdiff-${piece.type}">${htmlEscape(decodeURI(piece.text))}</span>`
            );
        }

        context.out("</div></li>");
    }

    context.out("</ul>");
}

