function htmlEscape(value: string | number) {
    if (typeof value === "number")
        return value;

    let html = String(value);

    const replacements: [RegExp, string][] = [
        [/&/g, "&amp;"],
        [/</g, "&lt;"],
        [/>/g, "&gt;"],
        [/'/g, "&apos;"],
        [/"/g, "&quot;"]
    ];

    for (let i = 0; i < replacements.length; i++) {
        html = html.replace(replacements[i][0], replacements[i][1]);
    }

    return html;
}

function jsondiffpatchHtmlFormatterAdjustArrows(nodeArg?: Element) {
    const node = nodeArg || document;

    const getElementText = (
        {
            textContent,
            innerText
        }: HTMLDivElement
    ) => textContent || innerText;

    const eachByQuery = (el: Element | Document, query: string, fn: (element: HTMLElement) => void) => {
        const elems = el.querySelectorAll(query);

        for (let i = 0, l = elems.length; i < l; i++) {
            fn(elems[i] as HTMLElement);
        }
    };

    const eachChildren = (
        {
            children
        }: ParentNode,
        fn: (child: Element, index: number) => void
    ) => {
        for (let i = 0, l = children.length; i < l; i++) {
            fn(children[i], i);
        }
    };

    eachByQuery(node, ".jsondiffpatch-arrow", (
        {
            parentNode,
            children,
            style
        }
    ) => {
        const arrowParent = parentNode as HTMLElement;
        const svg = children[0] as SVGSVGElement;
        const path = svg.children[1] as SVGPathElement;
        svg.style.display = "none";
        const destination = getElementText(arrowParent.querySelector(".jsondiffpatch-moved-destination")!);
        const container = arrowParent.parentNode!;
        let destinationElem: HTMLElement | undefined;

        eachChildren(container, child => {
            if (child.getAttribute("data-key") === destination) {
                destinationElem = child as HTMLElement;
            }
        });

        if (!destinationElem) {
            return;
        }

        try {
            const distance = destinationElem.offsetTop - arrowParent.offsetTop;
            svg.setAttribute("height", `${Math.abs(distance) + 6}`);
            style.top = `${-8 + (distance > 0 ? 0 : distance)}px`;
            const curve = distance > 0 ? `M30,0 Q-10,${Math.round(distance / 2)} 26,${distance - 4}` : `M30,${-distance} Q-10,${Math.round(-distance / 2)} 26,4`;
            path.setAttribute("d", curve);
            svg.style.display = "";
        } catch (err) {}
    });
}

(show?: boolean, node?: Element | null, delay?: number) => {
    const el = node || document.body;
    const prefix = "jsondiffpatch-unchanged-";

    const classes = {
        showing: `${prefix}showing`,
        hiding: `${prefix}hiding`,
        visible: `${prefix}visible`,
        hidden: `${prefix}hidden`
    };

    const list = el.classList;

    if (!list) {
        return;
    }

    if (!delay) {
        list.remove(classes.showing);
        list.remove(classes.hiding);
        list.remove(classes.visible);
        list.remove(classes.hidden);

        if (show === false) {
            list.add(classes.hidden);
        }

        return;
    }

    if (show === false) {
        list.remove(classes.showing);
        list.add(classes.visible);

        setTimeout(() => {
            list.add(classes.hiding);
        }, 10);
    } else {
        list.remove(classes.hiding);
        list.add(classes.showing);
        list.remove(classes.hidden);
    }

    const intervalId = setInterval(() => {
        adjustArrows(el);
    }, 100);

    setTimeout(() => {
        list.remove(classes.showing);
        list.remove(classes.hiding);

        if (show === false) {
            list.add(classes.hidden);
            list.remove(classes.visible);
        } else {
            list.add(classes.visible);
            list.remove(classes.hidden);
        }

        setTimeout(() => {
            list.remove(classes.visible);
            clearInterval(intervalId);
        }, delay + 400);
    }, delay);
}

