function adjustI18nResources(gl: Composer, options: ComposerOptions, componentOptions: any): void {
    let messages = isObject(options.messages) ? options.messages : create() as NonNullable<ComposerOptions["messages"]>;

    if ("__i18nGlobal" in componentOptions) {
        messages = getLocaleMessages(gl.locale.value as Locale, {
            messages,
            __i18n: componentOptions.__i18nGlobal
        });
    }

    const locales = Object.keys(messages);

    if (locales.length) {
        locales.forEach(locale => {
            gl.mergeLocaleMessage(locale, messages[locale]);
        });
    }

    if (!__LITE__) {
        if (isObject(options.datetimeFormats)) {
            const locales = Object.keys(options.datetimeFormats);

            if (locales.length) {
                locales.forEach(locale => {
                    gl.mergeDateTimeFormat(locale, options.datetimeFormats![locale]);
                });
            }
        }

        if (isObject(options.numberFormats)) {
            const locales = Object.keys(options.numberFormats);

            if (locales.length) {
                locales.forEach(locale => {
                    gl.mergeNumberFormat(locale, options.numberFormats![locale]);
                });
            }
        }
    }
}

