                                {keyTeam && keyTeam.models ? keyTeam.models.includes("all-proxy-models") ? userModels.filter(model => model !== "all-proxy-models").map((model: string) => (<Option key={model} value={model}>
                                    {model}
                                </Option>)) : keyTeam.models.map((model: string) => (<Option key={model} value={model}>
                                    {model}
                                </Option>)) : userModels.map((model: string) => (<Option key={model} value={model}>
                                    {model}
                                </Option>))}
                            </Select>
                        </Form.Item>
                        <Form.Item
                            className="mt-8"
                            label="Max Budget (USD)"
                            name="max_budget"
                            help={`Budget cannot exceed team max budget: ${keyTeam?.max_budget !== null && keyTeam?.max_budget !== undefined ? keyTeam?.max_budget : "unlimited"}`}
                            rules={[{
                                validator: async (_, value) => {
                                    if (value && keyTeam && keyTeam.max_budget !== null && value > keyTeam.max_budget) {
                                        console.log(`keyTeam.max_budget: ${keyTeam.max_budget}`);
                                        throw new Error(`Budget cannot exceed team max budget: $${keyTeam.max_budget}`);
                                    }
                                }
                            }]}>
                            <InputNumber step={0.01} precision={2} width={200} />
                        </Form.Item>
                        <Form.Item
                            className="mt-8"
                            label="Reset Budget"
                            name="budget_duration"
                            help={`Current Reset Budget: ${token.budget_duration}, budget will be reset: ${token.budget_reset_at ? new Date(token.budget_reset_at).toLocaleString() : "Never"}`}>
                            <Select placeholder="n/a">
                                <Select.Option value="daily">daily</Select.Option>
                                <Select.Option value="weekly">weekly</Select.Option>
                                <Select.Option value="monthly">monthly</Select.Option>
                            </Select>
                        </Form.Item>
                        <Form.Item label="token" name="token" hidden={true}></Form.Item>
                        <Form.Item
                            label="Team"
