            }}>
            {node.children.filter((i: any) => i.type === "element").map((child: any, index: number) => {
                if (child.tagName === SUPPORTED_TAGS.LABEL) {
                    return (
                        (<label
                            key={index}
                            htmlFor={child.properties.for}
                            className="my-2 system-md-semibold text-text-secondary">
                            {child.children[0]?.value || ""}
                        </label>)
                    );
                }

                if (child.tagName === SUPPORTED_TAGS.INPUT && Object.values(SUPPORTED_TYPES).includes(child.properties.type)) {
                    return (
                        (<Input
                            key={index}
                            type={child.properties.type}
                            name={child.properties.name}
                            placeholder={child.properties.placeholder}
                            value={formValues[child.properties.name]}
                            onChange={e => {
                                setFormValues(prevValues => ({
                                    ...prevValues,
                                    [child.properties.name]: e.target.value
                                }));
                            }} />)
                    );
                }

                if (child.tagName === SUPPORTED_TAGS.TEXTAREA) {
                    return (
                        (<Textarea
                            key={index}
                            name={child.properties.name}
                            placeholder={child.properties.placeholder}
                            value={formValues[child.properties.name]}
                            onChange={e => {
                                setFormValues(prevValues => ({
                                    ...prevValues,
                                    [child.properties.name]: e.target.value
                                }));
                            }} />)
                    );
                }

                if (child.tagName === SUPPORTED_TAGS.BUTTON) {
                    const variant = child.properties.dataVariant;
                    const size = child.properties.dataSize;

                    return (
                        (<Button
                            variant={variant}
                            size={size}
                            className="mt-4"
                            key={index}
                            onClick={onSubmit}>
                            <span className="text-[13px]">{child.children[0]?.value || ""}</span>
                        </Button>)
                    );
                }

                return <p key={index}>Unsupported tag:{child.tagName}</p>;
            })}
        </form>)
    );
}

async function canRespond(request, response, next) {
    const embed = response.locals.embedConfig;

    if (!embed) {
        response.sendStatus(404).end();
        return;
    }

    if (!embed.enabled) {
        response.status(503).json({
            id: uuidv4(),
            type: "abort",
            textResponse: null,
            sources: [],
            close: true,
            error: "This chat has been disabled by the administrator - try again later."
        });

        return;
    }

    const host = request.headers.origin ?? "";
    const allowedHosts = EmbedConfig.parseAllowedHosts(embed);

    if (allowedHosts !== null && !allowedHosts.includes(host)) {
        response.status(401).json({
            id: uuidv4(),
            type: "abort",
            textResponse: null,
            sources: [],
            close: true,
            error: "Invalid request."
        });

        return;
    }

    const {
        sessionId,
        message
    } = reqBody(request);

    if (!message?.length || !VALID_CHAT_MODE.includes(embed.chat_mode)) {
        response.status(400).json({
            id: uuidv4(),
            type: "abort",
            textResponse: null,
            sources: [],
            close: true,
            error: !message?.length ? "Message is empty." : `${embed.chat_mode} is not a valid mode.`
        });

        return;
    }

    if (!isNaN(embed.max_chats_per_day) && Number(embed.max_chats_per_day) > 0) {
        const dailyChatCount = await EmbedChats.count({
            embed_id: embed.id,

            createdAt: {
                gte: new Date(new Date() - 24 * 60 * 60 * 1000)
            }
        });

        if (dailyChatCount >= Number(embed.max_chats_per_day)) {
            response.status(429).json({
                id: uuidv4(),
                type: "abort",
                textResponse: null,
                sources: [],
                close: true,
                error: "The quota for this chat has been reached. Try again later or contact the site owner."
            });

            return;
        }
    }

    if (!isNaN(embed.max_chats_per_session) && Number(embed.max_chats_per_session) > 0) {
        const dailySessionCount = await EmbedChats.count({
            embed_id: embed.id,
            session_id: sessionId,

            createdAt: {
                gte: new Date(new Date() - 24 * 60 * 60 * 1000)
            }
        });

        if (dailySessionCount >= Number(embed.max_chats_per_session)) {
            response.status(429).json({
                id: uuidv4(),
                type: "abort",
                textResponse: null,
                sources: [],
                close: true,
                error: "Your quota for this chat has been reached. Try again later or contact the site owner."
            });

            return;
        }
    }

    next();
}

