function systemEndpoints(app) {
    if (!app)
        return;

    app.get("/ping", (_, response) => {
        response.status(200).json({
            online: true
        });
    });

    app.get("/migrate", async (_, response) => {
        response.sendStatus(200);
    });

    app.get("/env-dump", async (_, response) => {
        if (process.env.NODE_ENV !== "production")
            return response.sendStatus(200).end();

        dumpENV();
        response.sendStatus(200).end();
    });

    app.get("/setup-complete", async (_, response) => {
        try {
            const results = await SystemSettings.currentSettings();

            response.status(200).json({
                results
            });
        } catch (e) {
            console.error(e.message, e);
            response.sendStatus(500).end();
        }
    });

    app.get("/system/check-token", [validatedRequest], async (request, response) => {
        try {
            if (multiUserMode(response)) {
                const user = await userFromSession(request, response);

                if (!user || user.suspended) {
                    response.sendStatus(403).end();
                    return;
                }

                response.sendStatus(200).end();
                return;
            }

            response.sendStatus(200).end();
        } catch (e) {
            console.error(e.message, e);
            response.sendStatus(500).end();
        }
    });

    app.post("/request-token", async (request, response) => {
        try {
            const bcrypt = require("bcrypt");

            if (await SystemSettings.isMultiUserMode()) {
                const {
                    username,
                    password
                } = reqBody(request);

                const existingUser = await User._get({
                    username: String(username)
                });

                if (!existingUser) {
                    await EventLogs.logEvent("failed_login_invalid_username", {
                        ip: request.ip || "Unknown IP",
                        username: username || "Unknown user"
                    }, existingUser?.id);

                    response.status(200).json({
                        user: null,
                        valid: false,
                        token: null,
                        message: "[001] Invalid login credentials."
                    });

                    return;
                }

                if (!bcrypt.compareSync(String(password), existingUser.password)) {
                    await EventLogs.logEvent("failed_login_invalid_password", {
                        ip: request.ip || "Unknown IP",
                        username: username || "Unknown user"
                    }, existingUser?.id);

                    response.status(200).json({
                        user: null,
                        valid: false,
                        token: null,
                        message: "[002] Invalid login credentials."
                    });

                    return;
                }

                if (existingUser.suspended) {
                    await EventLogs.logEvent("failed_login_account_suspended", {
                        ip: request.ip || "Unknown IP",
                        username: username || "Unknown user"
                    }, existingUser?.id);

                    response.status(200).json({
                        user: null,
                        valid: false,
                        token: null,
                        message: "[004] Account suspended by admin."
                    });

                    return;
                }

                await Telemetry.sendTelemetry("login_event", {
                    multiUserMode: false
                }, existingUser?.id);

                await EventLogs.logEvent("login_event", {
                    ip: request.ip || "Unknown IP",
                    username: existingUser.username || "Unknown user"
                }, existingUser?.id);

                if (!existingUser.seen_recovery_codes) {
                    const plainTextCodes = await generateRecoveryCodes(existingUser.id);

                    response.status(200).json({
                        valid: true,
                        user: User.filterFields(existingUser),

                        token: makeJWT({
                            id: existingUser.id,
                            username: existingUser.username
                        }, "30d"),

                        message: null,
                        recoveryCodes: plainTextCodes
                    });

                    return;
                }

                response.status(200).json({
                    valid: true,
                    user: User.filterFields(existingUser),

                    token: makeJWT({
                        id: existingUser.id,
                        username: existingUser.username
                    }, "30d"),

                    message: null
                });

                return;
            } else {
                const {
                    password
                } = reqBody(request);

                if (!bcrypt.compareSync(password, bcrypt.hashSync(process.env.AUTH_TOKEN, 10))) {
                    await EventLogs.logEvent("failed_login_invalid_password", {
                        ip: request.ip || "Unknown IP",
                        multiUserMode: false
                    });

                    response.status(401).json({
                        valid: false,
                        token: null,
                        message: "[003] Invalid password provided"
                    });

                    return;
                }

                await Telemetry.sendTelemetry("login_event", {
                    multiUserMode: false
                });

                await EventLogs.logEvent("login_event", {
                    ip: request.ip || "Unknown IP",
                    multiUserMode: false
                });

                response.status(200).json({
                    valid: true,

                    token: makeJWT({
                        p: new EncryptionManager().encrypt(password)
                    }, "30d"),

                    message: null
                });
            }
        } catch (e) {
            console.error(e.message, e);
            response.sendStatus(500).end();
        }
    });

    app.get(
        "/request-token/sso/simple",
        [simpleSSOEnabled],
