    app.get("/system/logo", async function(request, response) {
        try {
            const darkMode = !request?.query?.theme || request?.query?.theme === "default";
            const defaultFilename = getDefaultFilename(darkMode);
            const logoPath = await determineLogoFilepath(defaultFilename);

            const {
                found,
                buffer,
                size,
                mime
            } = fetchLogo(logoPath);

            if (!found) {
                response.sendStatus(204).end();
                return;
            }

            const currentLogoFilename = await SystemSettings.currentLogoFilename();

            response.writeHead(200, {
                "Access-Control-Expose-Headers": "Content-Disposition,X-Is-Custom-Logo,Content-Type,Content-Length",
                "Content-Type": mime || "image/png",
                "Content-Disposition": `attachment; filename=${path.basename(logoPath)}`,
                "Content-Length": size,
                "X-Is-Custom-Logo": currentLogoFilename !== null && currentLogoFilename !== defaultFilename && !isDefaultFilename(currentLogoFilename)
            });

            response.end(Buffer.from(buffer, "base64"));
            return;
        } catch (error) {
            console.error("Error processing the logo request:", error);

            response.status(500).json({
                message: "Internal server error"
            });
        }
    });

