                const userRecord = await User.get({
                    id: user.id
                });

                const oldPfpFilename = userRecord.pfpFilename;

                if (oldPfpFilename) {
                    const storagePath = path.join(__dirname, "../storage/assets/pfp");
                    const oldPfpPath = path.join(storagePath, normalizePath(userRecord.pfpFilename));

                    if (!isWithin(path.resolve(storagePath), path.resolve(oldPfpPath)))
                        throw new Error("Invalid path name");

                    if (fs.existsSync(oldPfpPath))
                        fs.unlinkSync(oldPfpPath);
                }

                const {
                    success,
                    error
                } = await User.update(user.id, {
                    pfpFilename: uploadedFileName
                });

                return response.status(success ? 200 : 500).json({
                    message: success ? "Profile picture uploaded successfully." : error || "Failed to update with new profile picture."
