(
    {
        nodeId,
        propKey,
        propSchema,
        currentValue,
        errors,
        connections,
        handleInputChange,
        handleInputClick,
        className,
        displayName
    }
) => {
    className = cn(className, "my-2");
    displayName ||= propSchema.title || beautifyString(propKey);

    if ("allOf" in propSchema) {
        propSchema = propSchema.allOf[0];
        console.warn(`Unsupported 'allOf' in schema for '${propKey}'!`, propSchema);
    }

    if ("credentials_provider" in propSchema) {
        return (
            (<NodeCredentialsInput
                selfKey={propKey}
                value={currentValue}
                errors={errors}
                className={className}
                handleInputChange={handleInputChange} />)
        );
    }

    if ("properties" in propSchema) {
        return (
            (<NodeObjectInputTree
                nodeId={nodeId}
                selfKey={propKey}
                schema={propSchema}
                object={currentValue}
                errors={errors}
                className={cn("border-l border-gray-500 pl-2", className)}
                displayName={displayName}
                connections={connections}
                handleInputClick={handleInputClick}
                handleInputChange={handleInputChange} />)
        );
    }

    if ("additionalProperties" in propSchema) {
        return (
            (<NodeKeyValueInput
                nodeId={nodeId}
                selfKey={propKey}
                schema={propSchema}
                entries={currentValue}
                errors={errors}
                className={className}
                displayName={displayName}
                connections={connections}
                handleInputChange={handleInputChange} />)
        );
    }

    if ("anyOf" in propSchema) {
        const types = propSchema.anyOf.map(s => ("type" in s ? s.type : undefined));

        if (types.includes("string") && types.includes("null")) {
            return (
                (<NodeStringInput
                    selfKey={propKey}
                    schema={{
                        ...propSchema,
                        type: "string"
                    } as BlockIOStringSubSchema}
                    value={currentValue}
                    error={errors[propKey]}
                    className={className}
                    displayName={displayName}
                    handleInputChange={handleInputChange}
                    handleInputClick={handleInputClick} />)
            );
        }
    }

    if ("oneOf" in propSchema) {
        console.error(`Unsupported 'oneOf' in schema for '${propKey}'!`, propSchema);
        return null;
    }

    if (!("type" in propSchema)) {
        return (
            (<NodeFallbackInput
                selfKey={propKey}
                schema={propSchema}
                value={currentValue}
                error={errors[propKey]}
                className={className}
                displayName={displayName}
                handleInputChange={handleInputChange}
                handleInputClick={handleInputClick} />)
        );
    }

    switch (propSchema.type) {
    case "string":
        return (
            (<NodeStringInput
                selfKey={propKey}
                schema={propSchema}
                value={currentValue}
                error={errors[propKey]}
                className={className}
                displayName={displayName}
                handleInputChange={handleInputChange}
                handleInputClick={handleInputClick} />)
        );
    case "boolean":
        return (
            (<NodeBooleanInput
                selfKey={propKey}
                schema={propSchema}
                value={currentValue}
                error={errors[propKey]}
                className={className}
                displayName={displayName}
                handleInputChange={handleInputChange} />)
        );
    case "number":
    case "integer":
        return (
            (<NodeNumberInput
                selfKey={propKey}
                schema={propSchema}
                value={currentValue}
                error={errors[propKey]}
                className={className}
                displayName={displayName}
                handleInputChange={handleInputChange} />)
        );
    case "array":
        return (
            (<NodeArrayInput
                nodeId={nodeId}
                selfKey={propKey}
                schema={propSchema}
                entries={currentValue}
                errors={errors}
                className={className}
                displayName={displayName}
                connections={connections}
                handleInputChange={handleInputChange}
                handleInputClick={handleInputClick} />)
        );
    case "object":
        return (
            (<NodeKeyValueInput
                nodeId={nodeId}
                selfKey={propKey}
                schema={propSchema}
                entries={currentValue}
                errors={errors}
                className={className}
                displayName={displayName}
                connections={connections}
                handleInputChange={handleInputChange} />)
        );
    default:
        console.warn(`Schema for '${propKey}' specifies unknown type:`, propSchema);

        return (
            (<NodeFallbackInput
                selfKey={propKey}
                schema={propSchema}
                value={currentValue}
                error={errors[propKey]}
                className={className}
                displayName={displayName}
                handleInputChange={handleInputChange}
                handleInputClick={handleInputClick} />)
        );
    }
}

