(value: any): ((el: HTMLInputElement | null) => void) => {
    return el => el && value && (el.value = value);
}

(
    {
        nodeId,
        selfKey,
        entries,
        schema,
        connections,
        handleInputChange,
        errors,
        className,
        displayName
    }
) => {
    const getPairValues = useCallback(() => {
        const defaultEntries = new Map(Object.entries(entries ?? schema.default ?? {}));
        const prefix = `${selfKey}_#_`;
        connections.filter(c => c.targetHandle.startsWith(prefix) && c.target === nodeId).map(c => c.targetHandle.slice(prefix.length)).forEach(k => !defaultEntries.has(k) && defaultEntries.set(k, ""));

        return Array.from(defaultEntries, ([key, value]) => ({
            key,
            value
        }));
    }, [entries, schema.default, connections, nodeId, selfKey]);

    const [keyValuePairs, setKeyValuePairs] = useState<{
        key: string;
        value: string | number | null;
    }[]>([]);

    useEffect(
        () => setKeyValuePairs(getPairValues()),
        [connections, entries, schema.default, getPairValues]
    );

    function updateKeyValuePairs(newPairs: typeof keyValuePairs) {
        setKeyValuePairs(newPairs);

        handleInputChange(selfKey, newPairs.reduce((
            obj,
            {
                key,
                value
            }
        ) => ({
            ...obj,
            [key]: value
        }), {}));
    }

    function convertValueType(value: string): string | number | null {
        if (!schema.additionalProperties || schema.additionalProperties.type == "string")
            return value;

        if (!value)
            return null;

        return Number(value);
    }

    function getEntryKey(key: string): string {
        return `${selfKey}_#_${key}`;
    }

    function isConnected(key: string): boolean {
        return connections.some(c => c.targetHandle === getEntryKey(key) && c.target === nodeId);
    }

    return (
        (<div
            className={cn(className, keyValuePairs.length > 0 ? "flex flex-col" : "")}>
            <div>
                {keyValuePairs.map((
                    {
                        key,
                        value
                    },
                    index
                ) => (<div key={getEntryKey(key)}>
                    <NodeHandle
                        keyName={getEntryKey(key)}
                        schema={{
                            type: "string"
                        }}
                        isConnected={isConnected(key)}
                        isRequired={false}
                        side="left" />
                    {!isConnected(key) && (<div className="nodrag mb-2 flex items-center space-x-2">
                        <Input
                            type="text"
                            placeholder="Key"
                            ref={InputRef(key ?? "")}
                            onBlur={e => updateKeyValuePairs(keyValuePairs.toSpliced(index, 1, {
                                key: e.target.value,
                                value: value
                            }))} />
                        <Input
                            type="text"
                            placeholder="Value"
                            ref={InputRef(value ?? "")}
                            onBlur={e => updateKeyValuePairs(keyValuePairs.toSpliced(index, 1, {
                                key: key,
                                value: convertValueType(e.target.value)
                            }))} />
                        <Button
                            variant="ghost"
                            className="px-2"
                            onClick={() => updateKeyValuePairs(keyValuePairs.toSpliced(index, 1))}>
                            <Cross2Icon />
                        </Button>
                    </div>)}
                    {errors[`${selfKey}.${key}`] && <span className="error-message">{errors[`${selfKey}.${key}`]}</span>}
                </div>))}
                <Button
                    className="bg-gray-200 font-normal text-black hover:text-white"
                    disabled={keyValuePairs.length > 0 && !keyValuePairs[keyValuePairs.length - 1].key}
                    onClick={() => updateKeyValuePairs(keyValuePairs.concat({
                        key: "",
                        value: ""
                    }))}>
                    <PlusIcon className="mr-2" />Add Property</Button>
            </div>
            {errors[selfKey] && <span className="error-message">{errors[selfKey]}</span>}
        </div>)
    );
}

(
    {
        nodeId,
        selfKey,
        schema,
        entries,
        errors,
        connections,
