        handleInputClick,
        className,
        displayName
    }
) => {
    entries ??= schema.default ?? [];
    const prefix = `${selfKey}_$_`;

    connections.filter(c => c.targetHandle.startsWith(prefix) && c.target === nodeId).map(c => parseInt(c.targetHandle.slice(prefix.length))).filter(c => !isNaN(c)).forEach(
        c => entries.length <= c && entries.push(...Array(c - entries.length + 1).fill(""))
    );

    const isItemObject = "items" in schema && "properties" in schema.items!;
    const error = typeof errors[selfKey] === "string" ? errors[selfKey] : undefined;

    return (
        (<div className={cn(className, "flex flex-col")}>
            {displayName && <strong>{displayName}</strong>}
            {entries.map((entry: any, index: number) => {
                const entryKey = `${selfKey}_$_${index}`;
                const isConnected = connections && connections.some(c => c.targetHandle === entryKey && c.target === nodeId);

                return (
                    (<div key={entryKey} className="self-start">
                        <div className="mb-2 flex space-x-2">
                            <NodeHandle
                                keyName={entryKey}
                                schema={schema.items!}
                                isConnected={isConnected}
                                isRequired={false}
                                side="left" />
                            {!isConnected && (schema.items ? (<NodeGenericInputField
                                nodeId={nodeId}
                                propKey={entryKey}
                                propSchema={schema.items}
                                currentValue={entry}
                                errors={errors}
                                connections={connections}
