function transformMiddleware(server: ViteDevServer): Connect.NextHandleFunction {
    const {
        config: {
            root,
            logger
        },

        moduleGraph
    } = server;

    return async function viteTransformMiddleware(req, res, next) {
        if (req.method !== "GET" || knownIgnoreList.has(req.url!)) {
            return next();
        }

        let url: string;

        try {
            url = decodeURI(removeTimestampQuery(req.url!)).replace(NULL_BYTE_PLACEHOLDER, "\u0000");
        } catch (e) {
            return next(e);
        }

        const withoutQuery = cleanUrl(url);

        try {
            const isSourceMap = withoutQuery.endsWith(".map");

            if (isSourceMap) {
                const depsOptimizer = getDepsOptimizer(server.config, false);

                if (depsOptimizer?.isOptimizedDepUrl(url)) {
                    const sourcemapPath = url.startsWith(FS_PREFIX) ? fsPathFromId(url) : normalizePath(path.resolve(root, url.slice(1)));

                    try {
                        const map = JSON.parse(await fsp.readFile(sourcemapPath, "utf-8")) as ExistingRawSourceMap;
                        applySourcemapIgnoreList(map, sourcemapPath, server.config.server.sourcemapIgnoreList, logger);

                        return send(req, res, JSON.stringify(map), "json", {
                            headers: server.config.server.headers
                        });
                    } catch (e) {
                        const dummySourceMap = {
                            version: 3,
                            file: sourcemapPath.replace(/\.map$/, ""),
                            sources: [],
                            sourcesContent: [],
                            names: [],
                            mappings: ";;;;;;;;;"
                        };

                        return send(req, res, JSON.stringify(dummySourceMap), "json", {
                            cacheControl: "no-cache",
                            headers: server.config.server.headers
                        });
                    }
                } else {
                    const originalUrl = url.replace(/\.map($|\?)/, "$1");
                    const map = (await moduleGraph.getModuleByUrl(originalUrl, false))?.transformResult?.map;

                    if (map) {
                        return send(req, res, JSON.stringify(map), "json", {
                            headers: server.config.server.headers
                        });
                    } else {
                        return next();
                    }
                }
            }

            const publicDir = normalizePath(server.config.publicDir);
            const rootDir = normalizePath(server.config.root);

            if (publicDir.startsWith(withTrailingSlash(rootDir))) {
                const publicPath = `${publicDir.slice(rootDir.length)}/`;

                if (url.startsWith(withTrailingSlash(publicPath))) {
                    let warning: string;

                    if (isImportRequest(url)) {
                        const rawUrl = removeImportQuery(url);

                        if (urlRE.test(url)) {
                            warning = `Assets in the public directory are served at the root path.\n` + `Instead of ${colors.cyan(rawUrl)}, use ${colors.cyan(rawUrl.replace(publicPath, "/"))}.`;
                        } else {
                            warning = "Assets in public directory cannot be imported from JavaScript.\n" + `If you intend to import that asset, put the file in the src directory, and use ${colors.cyan(rawUrl.replace(publicPath, "/src/"))} instead of ${colors.cyan(rawUrl)}.\n` + `If you intend to use the URL of that asset, use ${colors.cyan(injectQuery(rawUrl.replace(publicPath, "/"), "url"))}.`;
                        }
                    } else {
                        warning = `files in the public directory are served at the root path.\n` + `Instead of ${colors.cyan(url)}, use ${colors.cyan(url.replace(publicPath, "/"))}.`;
                    }

                    logger.warn(colors.yellow(warning));
                }
            }

            if ((rawRE.test(url) || urlRE.test(url)) && !ensureServingAccess(url, server, res, next)) {
                return;
            }

            if (isJSRequest(url) || isImportRequest(url) || isCSSRequest(url) || isHTMLProxy(url)) {
                url = removeImportQuery(url);
                url = unwrapId(url);

                if (isCSSRequest(url) && !isDirectRequest(url) && req.headers.accept?.includes("text/css")) {
                    url = injectQuery(url, "direct");
                }

                const ifNoneMatch = req.headers["if-none-match"];

                if (ifNoneMatch && (await moduleGraph.getModuleByUrl(url, false))?.transformResult?.etag === ifNoneMatch) {
                    debugCache?.(`[304] ${prettifyUrl(url, root)}`);
                    res.statusCode = 304;
                    return res.end();
                }

                const result = await transformRequest(url, server, {
                    html: req.headers.accept?.includes("text/html")
                });

                if (result) {
                    const depsOptimizer = getDepsOptimizer(server.config, false);
                    const type = isDirectCSSRequest(url) ? "css" : "js";
                    const isDep = DEP_VERSION_RE.test(url) || depsOptimizer?.isOptimizedDepUrl(url);

                    return send(req, res, result.code, type, {
                        etag: result.etag,
                        cacheControl: isDep ? "max-age=31536000,immutable" : "no-cache",
                        headers: server.config.server.headers,
                        map: result.map
                    });
                }
            }
        } catch (e) {
            if (e?.code === ERR_OPTIMIZE_DEPS_PROCESSING_ERROR) {
                if (!res.writableEnded) {
                    res.statusCode = 504;
                    res.statusMessage = "Optimize Deps Processing Error";
                    res.end();
                }

                logger.error(e.message);
                return;
            }

            if (e?.code === ERR_OUTDATED_OPTIMIZED_DEP) {
                if (!res.writableEnded) {
                    res.statusCode = 504;
                    res.statusMessage = "Outdated Optimize Dep";
                    res.end();
                }

                return;
            }

            if (e?.code === ERR_CLOSED_SERVER) {
                if (!res.writableEnded) {
                    res.statusCode = 504;
                    res.statusMessage = "Outdated Request";
                    res.end();
                }

                return;
            }

            if (e?.code === ERR_LOAD_URL) {
                return next();
            }

            return next(e);
        }

        next();
    };
}

