function validate(fs, name, root, cb) {
    if (name === root)
        return cb(null, true);

    fs.lstat(name, function(err, st) {
        if (err && err.code === "ENOENT")
            return validate(fs, path.join(name, ".."), root, cb);
        else if (err)
            return cb(err);

        cb(null, st.isDirectory());
    });
