function statAll(fs, stat, cwd, ignore, entries, sort) {
    if (!entries)
        entries = ["."];

    const queue = entries.slice(0);

    return function loop(callback) {
        if (!queue.length)
            return callback(null);

        const next = queue.shift();
        const nextAbs = path.join(cwd, next);

        stat.call(fs, nextAbs, function(err, stat) {
            if (err)
                return callback(entries.indexOf(next) === -1 && err.code === "ENOENT" ? null : err);

            if (!stat.isDirectory())
                return callback(null, next, stat);

            fs.readdir(nextAbs, function(err, files) {
                if (err)
                    return callback(err);

                if (sort)
                    files.sort();

                for (let i = 0; i < files.length; i++) {
                    if (!ignore(path.join(cwd, next, files[i])))
                        queue.push(path.join(next, files[i]));
                }

                callback(null, next, stat);
            });
        });
    };
}

