                muted: "muted",
                poster: this.sanitizeURL(this.previewElement.attr("src"))
            }).append($("<source>", {
                type: "video/mp4",
                src: this.sanitizeURL(videoSrcMp4)
            }), $("<source>", {
                type: "video/webm",
                src: this.sanitizeURL(videoSrcWebm)
            }));

            const gp = this;

            const checkLoad = function() {
                if (gp.videoElement[0].readyState === 4) {
                    gp.playVideo();
                    gp.animationLoaded = true;
                } else {
                    setTimeout(checkLoad, 100);
                }
            };

            const wait = this.getOption("wait");

            if (wait) {
                checkLoad();
            } else {
                this.playVideo();
            }

            this.videoElement.on("click", function() {
                if (gp.videoPaused) {
                    gp.resumeVideo();
                } else {
                    gp.pauseVideo();
                }
            });
        },

        playVideo: function() {
            this.spinnerElement.hide();
            this.previewElement.hide();
            this.playElement.hide();
            this.gifLoaded = true;
            this.previewElement.hide();
            this.wrapper.append(this.videoElement);
            this.videoPaused = false;
            this.videoElement[0].play();
            this.getOption("onPlay").call(this.previewElement);
        },

        pauseVideo: function() {
            this.videoPaused = true;
            this.videoElement[0].pause();
            this.playElement.show();
            this.mouseoverEnabled = false;
            this.getOption("onStop").call(this.previewElement);
        },

        resumeVideo: function() {
            this.videoPaused = false;
            this.videoElement[0].play();
            this.playElement.hide();
            this.getOption("onPlay").call(this.previewElement);
        },

        enableAbort: function() {
            const gp = this;

            this.previewElement.click(function(e) {
                gp.abortLoading(e);
            });

            this.spinnerElement.click(function(e) {
                gp.abortLoading(e);
            });
        },

        abortLoading: function(e) {
            this.spinnerElement.hide();
            this.playElement.show();
            e.preventDefault();
            e.stopPropagation();

            this.gifElement.off("load").on("load", function(ev) {
                ev.preventDefault();
                ev.stopPropagation();
            });

            this.resetEvents();
            this.getOption("onStop").call(this.previewElement);
        },

        resetEvents: function() {
            this.previewElement.off("click");
            this.previewElement.off("mouseover");
            this.playElement.off("click");
            this.spinnerElement.off("click");
            this.addEvents();
        },

        sanitizeURL: function(url) {
            const parser = document.createElement("a");
            parser.href = url;
            const allowedProtocols = ["http:", "https:", ":", "file:"];

            if (allowedProtocols.includes(parser.protocol)) {
                return parser.href;
            } else {
                return "about:blank";
            }
        }
    };

    $.fn.gifplayer = function(options) {
        if (/^(play|stop)$/i.test(options)) {
            return this.each(function() {
                options = options.toLowerCase();

                if ($(this).hasClass("gifplayer-ready")) {
                    const gp = new GifPlayer($(this), null);
                    gp.options = {};
                    gp.options = $.extend({}, $.fn.gifplayer.defaults, gp.options);
                    gp.wrapper = $(this).parent();
                    gp.spinnerElement = gp.wrapper.find(".spinner");
                    gp.playElement = gp.wrapper.find(".play-gif");
                    gp.gifElement = gp.wrapper.find(".gp-gif-element");
                    gp.videoElement = gp.wrapper.find(".gp-video-element");
                    gp.mode = gp.getOption("mode");

                    switch (options) {
                    case "play":
                        gp.playElement.trigger("click");
                        break;
                    case "stop":
                        if (!gp.playElement.is(":visible")) {
                            if (gp.mode == "gif") {
                                gp.stopGif();
                            } else if (gp.mode == "video") {
                                gp.videoElement.trigger("click");
                            }
                        }

                        break;
                    }
                }
            });
        } else {
            return this.each(function() {
                options = $.extend({}, $.fn.gifplayer.defaults, options);
                const gifplayer = new GifPlayer($(this), options);
                gifplayer.activate();
            });
        }
    };

    $.fn.gifplayer.defaults = {
        label: "GIF",
        playOn: "click",
        mode: "gif",
        gif: "",
        mp4: "",
        webm: "",
        wait: false,
        scope: false,
        onPlay: function() {},
        onStop: function() {},
        onClick: function() {},
        onLoad: function() {},
        onLoadComplete: function() {}
    };

    return GifPlayer;
}

function transformMiddleware(server: ViteDevServer): Connect.NextHandleFunction {
    const {
        root,
        publicDir
    } = server.config;

    const publicDirInRoot = publicDir.startsWith(withTrailingSlash(root));
    const publicPath = `${publicDir.slice(root.length)}/`;

    return async function viteTransformMiddleware(req, res, next) {
        const environment = server.environments.client;

        if (req.method !== "GET" || knownIgnoreList.has(req.url!)) {
            return next();
        }

        let url: string;

        try {
            url = decodeURI(removeTimestampQuery(req.url!)).replace(NULL_BYTE_PLACEHOLDER, "\u0000");
        } catch (e) {
            return next(e);
        }

        const withoutQuery = cleanUrl(url);

        try {
            const isSourceMap = withoutQuery.endsWith(".map");

            if (isSourceMap) {
                const depsOptimizer = environment.depsOptimizer;

                if (depsOptimizer?.isOptimizedDepUrl(url)) {
                    const sourcemapPath = url.startsWith(FS_PREFIX) ? fsPathFromId(url) : normalizePath(path.resolve(server.config.root, url.slice(1)));

                    try {
                        const map = JSON.parse(await fsp.readFile(sourcemapPath, "utf-8")) as ExistingRawSourceMap;

                        applySourcemapIgnoreList(
                            map,
                            sourcemapPath,
                            server.config.server.sourcemapIgnoreList,
                            server.config.logger
                        );

                        return send(req, res, JSON.stringify(map), "json", {
                            headers: server.config.server.headers
                        });
                    } catch {
                        const dummySourceMap = {
                            version: 3,
                            file: sourcemapPath.replace(/\.map$/, ""),
                            sources: [],
                            sourcesContent: [],
                            names: [],
                            mappings: ";;;;;;;;;"
                        };

                        return send(req, res, JSON.stringify(dummySourceMap), "json", {
                            cacheControl: "no-cache",
                            headers: server.config.server.headers
                        });
                    }
                } else {
                    const originalUrl = url.replace(/\.map($|\?)/, "$1");
                    const map = (await environment.moduleGraph.getModuleByUrl(originalUrl))?.transformResult?.map;

                    if (map) {
                        return send(req, res, JSON.stringify(map), "json", {
                            headers: server.config.server.headers
                        });
                    } else {
                        return next();
                    }
                }
            }

            if (publicDirInRoot && url.startsWith(publicPath)) {
                warnAboutExplicitPublicPathInUrl(url);
            }

            const urlWithoutTrailingQuerySeparators = url.replace(trailingQuerySeparatorsRE, "");

            if ((rawRE.test(urlWithoutTrailingQuerySeparators) || urlRE.test(urlWithoutTrailingQuerySeparators)) && !ensureServingAccess(urlWithoutTrailingQuerySeparators, server, res, next)) {
                return;
            }

            if (req.headers["sec-fetch-dest"] === "script" || isJSRequest(url) || isImportRequest(url) || isCSSRequest(url) || isHTMLProxy(url)) {
                url = removeImportQuery(url);
                url = unwrapId(url);

                if (isCSSRequest(url)) {
                    if (req.headers.accept?.includes("text/css") && !isDirectRequest(url)) {
                        url = injectQuery(url, "direct");
                    }

                    const ifNoneMatch = req.headers["if-none-match"];

                    if (ifNoneMatch && (await environment.moduleGraph.getModuleByUrl(url))?.transformResult?.etag === ifNoneMatch) {
                        debugCache?.(`[304] ${prettifyUrl(url, server.config.root)}`);
                        res.statusCode = 304;
                        return res.end();
                    }
                }

                const result = await transformRequest(environment, url, {
                    html: req.headers.accept?.includes("text/html")
                });

                if (result) {
                    const depsOptimizer = environment.depsOptimizer;
                    const type = isDirectCSSRequest(url) ? "css" : "js";
                    const isDep = DEP_VERSION_RE.test(url) || depsOptimizer?.isOptimizedDepUrl(url);

                    return send(req, res, result.code, type, {
                        etag: result.etag,
                        cacheControl: isDep ? "max-age=31536000,immutable" : "no-cache",
                        headers: server.config.server.headers,
                        map: result.map
                    });
                }
            }
        } catch (e) {
            if (e?.code === ERR_OPTIMIZE_DEPS_PROCESSING_ERROR) {
                if (!res.writableEnded) {
                    res.statusCode = 504;
                    res.statusMessage = "Optimize Deps Processing Error";
                    res.end();
                }

                server.config.logger.error(e.message);
                return;
            }

            if (e?.code === ERR_OUTDATED_OPTIMIZED_DEP) {
                if (!res.writableEnded) {
                    res.statusCode = 504;
                    res.statusMessage = "Outdated Optimize Dep";
                    res.end();
                }

                return;
            }

            if (e?.code === ERR_CLOSED_SERVER) {
                if (!res.writableEnded) {
                    res.statusCode = 504;
                    res.statusMessage = "Outdated Request";
                    res.end();
                }

                return;
            }

            if (e?.code === ERR_FILE_NOT_FOUND_IN_OPTIMIZED_DEP_DIR) {
                if (!res.writableEnded) {
                    res.statusCode = 404;
                    res.end();
                }

                server.config.logger.warn(colors.yellow(e.message));
                return;
            }

            if (e?.code === ERR_LOAD_URL) {
                return next();
            }

            return next(e);
        }

        next();
    };

    function warnAboutExplicitPublicPathInUrl(url: string) {
        let warning: string;

        if (isImportRequest(url)) {
            const rawUrl = removeImportQuery(url);

            if (urlRE.test(url)) {
                warning = `Assets in the public directory are served at the root path.\n` + `Instead of ${colors.cyan(rawUrl)}, use ${colors.cyan(rawUrl.replace(publicPath, "/"))}.`;
            } else {
                warning = "Assets in public directory cannot be imported from JavaScript.\n" + `If you intend to import that asset, put the file in the src directory, and use ${colors.cyan(rawUrl.replace(publicPath, "/src/"))} instead of ${colors.cyan(rawUrl)}.\n` + `If you intend to use the URL of that asset, use ${colors.cyan(injectQuery(rawUrl.replace(publicPath, "/"), "url"))}.`;
            }
        } else {
            warning = `Files in the public directory are served at the root path.\n` + `Instead of ${colors.cyan(url)}, use ${colors.cyan(url.replace(publicPath, "/"))}.`;
        }

        server.config.logger.warn(colors.yellow(warning));
    }
}

