            let anchor = document.querySelector<HTMLDivElement>(`#${widgetId}`);

            if (!anchor) {
                anchor = document.createElement("div");
                anchor.id = widgetId;
                document.body.appendChild(anchor);
            }

            const tagDialog = true;
            const isSingleCommit = true;
            const waitForDialog = new PromiseDelegate<string | null>();

            const dialog = ReactWidget.create(<NewTagDialogBox
                pastCommits={[commit.commit]}
                model={gitModel}
                trans={trans}
                open={tagDialog}
                onClose={(tagName?: string) => {
                    dialog.dispose();
                    waitForDialog.resolve(tagName ?? null);
                }}
                isSingleCommit={isSingleCommit} />);

            Widget.attach(dialog, anchor);
            const tagName = await waitForDialog.promise;

            if (tagName) {
                const id = Notification.emit(
                    trans.__("Create tag pointing to '%1'...", commit.commit.commit_msg),
                    "in-progress"
                );

                try {
                    await gitModel.setTag(tagName, commit.commit.commit);
                } catch (err) {
                    Notification.update({
                        id,
                        message: trans.__("Failed to create tag '%1' poining to '%2'.", tagName, commit),
                        type: "error",
                        ...showError(err as any, trans)
                    });

                    return;
                }

                Notification.update({
                    id,
                    message: trans.__("Created tag '%1' pointing to '%2'.", tagName, commit),
                    type: "success"
                });
            }
        },

        icon: tagIcon.bindprops({
            stylesheet: "menuItem"
        })
    });
}

function createGitMenu(commands: CommandRegistry, trans: TranslationBundle): Menu {
    const RESOURCES = [{
        text: trans.__("Set Up Remotes"),
        url: "https://www.atlassian.com/git/tutorials/setting-up-a-repository"
    }, {
        text: trans.__("Git Documentation"),
        url: "https://git-scm.com/doc"
    }];

    const menu = new Menu({
        commands
    });

    menu.title.label = trans.__("Git");

    [
        CommandIDs.gitInit,
        CommandIDs.gitClone,
        CommandIDs.gitMerge,
        CommandIDs.gitPush,
        CommandIDs.gitPull,
        CommandIDs.gitResetToRemote,
        CommandIDs.gitManageRemote,
        CommandIDs.gitTerminalCommand,
        CommandIDs.gitStash
    ].forEach(command => {
        menu.addItem({
            command
        });

        if (command === CommandIDs.gitPush) {
            menu.addItem({
                command,

                args: {
                    advanced: true
                }
            });
        }

        if (command === CommandIDs.gitPull) {
            menu.addItem({
                command,

                args: {
                    force: true
                }
            });
        }
    });

    menu.addItem({
        type: "separator"
    });

    menu.addItem({
        command: CommandIDs.gitToggleSimpleStaging
    });

    menu.addItem({
        command: CommandIDs.gitToggleDoubleClickDiff
    });

    menu.addItem({
        type: "separator"
    });

    menu.addItem({
        command: CommandIDs.gitOpenGitignore
    });

    menu.addItem({
        type: "separator"
    });

    const tutorial = new Menu({
        commands
    });

    tutorial.title.label = trans.__(" Help ");

    RESOURCES.map(args => {
        tutorial.addItem({
            args,
            command: CommandIDs.gitOpenUrl
        });
    });

    menu.addItem({
        type: "submenu",
        submenu: tutorial
    });

    return menu;
}

