function addFileBrowserContextMenu(
    model: IGitExtension,
    filebrowser: FileBrowser,
    contents: Contents.IManager,
    contextMenu: ContextMenuSvg,
    trans: TranslationBundle
): void {
    let gitMenu: Menu | null = null;
    let _commands: ContextCommandIDs[];
    let _paths: string[];

    function updateItems(menu: Menu): void {
        const wasShown = menu.isVisible;
        const parent = menu.parentMenu;
        const items = Array.from(filebrowser.selectedItems());

        const statuses = new Set<Git.Status>(items.map(item => {
            const itemPath = contents.localPath(item.path);
            return model.pathRepository === null ? undefined : model.getFile(itemPath)?.status;
        }).filter(status => typeof status !== "undefined"));

        const allCommands = new Set<ContextCommandIDs>(
            [].concat(...[...statuses].map(status => CONTEXT_COMMANDS[status!])).filter(
                command => command !== ContextCommandIDs.gitFileOpen && command !== ContextCommandIDs.gitFileDelete && typeof command !== "undefined"
            ).map(
                command => command === ContextCommandIDs.gitFileStage || command === ContextCommandIDs.gitFileTrack ? ContextCommandIDs.gitFileAdd : command
            )
        );

        const commandsChanged = !_commands || _commands.length !== allCommands.size || !_commands.every(command => allCommands.has(command));
        const paths = items.map(item => item.path);
        const filesChanged = !_paths || !ArrayExt.shallowEqual(_paths, paths);

        if (commandsChanged || filesChanged) {
            const commandsList = [...allCommands];
            menu.clearItems();

            addMenuItems(
                commandsList,
                menu,
                (paths ?? []).map(path => model.getFile(path)).filter(file => !["null", "undefined"].includes(typeof file))
            );

            if (wasShown) {
                parent!.triggerActiveItem();
            }

            _commands = commandsList;
            _paths = paths;
        }
    }

    function updateGitMenu(contextMenu: ContextMenu) {
        if (!gitMenu) {
            gitMenu = contextMenu.menu.items.find(
                item => item.type === "submenu" && item.submenu?.id === "jp-contextmenu-git"
            )?.submenu ?? null;
        }

        if (!gitMenu) {
            return;
        }

        updateItems(gitMenu);
        const renderedStatus = model.status;

        model.refreshStatus().then(() => {
            if (model.status !== renderedStatus) {
                updateItems(gitMenu!);
            }
        }).catch(error => {
            console.error("Fail to refresh model when displaying git context menu.", error);
        });
    }

    if ((contextMenu as any).opened) {
        (contextMenu as any).opened.connect(updateGitMenu);
    } else {
        class GitMenu extends Menu {
            protected onBeforeAttach(msg: Message): void {
                updateGitMenu(contextMenu);
                super.onBeforeAttach(msg);
            }
        }

        const selectorNotDir = ".jp-DirListing-item[data-isdir=\"false\"]";

        gitMenu = new GitMenu({
            commands: contextMenu.menu.commands
        });

        gitMenu.title.label = trans.__("Git");

        gitMenu.title.icon = gitIcon.bindprops({
            stylesheet: "menuItem"
        });

        contextMenu.addItem({
            type: "submenu",
            submenu: gitMenu,
            selector: selectorNotDir,
            rank: 5
        });
    }
}

async function showGitOperationDialog<T>(
    model: IGitExtension,
    operation: Operation,
    trans: TranslationBundle,
    args?: T,
    authentication?: Git.IAuth,
    retry = false
): Promise<string> {
    async function getCurrentRemote(currentRemoteName: string): Promise<string> {
        const remoteList = await model.getRemotes().then(remoteList => {
            return remoteList;
        });

        const currentRemote = remoteList.find(remoteURI => remoteURI.name === currentRemoteName);

        if (currentRemote) {
            return currentRemote?.url;
        } else {
            return "";
        }
    }

    function getGitProviderHost(remoteUrl: string): string {
        const re = /https:\/\/([^.]+)\./;
        const result = remoteUrl.match(re) ?? [];
        const gitProvider = result[1];
        return gitProvider;
    }

    try {
        let result: Git.IResultWithMessage;

        switch (operation) {
        case Operation.Clone:
            const {
                path,
                url,
                versioning,
                submodules
            } = args as any as IGitCloneArgs;

            result = await model.clone(path, url, authentication, versioning ?? true, submodules ?? false);
            break;
        case Operation.Pull:
            result = await model.pull(authentication);
            break;
        case Operation.Push:
            result = await model.push(authentication, false, (args as unknown as {
                remote: string;
            })["remote"]);

            break;
        case Operation.ForcePush:
            result = await model.push(authentication, true, (args as unknown as {
                remote: string;
            })["remote"]);

            break;
        case Operation.Fetch:
            result = await model.fetch(authentication);
            model.credentialsRequired = false;
            break;
        default:
            result = {
                code: -1,
                message: "Unknown git command"
            };

            break;
        }

        return result.message;
    } catch (error) {
        if (AUTH_ERROR_MESSAGES.some(errorMessage => (error as Error).message.indexOf(errorMessage) > -1)) {
            let gitPasswordPlaceholder = trans.__("password / personal access token");
            let remoteGitProvider = "";

            switch (operation) {
            case Operation.Clone:
                const {
                    url: encodedArgsUrl
                } = args as any as IGitCloneArgs;

                remoteGitProvider = getGitProviderHost(decodeURIComponent(encodedArgsUrl));
                break;
            case Operation.Push:
            case Operation.ForcePush:
            case Operation.Pull:
                if (model.currentBranch?.upstream) {
                    const remoteName = model.currentBranch.upstream.split("/")[0];
                    const currentRemoteUrl = await getCurrentRemote(remoteName);
                    remoteGitProvider = currentRemoteUrl ? getGitProviderHost(currentRemoteUrl) : "";
                } else {
                    const remoteList = await model.getRemotes().then(remoteList => {
                        return remoteList;
                    });

                    remoteGitProvider = getGitProviderHost(remoteList[0]?.url);
                }

                break;
            case Operation.Fetch:
                remoteGitProvider = await model.getRemotes().then(remoteList => remoteList[0]?.url);
                break;
            default:
                break;
            }

            if (remoteGitProvider && remoteGitProvider.toLowerCase() === "github") {
                gitPasswordPlaceholder = trans.__("personal access token");
            }

            const credentials = await showDialog({
                title: trans.__("Git credentials required"),

                body: new GitCredentialsForm(
                    trans,
                    trans.__("Enter credentials for remote repository"),
                    retry ? trans.__("Incorrect username or password.") : "",
                    gitPasswordPlaceholder
                )
            });

            if (credentials.button.accept) {
                return await showGitOperationDialog<T>(model, operation, trans, args, credentials.value ?? undefined, true);
            } else {
                throw new CancelledError();
            }
        }

        throw error;
    }
}

