function resolveServerOptions(root: string, raw: ServerOptions | undefined, logger: Logger): ResolvedServerOptions {
    const _server = mergeWithDefaults({
        ...serverConfigDefaults,
        host: undefined,
        sourcemapIgnoreList: isInNodeModules
    }, raw ?? {});

    const server: ResolvedServerOptions = {
        ..._server,

        fs: {
            ..._server.fs,
            allow: raw?.fs?.allow ?? [searchForWorkspaceRoot(root)]
        },

        sourcemapIgnoreList: _server.sourcemapIgnoreList === false ? () => false : _server.sourcemapIgnoreList
    };

    let allowDirs = server.fs.allow;

    if (process.versions.pnp) {
        const cwd = searchForPackageRoot(root);

        try {
            const enableGlobalCache = execSync("yarn config get enableGlobalCache", {
                cwd
            }).toString().trim() === "true";

            const yarnCacheDir = execSync(`yarn config get ${enableGlobalCache ? "globalFolder" : "cacheFolder"}`, {
                cwd
            }).toString().trim();

            allowDirs.push(yarnCacheDir);
        } catch (e) {
            logger.warn(`Get yarn cache dir error: ${e.message}`, {
                timestamp: true
            });
        }
    }

    allowDirs = allowDirs.map(i => resolvedAllowDir(root, i));
    const resolvedClientDir = resolvedAllowDir(root, CLIENT_DIR);

    if (!allowDirs.some(dir => isParentDirectory(dir, resolvedClientDir))) {
        allowDirs.push(resolvedClientDir);
    }

    server.fs.allow = allowDirs;

    if (server.origin?.endsWith("/")) {
        server.origin = server.origin.slice(0, -1);

        logger.warn(colors.yellow(
            `${colors.bold("(!)")} server.origin should not end with "/". Using "${server.origin}" instead.`
        ));
    }

    if (process.env.__VITE_ADDITIONAL_SERVER_ALLOWED_HOSTS && Array.isArray(server.allowedHosts)) {
        const additionalHost = process.env.__VITE_ADDITIONAL_SERVER_ALLOWED_HOSTS;
        server.allowedHosts = [...server.allowedHosts, additionalHost];
    }

    return server;
}

async function restartServer(server: ViteDevServer) {
    global.__vite_start_time = performance.now();
    const shortcutsOptions = server._shortcutsOptions;
    let inlineConfig = server.config.inlineConfig;

    if (server._forceOptimizeOnRestart) {
        inlineConfig = mergeConfig(inlineConfig, {
            forceOptimizeDeps: true
        });
    }

    {
        let newServer: ViteDevServer | null = null;

        try {
            newServer = await _createServer(inlineConfig, {
                listen: false,
                previousEnvironments: server.environments
            });
        } catch (err: any) {
            server.config.logger.error(err.message, {
                timestamp: true
            });

            server.config.logger.error("server restart failed", {
                timestamp: true
            });

            return;
        }

        await server.close();
        const middlewares = server.middlewares;
        newServer._configServerPort = server._configServerPort;
        newServer._currentServerPort = server._currentServerPort;
        Object.assign(server, newServer);
        middlewares.stack = newServer.middlewares.stack;
        server.middlewares = middlewares;
        newServer._setInternalServer(server);
    }

    const {
        logger,

        server: {
            port,
            middlewareMode
        }
    } = server.config;

    if (!middlewareMode) {
        await server.listen(port, true);
    } else {
        await Promise.all(Object.values(server.environments).map(e => e.listen(server)));
    }

    logger.info("server restarted.", {
        timestamp: true
    });

    if (shortcutsOptions) {
        shortcutsOptions.print = false;
        bindCLIShortcuts(server, shortcutsOptions);
    }
}

validate(packageNameAliases) {
    const validationResult = {
        type: "success",
        errors: []
    };

    const packageNameAliasPairs = this._getPackageNameAliasPairs(packageNameAliases);

    for (const [packageName, packageMetadata] of Object.entries(this.packages)) {
        if (!("resolved" in packageMetadata)) {
            continue;
        }

        if (Object.hasOwn(packageNameAliasPairs, this._getPackageNameOnly(packageName))) {
            debug(
                `skipping package name validation for aliased package name: ${packageName} resolving to: ${packageNameAliasPairs[packageName]}}`
            );

            continue;
        }

        try {
            const packageResolvedURL = new URL(packageMetadata.resolved);

            if (!Object.values(REGISTRY).includes(packageResolvedURL.host)) {
                debug(
                    `skipping package name '${packageName}' validation for non-official registry '${packageResolvedURL.origin}'`
                );

                continue;
            }

            const path = packageResolvedURL.pathname;
            const packageNameFromResolved = path.split("/-/")[0].slice(1);
            const packageNameOnly = this._getPackageNameOnly(packageName);
            const expectedURLBeginning = `${packageResolvedURL.origin}/${packageNameOnly}`;
            const isPassing = packageMetadata.resolved.startsWith(expectedURLBeginning);

            if (!isPassing) {
                validationResult.errors.push({
                    message: `detected resolved URL for package with a different name: ${packageNameOnly}\n    expected: ${packageNameOnly}\n    actual: ${packageNameFromResolved}\n`,
                    package: packageNameOnly
                });
            }
        } catch (error) {}
    }

    if (validationResult.errors.length !== 0) {
        validationResult.type = "error";
    }

    return validationResult;
}

