async targetUrl => {
    console.log(`[SCREENSHOT] Request received for URL: ${targetUrl}`);

    if (!targetUrl) {
        console.error("[SCREENSHOT] URL is missing from queryStringParameters");
        throw new Error("URL is missing from queryStringParameters");
    }

    if (!targetUrl.startsWith("http://") && !targetUrl.startsWith("https://")) {
        targetUrl = "http://" + targetUrl;
    }

    try {
        new URL(targetUrl);
    } catch (error) {
        console.error(`[SCREENSHOT] URL provided is invalid: ${targetUrl}`);
        throw new Error("URL provided is invalid");
    }

    try {
        console.log(`[SCREENSHOT] Using direct Chromium method for URL: ${targetUrl}`);
        const base64Screenshot = await directChromiumScreenshot(targetUrl);
        console.log(`[SCREENSHOT] Direct screenshot successful`);

        return {
            image: base64Screenshot
        };
    } catch (directError) {
        console.error(`[SCREENSHOT] Direct screenshot method failed: ${directError.message}`);
        console.log(`[SCREENSHOT] Falling back to puppeteer method...`);
    }

    let browser = null;

    try {
        console.log(`[SCREENSHOT] Launching puppeteer browser`);

        browser = await puppeteer.launch({
            args: [...chromium.args, "--no-sandbox"],

            defaultViewport: {
                width: 800,
                height: 600
            },

            executablePath: process.env.CHROME_PATH || "/usr/bin/chromium",
            headless: true,
            ignoreHTTPSErrors: true,
            ignoreDefaultArgs: ["--disable-extensions"]
        });

        console.log(`[SCREENSHOT] Creating new page`);
        const page = await browser.newPage();
        console.log(`[SCREENSHOT] Setting page preferences`);

        await page.emulateMediaFeatures([{
            name: "prefers-color-scheme",
            value: "dark"
        }]);

        page.setDefaultNavigationTimeout(8000);
        console.log(`[SCREENSHOT] Navigating to URL: ${targetUrl}`);

        await page.goto(targetUrl, {
            waitUntil: "domcontentloaded"
        });

        console.log(`[SCREENSHOT] Checking if body element exists`);

        await page.evaluate(() => {
            const selector = "body";

            return new Promise((resolve, reject) => {
                const element = document.querySelector(selector);

                if (!element) {
                    reject(new Error(`Error: No element found with selector: ${selector}`));
                }

                resolve();
            });
        });

        console.log(`[SCREENSHOT] Taking screenshot`);
        const screenshotBuffer = await page.screenshot();
        console.log(`[SCREENSHOT] Converting screenshot to base64`);
        const base64Screenshot = screenshotBuffer.toString("base64");
        console.log(`[SCREENSHOT] Screenshot complete, returning image`);

        return {
            image: base64Screenshot
        };
    } catch (error) {
        console.error(`[SCREENSHOT] Puppeteer screenshot failed: ${error.message}`);
        throw error;
    } finally {
        if (browser !== null) {
            console.log(`[SCREENSHOT] Closing browser`);
            await browser.close();
        }
    }
}

function(editor) {
    const regexGetSizeOrEmpty = /(^\s*(\d+)(px)?\s*$)|^$/i;
    const lockButtonId = CKEDITOR.tools.getNextId();
    const resetButtonId = CKEDITOR.tools.getNextId();
    const lang = editor.lang.image2_chamilo;
    const commonLang = editor.lang.common;
    const colorDialog = editor.plugins.colordialog;
    const lockResetStyle = "margin-top:18px;width:40px;height:20px;";

    const lockResetHtml = new CKEDITOR.template(
        "<div>" + "<a href=\"javascript:void(0)\" tabindex=\"-1\" title=\"" + lang.lockRatio + "\" class=\"cke_btn_locked\" id=\"{lockButtonId}\" role=\"checkbox\">" + "<span class=\"cke_icon\"></span>" + "<span class=\"cke_label\">" + lang.lockRatio + "</span>" + "</a>" + "<a href=\"javascript:void(0)\" tabindex=\"-1\" title=\"" + lang.resetSize + "\" class=\"cke_btn_reset\" id=\"{resetButtonId}\" role=\"button\">" + "<span class=\"cke_label\">" + lang.resetSize + "</span>" + "</a>" + "</div>"
    ).output({
        lockButtonId: lockButtonId,
        resetButtonId: resetButtonId
    });

    const helpers = CKEDITOR.plugins.image2_chamilo;
    const config = editor.config;
    const hasFileBrowser = !!(config.filebrowserImageBrowseUrl || config.filebrowserBrowseUrl);
    const features = editor.widgets.registered.image.features;
    const getNatural = helpers.getNatural;
    let doc;
    let widget;
    let image;
    let preLoader;
    let domWidth;
    let domHeight;
    let preLoadedWidth;
    let preLoadedHeight;
    let srcChanged;
    let lockRatio;
    let userDefinedLock;
    let lockButton;
    let resetButton;
    let widthField;
    let heightField;
    let natural;

    function validateDimension() {
        const match = this.getValue().match(regexGetSizeOrEmpty);
        const isValid = !!(match && parseInt(match[1], 10) !== 0);

        if (!isValid)
            alert(commonLang["invalid" + CKEDITOR.tools.capitalize(this.id)]);

        return isValid;
    }

    function createPreLoader() {
        const image = doc.createElement("img");
        const listeners = [];

        function addListener(event, callback) {
            listeners.push(image.once(event, function(evt) {
                removeListeners();
                callback(evt);
            }));
        }

        function removeListeners() {
            let l;

            while ((l = listeners.pop()))
                l.removeListener();
        }

        return function(src, callback, scope) {
            addListener("load", function() {
                const dimensions = getNatural(image);
                callback.call(scope, image, dimensions.width, dimensions.height);
            });

            addListener("error", function() {
                callback(null);
            });

            addListener("abort", function() {
                callback(null);
            });

            image.setAttribute(
                "src",
                (config.baseHref || "") + src + "?" + Math.random().toString(16).substring(2)
            );
        };
    }

    function onChangeSrc() {
        const value = this.getValue();
        toggleDimensions(false);

        if (value !== widget.data.src) {
            preLoader(value, function(image, width, height) {
                toggleDimensions(true);

                if (!image)
                    return toggleLockRatio(false);

                widthField.setValue(editor.config.image2_chamilo_prefillDimensions === false ? 0 : width);
                heightField.setValue(editor.config.image2_chamilo_prefillDimensions === false ? 0 : height);
                preLoadedWidth = width;
                preLoadedHeight = height;
                toggleLockRatio(helpers.checkHasNaturalRatio(image));
            });

            srcChanged = true;
        } else if (srcChanged) {
            toggleDimensions(true);
            widthField.setValue(domWidth);
            heightField.setValue(domHeight);
            srcChanged = false;
        } else {
            toggleDimensions(true);
        }
    }

    function onChangeDimension() {
        if (!lockRatio)
            return;

        let value = this.getValue();

        if (!value)
            return;

        if (!value.match(regexGetSizeOrEmpty))
            toggleLockRatio(false);

        if (value === "0")
            return;

        const isWidth = this.id == "width";
        const width = domWidth || preLoadedWidth;
        const height = domHeight || preLoadedHeight;

        if (isWidth)
            value = Math.round(height * (value / width));
        else
            value = Math.round(width * (value / height));

        if (!isNaN(value))
            (isWidth ? heightField : widthField).setValue(value);
    }

    function onLoadLockReset() {
        const dialog = this.getDialog();

        function setupMouseClasses(el) {
            el.on("mouseover", function() {
                this.addClass("cke_btn_over");
            }, el);

            el.on("mouseout", function() {
                this.removeClass("cke_btn_over");
            }, el);
        }

        lockButton = doc.getById(lockButtonId);
        resetButton = doc.getById(resetButtonId);

        if (lockButton) {
            dialog.addFocusable(lockButton, 4 + hasFileBrowser);

            lockButton.on("click", function(evt) {
                toggleLockRatio();
                evt.data && evt.data.preventDefault();
            }, this.getDialog());

            setupMouseClasses(lockButton);
        }

        if (resetButton) {
            dialog.addFocusable(resetButton, 5 + hasFileBrowser);

            resetButton.on("click", function(evt) {
                if (srcChanged) {
                    widthField.setValue(preLoadedWidth);
                    heightField.setValue(preLoadedHeight);
                } else {
                    widthField.setValue(domWidth);
                    heightField.setValue(domHeight);
                }

                evt.data && evt.data.preventDefault();
            }, this);

            setupMouseClasses(resetButton);
        }
    }

    function toggleLockRatio(enable) {
        if (!lockButton)
            return;

        if (typeof enable == "boolean") {
            if (userDefinedLock)
                return;

            lockRatio = enable;
        } else {
            const width = widthField.getValue();
            let height;
            userDefinedLock = true;
            lockRatio = !lockRatio;

            if (lockRatio && width) {
                height = (domHeight / domWidth) * width;

                if (!isNaN(height))
                    heightField.setValue(Math.round(height));
            }
        }

        lockButton[lockRatio ? "removeClass" : "addClass"]("cke_btn_unlocked");
        lockButton.setAttribute("aria-checked", lockRatio);

        if (CKEDITOR.env.hc) {
            const icon = lockButton.getChild(0);
            icon.setHtml(lockRatio ? (CKEDITOR.env.ie ? "■" : "▣") : CKEDITOR.env.ie ? "□" : "▢");
        }
    }

    function toggleDimensions(enable) {
        const method = enable ? "enable" : "disable";
        widthField[method]();
        heightField[method]();
    }

    const srcBoxChildren = [{
        id: "src",
        type: "text",
        label: commonLang.url,
        onKeyup: onChangeSrc,
        onChange: onChangeSrc,

        setup: function(widget) {
            this.setValue(widget.data.src);
        },

        commit: function(widget) {
            widget.setData("src", this.getValue());
        },

        validate: CKEDITOR.dialog.validate.notEmpty(lang.urlMissing)
    }];

    if (hasFileBrowser) {
        srcBoxChildren.push({
            type: "button",
            id: "browse",
            style: "display:inline-block;margin-top:14px;",
            align: "center",
            label: editor.lang.common.browseServer,
            hidden: true,
            filebrowser: "info:src"
        });
    }

    return {
        title: lang.title,
        minWidth: 270,
        minHeight: 100,

        onLoad: function() {
            doc = this._.element.getDocument();
            preLoader = createPreLoader();
        },

        onShow: function() {
            widget = this.widget;
            image = widget.parts.image;
            srcChanged = userDefinedLock = lockRatio = false;
            natural = getNatural(image);
            preLoadedWidth = domWidth = natural.width;
            preLoadedHeight = domHeight = natural.height;
        },

        contents: [{
            id: "info",
            label: lang.infoTab,

            elements: [{
                type: "vbox",
                padding: 0,

                children: [{
                    type: "hbox",
                    widths: ["100%"],
                    className: "cke_dialog_image_url",
                    children: srcBoxChildren
                }]
            }, {
                id: "alt",
                type: "text",
                label: lang.alt,

                setup: function(widget) {
                    this.setValue(widget.data.alt);
                },

                commit: function(widget) {
                    widget.setData("alt", this.getValue());
                },

                validate: editor.config.image2_chamilo_altRequired === true ? CKEDITOR.dialog.validate.notEmpty(lang.altMissing) : null
            }, {
                type: "hbox",
                widths: ["25%", "25%", "50%"],
                requiredContent: features.dimension.requiredContent,

                children: [{
                    type: "text",
                    width: "45px",
                    id: "width",
                    label: commonLang.width,
                    validate: validateDimension,
                    onKeyUp: onChangeDimension,

                    onLoad: function() {
                        widthField = this;
                    },

                    setup: function(widget) {
                        this.setValue(widget.data.width);
                    },

                    commit: function(widget) {
                        widget.setData("width", this.getValue());
                    }
                }, {
                    type: "text",
                    id: "height",
                    width: "45px",
                    label: commonLang.height,
                    validate: validateDimension,
                    onKeyUp: onChangeDimension,

                    onLoad: function() {
                        heightField = this;
                    },

                    setup: function(widget) {
                        this.setValue(widget.data.height);
                    },

                    commit: function(widget) {
                        widget.setData("height", this.getValue());
                    }
                }, {
                    id: "lock",
                    type: "html",
                    style: lockResetStyle,
                    onLoad: onLoadLockReset,

                    setup: function(widget) {
                        toggleLockRatio(widget.data.lock);
                    },

                    commit: function(widget) {
                        widget.setData("lock", lockRatio);
                    },

                    html: lockResetHtml
                }]
            }, {
                type: "hbox",
                id: "alignment",
                requiredContent: features.align.requiredContent,

                children: [{
                    id: "align",
                    type: "select",

                    items: [
                        [commonLang.alignNone, "none"],
                        [commonLang.alignLeft, "left"],
                        [commonLang.alignCenter, "center"],
                        [commonLang.alignRight, "right"],
                        [lang.alignBaseline, "baseline"],
                        [lang.alignTop, "top"],
                        [lang.alignBottom, "bottom"],
                        [lang.alignMiddle, "middle"],
                        [lang.alignSuper, "super"],
