    const channelID = useSelector(getCurrentChannelId);
    const channel = useSelector((state: GlobalState) => getChannel(state, channelID));
    const teamID = useSelector(getCurrentTeamId);
    const publicChannelPermission = useHasChannelPermission(teamID, channelID, Permissions.MANAGE_PUBLIC_CHANNEL_PROPERTIES);
    const privateChannelPermission = useHasChannelPermission(teamID, channelID, Permissions.MANAGE_PRIVATE_CHANNEL_PROPERTIES);

    const [
        welcomeMsg,
        setWelcomeMsg,
        welcomeMsgInit,
        welcomeMsgReset,
        welcomeMsgOverwrite
    ] = useActionState(welcomeMsgEmptyState);

    const [
        categorization,
        setCategorization,
        categorizationInit,
        categorizationReset,
        categorizationOverwrite
    ] = useActionState(categorizationEmptyState);

    const [prompt, setPrompt, promptInit, promptReset, promptOverwrite] = useActionState(promptEmptyState);
    const editable = channel?.type === "O" ? publicChannelPermission : privateChannelPermission;

    useEffect(() => {
        const getActions = async (id: string) => {
            welcomeMsgInit(welcomeMsgEmptyState);
            categorizationInit(categorizationEmptyState);
            promptInit(promptEmptyState);
            const fetchedActions = await fetchChannelActions(id);

            fetchedActions.forEach(action => {
                switch (action.action_type) {
                case ChannelActionType.WelcomeMessage:
                    welcomeMsgInit({
                        id: action.id,
                        enabled: action.enabled,
                        payload: action.payload as WelcomeMessageActionPayload
                    });

                    break;
                case ChannelActionType.CategorizeChannel:
                    categorizationInit({
                        id: action.id,
                        enabled: action.enabled,
                        payload: action.payload as CategorizeChannelPayload
                    });

                    break;
                case ChannelActionType.PromptRunPlaybook:
                    promptInit({
                        id: action.id,
                        enabled: action.enabled,
                        payload: action.payload as PromptRunPlaybookFromKeywordsPayload
                    });

                    break;
                }
            });
        };

        if (channelID && show) {
            getActions(channelID);
        }
    }, [channelID, show, welcomeMsgInit, categorizationInit, promptInit]);

    const onHide = () => {
        welcomeMsgReset();
        promptReset();
        categorizationReset();
        dispatch(hideChannelActionsModal());
    };

    const onSave = () => {
        const welcomeMessageAction = {
            ...welcomeMsg,
            channel_id: channelID,
            action_type: ChannelActionType.WelcomeMessage,
            trigger_type: ChannelTriggerType.NewMemberJoins
        };

        saveChannelAction(welcomeMessageAction).then(id => setWelcomeMsg({
            ...welcomeMsg,
            id
        }));

        welcomeMsgOverwrite();

        const categorizeChannelAction = {
            ...categorization,
            channel_id: channelID,
            action_type: ChannelActionType.CategorizeChannel,
            trigger_type: ChannelTriggerType.NewMemberJoins
        };

        saveChannelAction(categorizeChannelAction).then(id => setCategorization({
            ...categorization,
            id
        }));

        categorizationOverwrite();

        const promptRunPlaybookAction = {
            ...prompt,
            channel_id: channelID,
            action_type: ChannelActionType.PromptRunPlaybook,
            trigger_type: ChannelTriggerType.KeywordsPosted
        };

        saveChannelAction(promptRunPlaybookAction).then(id => setPrompt({
            ...prompt,
            id
        }));

        promptOverwrite();
        dispatch(hideChannelActionsModal());
    };

    return (
        (<ActionsModal
            id={"channel-actions-modal"}
            title={formatMessage({
                defaultMessage: "Channel Actions"
            })}
            subtitle={formatMessage({
                defaultMessage: "Channel actions allow you to automate activities for this channel"
            })}
            show={show}
            onHide={onHide}
            editable={editable}
            onSave={onSave}
            isValid={true}>
            <TriggersContainer>
                <Trigger
                    title={formatMessage({
                        defaultMessage: "When a user joins the channel"
                    })}>
                    <ActionsContainer>
                        <Action
                            enabled={welcomeMsg.enabled}
                            title={formatMessage({
                                defaultMessage: "Send a temporary welcome message to the user"
                            })}
                            editable={editable}
                            onToggle={() => setWelcomeMsg({
                                ...welcomeMsg,
                                enabled: !welcomeMsg.enabled
                            })}>
                            <WelcomeActionChildren
                                message={welcomeMsg.payload.message}
                                onUpdate={msg => setWelcomeMsg({
                                    ...welcomeMsg,

                                    payload: {
                                        message: msg
                                    }
                                })}
                                editable={editable} />
                        </Action>
                        <Action
                            enabled={categorization.enabled}
                            title={formatMessage({
                                defaultMessage: "Add the channel to a sidebar category for the user"
                            })}
                            editable={editable}
                            onToggle={() => setCategorization({
                                ...categorization,
                                enabled: !categorization.enabled
                            })}>
                            <CategorizeChannelChildren
                                categoryName={categorization.payload.category_name}
                                onUpdate={name => setCategorization({
                                    ...categorization,

                                    payload: {
                                        category_name: name
                                    }
                                })}
                                editable={editable} />
                        </Action>
                    </ActionsContainer>
                </Trigger>
                <Trigger
                    title={formatMessage({
                        defaultMessage: "When a message with these keywords is posted"
                    })}
                    triggerModifier={<TriggerKeywords
                        editable={editable}
                        keywords={prompt.payload.keywords}
                        onUpdate={newKeywords => setPrompt({
                            ...prompt,

                            payload: {
                                ...prompt.payload,
                                keywords: newKeywords
                            }
                        })} />}>
                    <ActionsContainer>
                        <Action
                            enabled={prompt.enabled}
                            title={formatMessage({
                                defaultMessage: "Prompt to run a playbook"
                            })}
                            editable={editable}
                            onToggle={() => setPrompt({
                                ...prompt,
                                enabled: !prompt.enabled
                            })}>
                            <RunPlaybookChildren
                                playbookId={prompt.payload.playbook_id}
                                onUpdate={newId => setPrompt({
                                    ...prompt,

                                    payload: {
                                        ...prompt.payload,
                                        playbook_id: newId
                                    }
                                })}
                                editable={editable} />
                        </Action>
                    </ActionsContainer>
                </Trigger>
            </TriggersContainer>
        </ActionsModal>)
    );
}

