    if (this.options.enabledPlugins.length === 0) {
        throw new FormidableError(
            "expect at least 1 enabled builtin plugin, see options.enabledPlugins",
            errors.missingPlugin
        );
    }

    this.options.enabledPlugins.forEach(plugin => {
        this.use(plugin);
    });

