        }

        if (fileSize > this.options.maxFileSize) {
            this._error(new FormidableError(
                `options.maxFileSize (${this.options.maxFileSize} bytes), received ${fileSize} bytes of file data`,
                errors.biggerThanMaxFileSize,
                413
            ));

            return;
        }

