    const newPath = path.join(this.uploadDir, name);

    if (!newPath.startsWith(this.uploadDir)) {
        return path.join(this.uploadDir, this.options.defaultInvalidName);
    }

    return newPath;
}

_setUpRename() {
    const hasRename = typeof this.options.filename === "function";

    if (hasRename) {
        this._getNewName = part => {
            let ext = "";
            let name = this.options.defaultInvalidName;

            if (part.originalFilename) {
                ({
                    ext,
                    name
                } = path.parse(part.originalFilename));

                if (this.options.keepExtensions !== true) {
                    ext = "";
                }
            }

            return this.options.filename.call(this, name, ext, part, this);
        };
    } else {
        this._getNewName = part => {
            const name = createId();

            if (part && this.options.keepExtensions) {
                const originalFilename = typeof part === "string" ? part : part.originalFilename;
                return `${name}${this._getExtension(originalFilename)}`;
            }

            return name;
        };
    }
}

_setUpMaxFields() {
    if (this.options.maxFields !== Infinity) {
        let fieldsCount = 0;

        this.on("field", () => {
            fieldsCount += 1;

            if (fieldsCount > this.options.maxFields) {
                this._error(new FormidableError(
                    `options.maxFields (${this.options.maxFields}) exceeded`,
                    errors.maxFieldsExceeded,
                    413
                ));
            }
        });
    }
}

_setUpMaxFiles() {
    if (this.options.maxFiles !== Infinity) {
        let fileCount = 0;

        this.on("fileBegin", () => {
            fileCount += 1;

            if (fileCount > this.options.maxFiles) {
                this._error(new FormidableError(
                    `options.maxFiles (${this.options.maxFiles}) exceeded`,
                    errors.maxFilesExceeded,
                    413
                ));
            }
        });
    }
}

_maybeEnd() {
    if (!this.ended || this._flushing || this.error) {
        return;
    }

    this.req = null;
    this.emit("end");
}

private async setContentHeaders(
    binaryDataId: string,
    action: "view" | "download",
    res: Response,
    fileName?: string,
    mimeType?: string
) {
    if (!fileName || !mimeType) {
        try {
            const metadata = await this.binaryDataService.getMetadata(binaryDataId);
            fileName = metadata.fileName;
            mimeType = metadata.mimeType;
            res.setHeader("Content-Length", metadata.fileSize);
        } catch {}
    }

    if (mimeType) {
        res.setHeader("Content-Type", mimeType);

        if (mimeType.includes("html") && action === "view") {
            res.header("Content-Security-Policy", "sandbox");
        }
    }

    if (action === "download" && fileName) {
        const encodedFilename = encodeURIComponent(fileName);
        res.setHeader("Content-Disposition", `attachment; filename="${encodedFilename}"`);
    }
}

