    if (exists(homedir)) {
        directories.push({
            dir: homedir,
            dirDescription: "home"
        });
    } else {
        Logger.getInstance().warn("Home directory of the user is not defined");
    }

    Logger.getInstance().debug(`Detected default directories: ${driverDirectory}`);
    return directories;
}

