(url, headers = {}) => {
    return new Promise((resolve, reject) => {
        const parsedUrl = new URL(url);
        const h = parsedUrl.protocol === "https:" ? https : http;

        const options = {
            headers: headers
        };

        h.get(url, options, res => {
            if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
                res.resume();

                fetchUrl(res.headers.location).then(buffer => {
                    resolve(buffer);
                }, result => {
                    reject(result);
                });

                return;
            }

            const ok = res.statusCode >= 200 && res.statusCode < 300;

            if (!ok) {
                reject(
                    new TypeError(`Failed to fetch (status code: ${res.statusCode}, url: "${url}")`)
                );

                res.resume();
                return;
            }

            const chunks = [];
            res.on("end", () => resolve(Buffer.concat(chunks)));
            res.on("data", d => chunks.push(d));
        }).on("error", reject);
    });
}

(url, headers = {}, redirectCount = 0) => {
    if (redirectCount >= MAX_REDIRECTS) {
        return new Promise((_, reject) => {
            reject(new Error(`Too many redirects (limit: ${MAX_REDIRECTS})`));
        });
    }

    return new Promise((resolve, reject) => {
        const parsedUrl = new URL(url);
        const h = parsedUrl.protocol === "https:" ? https : http;

        const options = {
            headers: headers
        };

        h.get(url, options, res => {
            if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
                res.resume();

                fetchUrl(res.headers.location, {}, redirectCount + 1).then(buffer => {
                    resolve(buffer);
                }, result => {
                    reject(result);
                });

                return;
            }

            const ok = res.statusCode >= 200 && res.statusCode < 300;

            if (!ok) {
                reject(
                    new TypeError(`Failed to fetch (status code: ${res.statusCode}, url: "${url}")`)
                );

                res.resume();
                return;
            }

            const chunks = [];
            res.on("end", () => resolve(Buffer.concat(chunks)));
            res.on("data", d => chunks.push(d));
        }).on("error", reject);
    });
}

constructor(fs) {
    this.fs = fs;
    this.resolving = {};
}

resolve(url, headers = {}) {
    if (!this.resolving[url]) {
        this.resolving[url] = new Promise((resolve, reject) => {
            if (url.toLowerCase().indexOf("https://") === 0 || url.toLowerCase().indexOf("http://") === 0) {
                if (this.fs.existsSync(url)) {
                    resolve();
                } else {
                    fetchUrl(url, headers).then(buffer => {
                        this.fs.writeFileSync(url, buffer);
                        resolve();
                    }, result => {
                        reject(result);
                    });
                }
            } else {
                resolve();
            }
        });
    }

    return this.resolving[url];
}

resolved() {
    return new Promise((resolve, reject) => {
        Promise.all(Object.values(this.resolving)).then(() => {
            resolve();
        }, result => {
            reject(result);
        });
    });
}

function base(ALPHABET) {
