async (path: SubPath, ctx: AppContext) => {
    const user = await fetchUser(path, ctx);
    await ctx.joplin.models.user().checkIfAllowed(ctx.joplin.owner, AclAction.Update, user);
    const postedUser = await postedUserFromContext(ctx);

    await ctx.joplin.models.user().save({
        id: user.id,
        ...postedUser
    });
}

async function fetchUser(path: SubPath, ctx: AppContext): Promise<User> {
    const user = await ctx.joplin.models.user().load(path.id);

    if (!user)
        throw new ErrorNotFound(`No user with ID ${path.id}`);

    return user;
}

async function postedUserFromContext(ctx: AppContext): Promise<User> {
    return ctx.joplin.models.user().fromApiInput(await bodyFields<any>(ctx.req));
}

async (path: SubPath, ctx: AppContext) => {
    const user = await fetchUser(path, ctx);
    await ctx.joplin.models.user().checkIfAllowed(ctx.joplin.owner, AclAction.Read, user);
    return user;
}

async (path: SubPath, ctx: AppContext) => {
    const user = await ctx.joplin.models.user().loadByEmail(path.id);

    if (!user)
        return "";

    const ppk = await ctx.joplin.models.user().publicPrivateKey(user.id);

    if (!ppk)
        return "";

    return {
        id: ppk.id,
        publicKey: ppk.publicKey
    };
}

async (_path: SubPath, ctx: AppContext) => {
    await ctx.joplin.models.user().checkIfAllowed(ctx.joplin.owner, AclAction.Create);
    const user = await postedUserFromContext(ctx);
    user.password = uuidgen();
    user.must_set_password = 1;
    user.email_confirmed = 0;
    const output = await ctx.joplin.models.user().save(user);
    return ctx.joplin.models.user().toApiOutput(output);
}

async (_path: SubPath, ctx: AppContext) => {
    await ctx.joplin.models.user().checkIfAllowed(ctx.joplin.owner, AclAction.List);

    return {
        items: await ctx.joplin.models.user().all(),
        has_more: false
    };
}

async (path: SubPath, ctx: AppContext) => {
    const user = await fetchUser(path, ctx);
    await ctx.joplin.models.user().checkIfAllowed(ctx.joplin.owner, AclAction.Delete, user);
    await ctx.joplin.models.user().delete(user.id);
}

async (path: SubPath, ctx: AppContext) => {
    const user = await fetchUser(path, ctx);

    const postedUser = {
        ...(await postedUserFromContext(ctx)),
        id: user.id
    };

    await ctx.joplin.models.user().checkIfAllowed(ctx.joplin.owner, AclAction.Update, postedUser);

    await ctx.joplin.models.user().save({
        id: user.id,
        ...postedUser
    });
}

async function localFileFromUrl(url: string): Promise<string> {
    const cssPluginAssets = "css/pluginAssets/";
    const jsPluginAssets = "js/pluginAssets/";

    if (url.indexOf(cssPluginAssets) === 0)
        return `${pluginAssetRootDir_}/${url.substr(cssPluginAssets.length)}`;

    if (url.indexOf(jsPluginAssets) === 0)
        return `${pluginAssetRootDir_}/${url.substr(jsPluginAssets.length)}`;

    return null;
}

async function initializeJoplinUtils(config: Config, models: Models, mustache: MustacheService) {
    models_ = models;
    baseUrl_ = config.baseUrl;
    mustache_ = mustache;
    const filePath = `${config.tempDir}/joplin.sqlite`;
    await fs.remove(filePath);
    db_ = new JoplinDatabase(new DatabaseDriverNode());

    await db_.open({
        name: filePath
    });

    BaseModel.setDb(db_);
    BaseItem.loadClass("Folder", Folder);
    BaseItem.loadClass("Note", Note);
    BaseItem.loadClass("Resource", Resource);
    BaseItem.loadClass("Tag", Tag);
    BaseItem.loadClass("NoteTag", NoteTag);
    BaseItem.loadClass("MasterKey", MasterKey);
    BaseItem.loadClass("Revision", Revision);
}

function linkedResourceIds(body: string): string[] {
    return Note.linkedItemIds(body);
}

function isJoplinItemName(name: string): boolean {
    return !!name.match(/^[0-9a-zA-Z]{32}\.md$/);
}

async function unserializeJoplinItem(body: string): Promise<any> {
    return BaseItem.unserialize(body);
}

async function serializeJoplinItem(item: any): Promise<string> {
    const ModelClass = BaseItem.itemClass(item);
    return ModelClass.serialize(item);
}

function resourceBlobPath(resourceId: string): string {
    return `${resourceDirName}/${resourceId}`;
}

function isJoplinResourceBlobPath(path: string): boolean {
    return path.indexOf(resourceDirName) === 0;
}

(relativeAssetPath: string) => {
    const resolvedPath = resolvePathWithinDir(pluginAssetRootDir_, relativeAssetPath);

    if (resolvedPath === null) {
        throw new ErrorForbidden("Disallowed access: Item is not in the plugin asset directory");
    }

    return resolvedPath;
}

async function localFileFromUrl(urlPath: string): Promise<string> {
    const cssPluginAssets = "css/pluginAssets/";
    const jsPluginAssets = "js/pluginAssets/";
    const baseUrls = [cssPluginAssets, jsPluginAssets];

    for (const baseUrl of baseUrls) {
        if (urlPath.startsWith(baseUrl)) {
            const pluginAssetPath = urlPath.substring(baseUrl.length);
            return resolveUnsafeAssetPath(pluginAssetPath);
        }
    }

    return null;
}

async function getResourceInfos(linkedItemInfos: LinkedItemInfos): Promise<ResourceInfos> {
    const output: Record<string, any> = {};

    for (const itemId of Object.keys(linkedItemInfos)) {
        const info = linkedItemInfos[itemId];

        if (info.item.type_ !== ModelType.Resource)
            continue;

        output[info.item.id] = {
            item: info.item,

            localState: {
                fetch_status: Resource.FETCH_STATUS_DONE
            }
        };
    }

    return output;
}

async function noteLinkedItemInfos(userId: Uuid, itemModel: ItemModel, noteBody: string): Promise<LinkedItemInfos> {
    const jopIds = await Note.linkedItemIds(noteBody);
    const output: LinkedItemInfos = {};

    for (const jopId of jopIds) {
        const item = await itemModel.loadByJopId(userId, jopId, {
            fields: ["*"],
            withContent: true
        });

        if (!item)
            continue;

        output[jopId] = {
            item: itemModel.itemToJoplinItem(item),
            file: null
        };
    }

    return output;
}

async function renderResource(userId: string, resourceId: string, item: Item, content: Buffer): Promise<FileViewerResponse> {
    let jopItem: any = null;

    try {
        const resourceItem = await models_.item().loadByJopId(userId, resourceId);
        jopItem = await models_.item().loadAsJoplinItem(resourceItem.id);
    } catch (error) {
        logger.error(
            `Could not load Joplin item ${resourceId} associated with item: ${item.id}`
        );
    }

    return {
        body: content,
        mime: jopItem ? jopItem.mime : item.mime_type,
        size: content ? content.byteLength : 0,
        filename: jopItem ? jopItem.title : ""
    };
}

async function renderNote(
    share: Share,
    note: NoteEntity,
    resourceInfos: ResourceInfos,
    linkedItemInfos: LinkedItemInfos
): Promise<FileViewerResponse> {
    const markupToHtml = new MarkupToHtml({
        ResourceModel: Resource as OptionsResourceModel
    });

    const renderOptions: any = {
        resources: resourceInfos,

        itemIdToUrl: (itemId: Uuid) => {
            if (!linkedItemInfos[itemId])
                return "#";

            const item = linkedItemInfos[itemId].item;

            if (!item)
                throw new Error(`No such item in this note: ${itemId}`);

            if (item.type_ === ModelType.Note) {
                return `${models_.share().shareUrl(share.owner_id, share.id)}?note_id=${item.id}&t=${item.updated_time}`;
            } else if (item.type_ === ModelType.Resource) {
                return `${models_.share().shareUrl(share.owner_id, share.id)}?resource_id=${item.id}&t=${item.updated_time}`;
            } else {
                logger.warn(`Unsupported type in share ${share.id}. Item: ${itemId}`);
                return "#";
            }
        },

        audioPlayerEnabled: false,
        videoPlayerEnabled: false,
        pdfViewerEnabled: false,
        checkboxDisabled: true,
        linkRenderingType: 2
    };

    const result = await markupToHtml.render(
        note.markup_language,
        note.body,
        themeStyle(Setting.THEME_LIGHT),
        renderOptions
    );

    const bodyHtml = await mustache_.renderView({
        cssFiles: ["items/note"],
        jsFiles: ["items/note"],
        name: "note",
        title: `${substrWithEllipsis(note.title, 0, 100)} - ${config().appName}`,
        titleOverride: true,
        path: "index/items/note",

        content: {
            note: {
                ...note,
                bodyHtml: result.html,
                updatedDateTime: formatDateTime(note.user_updated_time)
            },

            cssStrings: result.cssStrings.join("\n"),

            assetsJs: `
                const joplinNoteViewer = {
                    pluginAssets: ${JSON.stringify(result.pluginAssets)},
                    appBaseUrl: ${JSON.stringify(baseUrl_)},
                };
            `
        }
    }, {
        prefersDarkEnabled: false
    });

    return {
        body: bodyHtml,
        mime: "text/html",
        size: Buffer.byteLength(bodyHtml, "utf-8"),
        filename: ""
    };
}

function itemIsEncrypted(item: Item): boolean {
    if ("jop_encryption_applied" in item)
        return !!item.jop_encryption_applied;

    if (!("content" in item)) throw new Error(
