        id: accessTokenId,
        grantId: grantId,
        userId: userId,
        createdAt: now,
        expiresAt: accessTokenExpiresAt,
        wrappedEncryptionKey: accessTokenWrappedKey,

        grant: {
            clientId: grantData.clientId,
            scope: grantData.scope,
            encryptedProps: encryptedAccessTokenProps
