@bindThis
public async handle(
    request: FastifyRequest<{
        Querystring: {
            url: string;
            lang?: string;
        };
    }>,
    reply: FastifyReply
): Promise<object | undefined> {
    const url = request.query.url;

    if (typeof url !== "string") {
        reply.code(400);
        return;
    }

    const lang = request.query.lang;

    if (Array.isArray(lang)) {
        reply.code(400);
        return;
    }

    if (!this.meta.urlPreviewEnabled) {
        reply.code(403);

        return {
            error: new ApiError({
                message: "URL preview is disabled",
                code: "URL_PREVIEW_DISABLED",
                id: "58b36e13-d2f5-0323-b0c6-76aa9dabefb8"
            })
        };
    }

    this.logger.info(
        this.meta.urlPreviewSummaryProxyUrl ? `(Proxy) Getting preview of ${url}@${lang} ...` : `Getting preview of ${url}@${lang} ...`
    );

    try {
        const summary = this.meta.urlPreviewSummaryProxyUrl ? await this.fetchSummaryFromProxy(url, this.meta, lang) : await this.fetchSummary(url, this.meta, lang);
        this.logger.succ(`Got preview of ${url}: ${summary.title}`);

        if (!(summary.url.startsWith("http://") || summary.url.startsWith("https://"))) {
            throw new Error("unsupported schema included");
        }

        if (summary.player.url && !(summary.player.url.startsWith("http://") || summary.player.url.startsWith("https://"))) {
            throw new Error("unsupported schema included");
        }

        summary.icon = this.wrap(summary.icon);
        summary.thumbnail = this.wrap(summary.thumbnail);
        reply.header("Cache-Control", "max-age=604800, immutable");
        return summary;
    } catch (err) {
        this.logger.warn(`Failed to get preview of ${url}: ${err}`);
        reply.code(422);
        reply.header("Cache-Control", "max-age=86400, immutable");

        return {
            error: new ApiError({
                message: "Failed to get preview",
                code: "URL_PREVIEW_FAILED",
                id: "09d01cb5-53b9-4856-82e5-38a50c290a3b"
            })
        };
    }
}

private fetchSummary(url: string, meta: MiMeta, lang?: string): Promise<SummalyResult> {
