        getCertFromKeyInfo: getKeyFn(options)
    });

    return sig;
}

validateSignature(str, options, callback) {
    const xml = utils.parseSamlResponse(str, this.parser);
    const signaturePath = this.options.signaturePath || options.signaturePath;
    const signatures = xpath.select(signaturePath, xml);

    if (signatures.length === 0) {
        return callback(new Error("Signature is missing (xpath: " + signaturePath + ")"));
    } else if (signatures.length > 1) {
        return callback(
            new Error("Signature was found more than one time (xpath: " + signaturePath + ")")
        );
    }

    const signature = signatures[0];
    let valid;

    const opts = Object.assign({}, options, {
        cert: this.options.cert,
        thumbprints: this.options.thumbprints
    });

    const sig = this.buildSignatureValidator(opts);

    try {
        sig.loadSignature(signature);
        valid = sig.checkSignature(utils.crlf2lf(str));

        if (!this.extractAndValidateCertExpiration(xml, this.options.cert) && this.options.checkCertExpiration) {
            return callback(new Error("The signing certificate is not currently valid."), null);
        }
    } catch (e) {
        if (e.message === "PEM_read_bio_PUBKEY failed") {
            return callback(new Error("The signing certificate is invalid (" + e.message + ")"));
        }

        if (e.opensslErrorStack !== undefined) {
            const err = new Error(`The signing certificate is invalid (${e.opensslErrorStack.join(", ")})`);
            err.originalError = e;
            return callback(err);
        }

        return callback(e);
    }

    if (!valid) {
        return callback(
            new Error("Signature check errors: " + sig.references[0].validationError.message)
        );
    }

    if (!sig.getSignedReferences().length) {
        return callback(new Error("Could not validate Signature(s)"));
    }

    return callback(null, sig.getSignedReferences()[0]);
}

extractAndValidateCertExpiration(validatedSamlAssertion, optionsCert) {
    const certNodes = validatedSamlAssertion.getElementsByTagNameNS("http://www.w3.org/2000/09/xmldsig#", "X509Certificate");
    const cert = certNodes.length > 0 ? certNodes[0].textContent : optionsCert;

    if (!cert) {
        return false;
    }

    const parsedCert = forge.pki.certificateFromPem(utils.certToPEM(cert));
    const nowDate = new Date();

    if (!(nowDate > parsedCert.validity.notBefore && nowDate < parsedCert.validity.notAfter)) {
        this.eventEmitter.emit("certificateExpirationValidationFailed", {});
        return false;
    }

    return true;
}

validateExpiration(samlAssertion) {
    const conditions = xpath.select(
        "//*[local-name(.)='Assertion'][1]/*[local-name(.)='Conditions']",
        samlAssertion
    );

    if (!conditions || conditions.length === 0) {
        return true;
    }

    const condition = conditions[0];
    const notBefore = condition.getAttribute("NotBefore");
    const notOnOrAfter = condition.getAttribute("NotOnOrAfter");

    if (!notBefore && !notOnOrAfter) {
        return true;
    }

    const now = new Date();

    if (notBefore) {
        const notBeforeDate = new Date(notBefore);
        notBeforeDate.setMinutes(notBeforeDate.getMinutes() - this.options.clockSkew);

        if (now < notBefore) {
            return false;
        }
    }

    if (notOnOrAfter) {
        const notOnOrAfterDate = new Date(notOnOrAfter);
        notOnOrAfterDate.setMinutes(notOnOrAfterDate.getMinutes() + this.options.clockSkew);

        if (now > notOnOrAfterDate) {
            return false;
        }
    }

    return true;
}

validateAudience(samlAssertion, realm, version) {
    let audience;

    if (version === "2.0") {
        audience = xpath.select(
            "//*[local-name(.)='Assertion'][1]/*[local-name(.)='Conditions']/*[local-name(.)='AudienceRestriction']/*[local-name(.)='Audience']",
            samlAssertion
        );
    } else {
        audience = xpath.select(
            "//*[local-name(.)='Assertion'][1]/*[local-name(.)='Conditions']/*[local-name(.)='AudienceRestrictionCondition']/*[local-name(.)='Audience']",
            samlAssertion
        );
    }

    if (!audience || audience.length === 0) {
        return false;
    }

    return utils.stringCompare(audience[0].textContent, realm);
}

validateNameQualifier(samlAssertion, issuer) {
    const nameID = getNameID20(samlAssertion);

    if (!nameID || !nameID.Format || !nameID.NameQualifier) {
        return true;
    }

    if ([
        "urn:oasis:names:tc:SAML:2.0:nameid-format:persistent",
        "urn:oasis:names:tc:SAML:2.0:nameid-format:transient"
    ].indexOf(nameID.Format) === -1) {
        return true;
    }

    return nameID.NameQualifier === issuer;
}

validateSPNameQualifier(samlAssertion, audience) {
    const nameID = getNameID20(samlAssertion);

    if (!nameID || !nameID.Format || !nameID.SPNameQualifier) {
        return true;
    }

    if ([
        "urn:oasis:names:tc:SAML:2.0:nameid-format:persistent",
        "urn:oasis:names:tc:SAML:2.0:nameid-format:transient"
    ].indexOf(nameID.Format) === -1) {
        return true;
    }

    return nameID.SPNameQualifier === audience;
}

validateRecipient(samlAssertion, recipientUrl) {
    const subjectConfirmationData = xpath.select(
        "//*[local-name(.)='Assertion'][1]/*[local-name(.)='Subject']/*[local-name(.)='SubjectConfirmation']/*[local-name(.)='SubjectConfirmationData']",
        samlAssertion
    );

    if (!subjectConfirmationData || subjectConfirmationData.length === 0) {
        return true;
    }

    const recipient = subjectConfirmationData[0].getAttribute("Recipient");
    const valid = !recipient || recipient === recipientUrl;

    if (!valid) {
        this.eventEmitter.emit("recipientValidationFailed", {
            configuredRecipient: recipientUrl,
            assertionRecipient: recipient
        });
    }

    return valid;
}

parseAttributes(samlAssertion, version) {
    const profile = {};
    const attributes = getAttributes(samlAssertion);
    profile.sessionIndex = getSessionIndex(samlAssertion);

    if (version === "2.0") {
        for (const index in attributes) {
            const attribute = attributes[index];
            profile[attribute.getAttribute("Name")] = getAttributeValues(attribute);
        }

        const nameId = getNameID20(samlAssertion);

        if (nameId) {
            profile["http://schemas.xmlsoap.org/ws/2005/05/identity/claims/nameidentifier"] = nameId.value;

            if (Object.keys(nameId).length > 1) {
                profile["nameIdAttributes"] = nameId;
            }
        }

        const authContext = getAuthContext20(samlAssertion);

        if (authContext) {
            profile["http://schemas.microsoft.com/ws/2008/06/identity/claims/authenticationmethod"] = authContext;
        }
    } else {
        if (attributes) {
            for (const index in attributes) {
                const attribute = attributes[index];
                profile[attribute.getAttribute("AttributeNamespace") + "/" + attribute.getAttribute("AttributeName")] = getAttributeValues(attribute);
            }
        }

        const nameId = getNameID11(samlAssertion);

        if (nameId) {
            profile["http://schemas.xmlsoap.org/ws/2005/05/identity/claims/nameidentifier"] = typeof nameId === "string" ? nameId : nameId["#"];
        }
    }

    return profile;
}

validateSamlAssertion(samlAssertionStr, options, callback) {
    this.validateSignature(samlAssertionStr, {
        meta: options.meta,
        signaturePath: "//*[local-name(.)='Assertion'][1]/*[local-name(.)='Signature' and namespace-uri(.)='http://www.w3.org/2000/09/xmldsig#']"
    }, (err, signed) => {
        if (err) {
            return callback(err);
        }

        this.parseAssertion(signed, callback);
    });
}

parseAssertion(samlAssertion, callback) {
    if (this.options.extractSAMLAssertion) {
        samlAssertion = this.options.extractSAMLAssertion(samlAssertion);
    }

    samlAssertion = utils.parseSamlAssertion(samlAssertion, this.parser);

    if (!samlAssertion.getAttribute) {
        samlAssertion = samlAssertion.documentElement;
    }

    if (samlAssertion.localName !== "Assertion") {
        return callback(new Error("saml response does not contain an Assertion element"));
    }

    const version = utils.getSamlAssertionVersion(samlAssertion);

    if (!version) {
        return callback(new Error("SAML Assertion version not supported, or not defined"), null);
    }

    if (this.options.checkExpiration && !this.validateExpiration(samlAssertion, version)) {
        return callback(new Error("assertion has expired."), null);
    }

    if (this.options.checkAudience && !this.validateAudience(samlAssertion, this.options.realm, version)) {
        return callback(new Error("Audience is invalid. Configured: " + this.options.realm), null);
    }

    if (!this.validateRecipient(samlAssertion, this.options.recipientUrl)) {
        if (this.options.checkRecipient) {
            return callback(
                new Error("Recipient is invalid. Configured: " + this.options.recipientUrl),
                null
            );
        }
    }

    const profile = this.parseAttributes(samlAssertion, version);
    let issuer;

    if (version === "2.0") {
        const issuerNode = xpath.select(
            "//*[local-name(.)='Assertion'][1]/*[local-name(.)='Issuer']",
            samlAssertion
        );

        if (issuerNode.length > 0) {
            issuer = issuerNode[0].textContent;
        }
    } else {
        issuer = samlAssertion.getAttribute("Issuer");
    }

    this.eventEmitter.emit("parseAssertion", {
        issuer: issuer,
        version: version
    });

    profile.issuer = issuer;

    if (this.options.checkNameQualifier && !this.validateNameQualifier(samlAssertion, issuer)) {
        return callback(
            new Error("NameQualifier attribute in the NameID element does not match " + issuer),
            null
        );
    }

    if (this.options.checkSPNameQualifier && !this.validateSPNameQualifier(samlAssertion, this.options.realm)) {
        return callback(new Error(
            "SPNameQualifier attribute in the NameID element does not match " + this.options.realm
        ), null);
    }

    if (!profile.email && profile["http://schemas.xmlsoap.org/ws/2005/05/identity/claims/emailaddress"]) {
        profile.email = profile["http://schemas.xmlsoap.org/ws/2005/05/identity/claims/emailaddress"];
    }

    return callback(null, profile);
}

(
    req: Request,
    opts?: {
        proxyBasePath?: string;
    }
): string => {
    const base = (req as any).base || "";
    return `http://0.0.0.0:${req.params.port}${opts?.proxyBasePath || ""}/${req.originalUrl.slice(base.length)}`;
}

(
    req: Request,
    opts?: {
        proxyBasePath?: string;
    }
): string => {
    const base = (req as any).base || "";
    let port: number;

    try {
        port = parseInt(req.params.port, 10);
    } catch (err) {
        throw new HttpError("Invalid port", HttpCode.BadRequest);
    }

    return `http://0.0.0.0:${port}${opts?.proxyBasePath || ""}/${req.originalUrl.slice(base.length)}`;
}

async function proxy(
    req: Request,
    res: Response,
    opts?: {
        passthroughPath?: boolean;
        proxyBasePath?: string;
    }
): Promise<void> {
    ensureProxyEnabled(req);

    if (req.method === "OPTIONS" && req.args["skip-auth-preflight"])
        {} else if (!(await authenticated(req))) {
        if (!req.params.path || req.params.path === "/") {
            const to = self(req);

            return redirect(req, res, "login", {
                to: to !== "/" ? to : undefined
            });
        }

        throw new HttpError("Unauthorized", HttpCode.Unauthorized);
    }

    if (!opts?.passthroughPath) {
        (req as any).base = req.path.split(path.sep).slice(0, 3).join(path.sep);
    }

    _proxy.web(req, res, {
        ignorePath: true,
        target: getProxyTarget(req, opts)
    });
}

async function wsProxy(
    req: WebsocketRequest,
    opts?: {
        passthroughPath?: boolean;
        proxyBasePath?: string;
    }
): Promise<void> {
    ensureProxyEnabled(req);
    ensureOrigin(req);
    await ensureAuthenticated(req);

    if (!opts?.passthroughPath) {
        (req as any).base = req.path.split(path.sep).slice(0, 3).join(path.sep);
    }

    _proxy.ws(req, req.ws, req.head, {
        ignorePath: true,
        target: getProxyTarget(req, opts)
    });
}

private enforceTextSemantics(
    semantics: ISemanticsEntry,
    params: any,
    parentParams: any,
    jsonPath: string
): void {
    log.debug("Checking contents of text entry");
    let newText: string = params;

    if (!newText) {
        newText = "";
    }

    if (semantics.tags) {
        let allowedTags = ["div", "span", "p", "br", ...semantics.tags];

        if (allowedTags.includes("table")) {
            allowedTags = [
                ...allowedTags,
                "tr",
                "td",
                "th",
                "colgroup",
                "thead",
                "tbody",
                "tfoot",
                "caption"
            ];
        }

        if (allowedTags.includes("strong")) {
            allowedTags.push("b");
        } else if (allowedTags.includes("b")) {
            allowedTags.push("strong");
        }

        if (allowedTags.includes("em")) {
            allowedTags.push("i");
        } else if (allowedTags.includes("i")) {
            allowedTags.push("em");
        }

        if (allowedTags.includes("ul") || allowedTags.includes("ol")) {
            allowedTags.push("li");
        }

        if (allowedTags.includes("del") || allowedTags.includes("strike")) {
            allowedTags.push("s");
        }

        const uniqueTags = new Set<string>(allowedTags);
        uniqueTags.delete("script");
        uniqueTags.delete("style");
        uniqueTags.delete("textarea");
        uniqueTags.delete("option");
        allowedTags = Array.from(uniqueTags);

        const allowedStyles = {
            "text-align": [/^(center|left|right|justify)$/i]
        };

        if (semantics.font) {
            if (semantics.font.size) {
                allowedStyles["font-size"] = [/^[0-9.]+(em|px|%)$/i];
            }

            if (semantics.font.family) {
                allowedStyles["font-family"] = [/^[-a-z0-9," ]+$/i];
            }

            if (semantics.font.color) {
                allowedStyles["color"] = [/^(#[a-f0-9]{3}[a-f0-9]{3}?|rgba?\([0-9, ]+\))$/i];
            }

            if (semantics.font.background) {
                allowedStyles["background-color"] = [/^(#[a-f0-9]{3}[a-f0-9]{3}?|rgba?\([0-9, ]+\))$/i];
            }

            if (semantics.font.spacing) {
                allowedStyles["spacing"] = [/^[0-9.]+(em|px|%)$/i];
            }

            if (semantics.font.height) {
                allowedStyles["line-height"] = [/^[0-9.]+(em|px|%)$/i];
            }
        }

        const tableCellStyle = allowedTags.includes("table") ? {
            "white-space": [/^(nowrap)|(normal)|(pre)$/i],
            "text-align": [/^(center|left|right|justify)$/i],
            "vertical-align": [/^(baseline)|(text-top)|(text-bottom)|(sub)|(super)$/i],
            height: [/^[0-9.]+(em|px|%)$/i],
            width: [/^[0-9.]+(em|px|%)$/i],
            "background-color": [/^(#[a-f0-9]{3}[a-f0-9]{3}?|rgba?\([0-9, ]+\))$/i],
            "border-color": [/^(#[a-f0-9]{3}[a-f0-9]{3}?|rgba?\([0-9, ]+\))$/i]
        } : undefined;

        log.debug("Filtering out disallowed HTML tags");

        newText = sanitizeHtml(newText, {
            allowedTags,

            allowedAttributes: {
                "*": ["style"],
                a: ["href", "hreflang", "media", "rel", "target"],
                td: ["colspan", "rowspan", "headers"],
                th: ["colspan", "rowspan", "headers", "scope"],
                ol: ["start", "reversed"],
                table: ["summary", "cellspacing", "cellpadding", "border", "align"]
            },

            allowedStyles: {
                "*": allowedStyles,

                table: allowedTags.includes("table") ? {
                    height: [/^[0-9.]+(em|px|%)$/i],
                    width: [/^[0-9.]+(em|px|%)$/i]
                } : undefined,

                td: tableCellStyle,
                th: tableCellStyle
            }
        });
    }

    if (semantics.maxLength && newText.length > semantics.maxLength) {
        log.debug("Clipping string that is too long");
        newText = newText.substring(0, semantics.maxLength);
    }

    if (newText !== "" && semantics.optional && semantics.regexp) {
        const regexp = new RegExp(semantics.regexp.pattern, semantics.regexp.modifiers);

        if (!regexp.test(newText)) {
            log.debug(
                `Provided string does not conform to regexp in semantics (value: ${newText}, regexp: ${semantics.regexp})`
            );

            newText = "";
        }
    }

    parentParams[semantics.name] = newText;
}

constructor(libraryManager: LibraryManager) {
    log.info("initialize");
    this.contentScanner = new ContentScanner(libraryManager);
}

public async enforceSemanticStructure(mainParams: any, mainLibraryName: ILibraryName): Promise<void> {
    log.debug("Starting to enforcing semantic structure.");

    await this.contentScanner.scanContent(
        mainParams,
        mainLibraryName,
        (semantics, params, jsonPath, parentParams) => {
            let deleteMe = false;

            if (semantics.type === "library") {
                const result = this.enforceLibrarySemantics(semantics, params, parentParams, jsonPath);
                deleteMe = result.deleteMe;
            } else if (semantics.type === "text") {
                this.enforceTextSemantics(semantics, params, parentParams, jsonPath);
            }

            if (deleteMe) {
                log.debug(`Enforcing library semantics by deleting params path ${jsonPath}.`);
                delete parentParams[semantics.name];
                return true;
            }

            return false;
        }
    );
}

private enforceLibrarySemantics(
    semantics: ISemanticsEntry,
    params: any,
    parentParams: any,
    jsonPath: string
): {
    deleteMe: boolean;
} {
    log.debug("Enforcing structure of a library element.");
    let deleteMe: boolean;

    if (!params.library) {
        log.debug(
            `Found a library entry without a library property (${jsonPath}). Marking it for deletion.`
        );

        deleteMe = true;
    } else {
        const allowedLibraries = semantics.options?.map(o => (typeof o === "string" ? o : o.name))?.filter(o => o);

        if (!allowedLibraries || !allowedLibraries.includes(params.library)) {
            log.debug(
                `Library check: Found a library entry with a library that is not specified in the options. Allowed are: ${allowedLibraries.join(", ")}. Library is set to: ${params.library} (${jsonPath}).`
            );

            deleteMe = true;
        }
    }

    return {
        deleteMe
    };
}

